#[inline]
fn p2p_inbound_newtx_should_drop_before_admission_v1(tx: &Transaction) -> bool {
    // Peer-gossiped coinbase TXs are invalid before any signature, chain-state,
    // mempool, or relay work. This keeps malformed peers from turning a correct
    // reject into CPU-visible admission work.
    tx.is_coinbase
}

