//   StateSync Supervisor integration (trigger-only; wiring happens in main.rs)
// ======================================================================================

static STATE_SYNC_SUPERVISOR_HANDLE: OnceLock<Mutex<Option<StateSyncSupervisorHandle>>> =
    OnceLock::new();

/// Register the StateSync supervisor handle (called once at startup).
/// Safe to call multiple times: the latest handle wins.
pub fn set_state_sync_supervisor_handle(handle: StateSyncSupervisorHandle) {
    let cell = STATE_SYNC_SUPERVISOR_HANDLE.get_or_init(|| Mutex::new(None));
    let mut g = cell.lock().unwrap_or_else(|e| e.into_inner());
    *g = Some(handle);
}

#[cfg(test)]
fn clear_state_sync_supervisor_handle_for_tests() {
    let cell = STATE_SYNC_SUPERVISOR_HANDLE.get_or_init(|| Mutex::new(None));
    let mut g = cell.lock().unwrap_or_else(|e| e.into_inner());
    *g = None;
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum StateSyncTriggerAuthorizationV246 {
    /// Peer-driven state sync: source peer is explicitly bound, Operational, ahead of local tip,
    /// and the StateSyncReason carries height/source hints matching that same peer.
    OperationalPeerBound,
    /// V287 catch-up-only peer driven state sync: source peer is explicitly bound
    /// and validated as a data recovery source, but is not counted as quorum,
    /// mining readiness, proposal or finality authority.
    CatchupPeerBound,
    /// Local-consensus wedged escalation: allowed only after the dedicated local retry blocker
    /// has been re-checked against an Operational source peer.
    LocalConsensusWedgedBound,
    /// Legacy V195 trigger is intentionally limited to regression tests so production code cannot
    /// arm state-sync from a raw/global peer height.
    #[cfg(test)]
    LegacySnapshotPriorityV195TestOnly,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum LocalConsensusWedgedStateSyncPermitV246 {
    /// Permit produced by the caller only after local_consensus_wedged_source_operational_bound_v245
    /// has accepted the retry blocker against an Operational source peer.
    OperationalSourceBound,
}

#[inline]
fn statesync_trigger_authorization_label_v246(
    authorization: StateSyncTriggerAuthorizationV246,
) -> &'static str {
    match authorization {
        StateSyncTriggerAuthorizationV246::OperationalPeerBound => "operational_peer_bound",
        StateSyncTriggerAuthorizationV246::CatchupPeerBound => "catchup_peer_bound_v287",
        StateSyncTriggerAuthorizationV246::LocalConsensusWedgedBound => {
            "local_consensus_wedged_bound"
        }
        #[cfg(test)]
        StateSyncTriggerAuthorizationV246::LegacySnapshotPriorityV195TestOnly => {
            "legacy_snapshot_priority_v195_test_only"
        }
    }
}

#[inline]
fn statesync_trigger_authorization_reason_check_v246(
    reason: &StateSyncReason,
    authorization: StateSyncTriggerAuthorizationV246,
) -> Result<(), &'static str> {
    match authorization {
        StateSyncTriggerAuthorizationV246::OperationalPeerBound => match reason {
            StateSyncReason::GapStall {
                local_height: Some(local_height),
                peer_height: Some(peer_height),
                ..
            } if peer_height > local_height => Ok(()),
            StateSyncReason::NoOverlap { peer: Some(peer) } if !peer.trim().is_empty() => Ok(()),
            StateSyncReason::NoOverlap { peer: Some(_) } => {
                Err("operational_peer_bound_no_overlap_empty_peer")
            }
            StateSyncReason::GapStall {
                local_height: None, ..
            }
            | StateSyncReason::GapStall {
                peer_height: None, ..
            } => Err("operational_peer_bound_gap_stall_missing_height_hints"),
            StateSyncReason::GapStall { .. } => {
                Err("operational_peer_bound_gap_stall_source_not_ahead")
            }
            StateSyncReason::NoOverlap { peer: None } => {
                Err("operational_peer_bound_no_overlap_missing_peer")
            }
            StateSyncReason::LocalConsensusWedged { .. } => {
                Err("local_consensus_wedged_requires_dedicated_authorization")
            }
            StateSyncReason::Manual { .. } => Err("manual_not_allowed_from_peer_bound_path"),
        },
        StateSyncTriggerAuthorizationV246::CatchupPeerBound => match reason {
            StateSyncReason::GapStall {
                local_height: Some(local_height),
                peer_height: Some(peer_height),
                ..
            } if peer_height > local_height => Ok(()),
            StateSyncReason::NoOverlap { peer: Some(peer) } if !peer.trim().is_empty() => Ok(()),
            StateSyncReason::NoOverlap { peer: Some(_) } => {
                Err("catchup_peer_bound_no_overlap_empty_peer")
            }
            StateSyncReason::GapStall {
                local_height: None, ..
            }
            | StateSyncReason::GapStall {
                peer_height: None, ..
            } => Err("catchup_peer_bound_gap_stall_missing_height_hints"),
            StateSyncReason::GapStall { .. } => Err("catchup_peer_bound_source_not_ahead"),
            StateSyncReason::NoOverlap { peer: None } => {
                Err("catchup_peer_bound_no_overlap_missing_peer")
            }
            StateSyncReason::LocalConsensusWedged { .. } => {
                Err("local_consensus_wedged_requires_dedicated_authorization")
            }
            StateSyncReason::Manual { .. } => Err("manual_not_allowed_from_catchup_peer_path"),
        },
        StateSyncTriggerAuthorizationV246::LocalConsensusWedgedBound => match reason {
            StateSyncReason::LocalConsensusWedged { .. } => Ok(()),
            StateSyncReason::GapStall { .. } => {
                Err("gap_stall_requires_operational_peer_bound_authorization")
            }
            StateSyncReason::NoOverlap { .. } => {
                Err("no_overlap_requires_operational_peer_bound_authorization")
            }
            StateSyncReason::Manual { .. } => Err("manual_not_allowed_from_local_consensus_path"),
        },
        #[cfg(test)]
        StateSyncTriggerAuthorizationV246::LegacySnapshotPriorityV195TestOnly => match reason {
            StateSyncReason::GapStall {
                local_height: Some(local_height),
                peer_height: Some(peer_height),
                ..
            } if peer_height > local_height => Ok(()),
            StateSyncReason::GapStall { .. } => {
                Err("legacy_v195_test_only_requires_structured_ahead_gap")
            }
            StateSyncReason::NoOverlap { .. } => Err("legacy_v195_test_only_rejects_no_overlap"),
            StateSyncReason::LocalConsensusWedged { .. } => {
                Err("legacy_v195_test_only_rejects_local_consensus_wedged")
            }
            StateSyncReason::Manual { .. } => Err("legacy_v195_test_only_rejects_manual"),
        },
    }
}

#[inline]
fn statesync_trigger_authorized_v246(
    reason: StateSyncReason,
    authorization: StateSyncTriggerAuthorizationV246,
) -> bool {
    if let Err(suppressed_reason) =
        statesync_trigger_authorization_reason_check_v246(&reason, authorization)
    {
        ng_warn_throttle!(
            key: format!(
                "statesync_trigger_suppressed_authorization_reason_v246_{}_{}",
                statesync_trigger_authorization_label_v246(authorization),
                suppressed_reason
            ),
            every_ms: 5_000,
            target: "p2p.sync",
            "event=statesync_trigger_suppressed_v246 authorization={} reason={} state_sync_reason={:?}",
            statesync_trigger_authorization_label_v246(authorization),
            suppressed_reason,
            reason,
        );
        return false;
    }

    let Some(cell) = STATE_SYNC_SUPERVISOR_HANDLE.get() else {
        return false;
    };
    let g = cell.lock().unwrap_or_else(|e| e.into_inner());
    if let Some(handle) = g.as_ref() {
        return handle.trigger(reason);
    }
    false
}

#[inline]
fn statesync_trigger_verified_operational_peer_bound_v246(reason: StateSyncReason) -> bool {
    statesync_trigger_authorized_v246(
        reason,
        StateSyncTriggerAuthorizationV246::OperationalPeerBound,
    )
}

#[inline]
fn statesync_trigger_verified_catchup_peer_bound_v287(reason: StateSyncReason) -> bool {
    statesync_trigger_authorized_v246(reason, StateSyncTriggerAuthorizationV246::CatchupPeerBound)
}

#[inline]
fn statesync_trigger_verified_local_consensus_wedged_v246(reason: StateSyncReason) -> bool {
    statesync_trigger_authorized_v246(
        reason,
        StateSyncTriggerAuthorizationV246::LocalConsensusWedgedBound,
    )
}

