fn local_consensus_fault_class_str(
    class: &crate::blockchain::LocalConsensusBootstrapFaultClass,
) -> &'static str {
    match class {
        crate::blockchain::LocalConsensusBootstrapFaultClass::SnapshotContextInvalid => {
            "snapshot_context_invalid"
        }
        crate::blockchain::LocalConsensusBootstrapFaultClass::HistoricalStateUnavailable => {
            "historical_state_unavailable"
        }
        crate::blockchain::LocalConsensusBootstrapFaultClass::ResolutionFallback => {
            "resolution_fallback"
        }
        crate::blockchain::LocalConsensusBootstrapFaultClass::CommitteeEmpty => "committee_empty",
        crate::blockchain::LocalConsensusBootstrapFaultClass::ExpectedProposerFailed => {
            "expected_proposer_failed"
        }
        crate::blockchain::LocalConsensusBootstrapFaultClass::PreconditionMissing => {
            "precondition_missing"
        }
    }
}

const SNAPSHOT_PRIORITY_LARGE_GAP_BLOCKS_V191: u64 = 1024;
const SNAPSHOT_PRIORITY_LOCAL_HEIGHT_CUTOFF_V191: u64 = 1024;
const SNAPSHOT_PRIORITY_OPERATOR_FALLBACK_MAX_GAP_BLOCKS_V192: u64 = 4096;
// V194: dirty/partial bootstrap databases can legitimately be above the
// original cold-start cutoff (for example a failed replay from genesis may
// leave B around height 3_252 while the cluster is around 39_446).  Treat
// those low partial chains, and any very large gap, as snapshot-priority so
// RestartCatchup cannot continue a hidden block-by-block replay.
const SNAPSHOT_PRIORITY_DIRTY_LOW_HEIGHT_CUTOFF_V194: u64 =
    SNAPSHOT_PRIORITY_OPERATOR_FALLBACK_MAX_GAP_BLOCKS_V192;
const SNAPSHOT_PRIORITY_FORCE_SNAPSHOT_GAP_BLOCKS_V194: u64 =
    SNAPSHOT_PRIORITY_OPERATOR_FALLBACK_MAX_GAP_BLOCKS_V192;

fn env_truthy_v192(name: &str) -> bool {
    std::env::var(name)
        .ok()
        .map(|v| {
            let t = v.trim();
            t == "1"
                || t.eq_ignore_ascii_case("true")
                || t.eq_ignore_ascii_case("yes")
                || t.eq_ignore_ascii_case("on")
        })
        .unwrap_or(false)
}

fn large_gap_block_fallback_explicitly_allowed_v191() -> bool {
    env_truthy_v192("NEWGEN_ALLOW_LARGE_GAP_BLOCK_FALLBACK")
}

fn unbounded_large_gap_block_fallback_explicitly_allowed_v192() -> bool {
    env_truthy_v192("NEWGEN_ALLOW_UNBOUNDED_LARGE_GAP_BLOCK_FALLBACK")
}

fn snapshot_priority_gap_v192(local_height: u64, peer_height: u64) -> u64 {
    peer_height.saturating_sub(local_height)
}

fn snapshot_priority_large_gap_pending_v192(
    boot_phase: P2pBootPhase,
    local_height: u64,
    peer_height: u64,
) -> bool {
    if !matches!(
        boot_phase,
        P2pBootPhase::RestartCatchup | P2pBootPhase::FallbackLiveSync
    ) {
        return false;
    }

    let gap = snapshot_priority_gap_v192(local_height, peer_height);
    if gap < SNAPSHOT_PRIORITY_LARGE_GAP_BLOCKS_V191 {
        return false;
    }

    // V194: protect both truly clean/early chains and dirty-low chains left by
    // a partial replay. Also force snapshot priority for any very large gap,
    // regardless of local height, because that is exactly where block replay
    // becomes operationally expensive and masks snapshot regressions.
    local_height <= SNAPSHOT_PRIORITY_DIRTY_LOW_HEIGHT_CUTOFF_V194
        || gap >= SNAPSHOT_PRIORITY_FORCE_SNAPSHOT_GAP_BLOCKS_V194
}

fn snapshot_priority_operator_fallback_allowed_with_policy_v192(
    boot_phase: P2pBootPhase,
    local_height: u64,
    peer_height: u64,
    large_gap_block_fallback_allowed: bool,
    unbounded_large_gap_block_fallback_allowed: bool,
) -> bool {
    if !snapshot_priority_large_gap_pending_v192(boot_phase, local_height, peer_height) {
        return false;
    }
    if !large_gap_block_fallback_allowed {
        return false;
    }
    unbounded_large_gap_block_fallback_allowed
        || snapshot_priority_gap_v192(local_height, peer_height)
            <= SNAPSHOT_PRIORITY_OPERATOR_FALLBACK_MAX_GAP_BLOCKS_V192
}

fn snapshot_priority_operator_fallback_allowed_v192(
    boot_phase: P2pBootPhase,
    local_height: u64,
    peer_height: u64,
) -> bool {
    snapshot_priority_operator_fallback_allowed_with_policy_v192(
        boot_phase,
        local_height,
        peer_height,
        large_gap_block_fallback_explicitly_allowed_v191(),
        unbounded_large_gap_block_fallback_explicitly_allowed_v192(),
    )
}

fn snapshot_priority_blocks_live_block_sync_with_policy_v192(
    boot_phase: P2pBootPhase,
    local_height: u64,
    peer_height: u64,
    large_gap_block_fallback_allowed: bool,
    unbounded_large_gap_block_fallback_allowed: bool,
) -> bool {
    if matches!(boot_phase, P2pBootPhase::ColdStartSnapshot) {
        return true;
    }
    if !snapshot_priority_large_gap_pending_v192(boot_phase, local_height, peer_height) {
        return false;
    }
    !snapshot_priority_operator_fallback_allowed_with_policy_v192(
        boot_phase,
        local_height,
        peer_height,
        large_gap_block_fallback_allowed,
        unbounded_large_gap_block_fallback_allowed,
    )
}

fn snapshot_priority_blocks_live_block_sync_with_policy_v191(
    boot_phase: P2pBootPhase,
    local_height: u64,
    peer_height: u64,
    large_gap_block_fallback_allowed: bool,
) -> bool {
    snapshot_priority_blocks_live_block_sync_with_policy_v192(
        boot_phase,
        local_height,
        peer_height,
        large_gap_block_fallback_allowed,
        false,
    )
}

fn snapshot_priority_blocks_live_block_sync_v192(
    boot_phase: P2pBootPhase,
    local_height: u64,
    peer_height: u64,
) -> bool {
    snapshot_priority_blocks_live_block_sync_with_policy_v192(
        boot_phase,
        local_height,
        peer_height,
        large_gap_block_fallback_explicitly_allowed_v191(),
        unbounded_large_gap_block_fallback_explicitly_allowed_v192(),
    )
}

fn snapshot_priority_blocks_live_block_sync_v191(
    boot_phase: P2pBootPhase,
    local_height: u64,
    peer_height: u64,
) -> bool {
    snapshot_priority_blocks_live_block_sync_v192(boot_phase, local_height, peer_height)
}

fn deferred_block_retry_allowed_v192(
    active_local_sync_retry_block: bool,
    state_sync_recovery_pending: bool,
    snapshot_priority_blocked: bool,
) -> bool {
    !(active_local_sync_retry_block || state_sync_recovery_pending || snapshot_priority_blocked)
}

fn rr_catchup_allowed(
    active_local_sync_retry_block: bool,
    state_sync_recovery_pending: bool,
    sync_in_flight: bool,
    snapshot_priority_blocked: bool,
) -> bool {
    !(active_local_sync_retry_block
        || state_sync_recovery_pending
        || sync_in_flight
        || snapshot_priority_blocked)
}

fn snapshot_priority_should_trigger_state_sync_recovery_v195(
    state_sync_pending: bool,
    boot_phase: P2pBootPhase,
    local_height: u64,
    peer_height: u64,
) -> bool {
    !state_sync_pending
        && snapshot_priority_blocks_live_block_sync_v192(boot_phase, local_height, peer_height)
}

#[cfg(test)]
fn snapshot_priority_trigger_state_sync_recovery_v195(
    tracker: &mut CatchupProgressTracker,
    boot_phase: P2pBootPhase,
    local_height: u64,
    peer_height: u64,
    path: &str,
    peer: Option<&PeerId>,
) -> bool {
    if !snapshot_priority_blocks_live_block_sync_v192(boot_phase, local_height, peer_height) {
        return false;
    }

    if !snapshot_priority_should_trigger_state_sync_recovery_v195(
        tracker.state_sync_pending(),
        boot_phase,
        local_height,
        peer_height,
    ) {
        return true;
    }

    let gap = snapshot_priority_gap_v192(local_height, peer_height);
    let blocked_next_height = peer_height.max(local_height.saturating_add(1));
    let peer_label = peer
        .map(|p| p.to_string())
        .unwrap_or_else(|| "none".to_string());
    let detail = format!(
        "snapshot_priority_required path={} local_height={} peer_height={} gap={} boot_phase={:?} peer={} action=trigger_state_sync_recovery",
        path, local_height, peer_height, gap, boot_phase, peer_label
    );

    ng_debug_throttle!(
        key: format!(
            "snapshot_priority_gate_trigger_statesync_{}_{}_{}",
            path, local_height, peer_height
        ),
        every_ms: 30_000,
        target: "p2p.sync",
        "event=snapshot_priority_gate_trigger_statesync path={} local_height={} peer_height={} gap={} boot_phase={:?} peer={} reason=large_gap_snapshot_required",
        path,
        local_height,
        peer_height,
        gap,
        boot_phase,
        peer_label,
    );

    if statesync_trigger_legacy_snapshot_priority_v195_test_only(
        StateSyncReason::gap_stall_with_heights(detail, local_height, peer_height),
    ) {
        tracker.note_state_sync_triggered(blocked_next_height);
        return true;
    }

    ng_debug_throttle!(
        key: format!(
            "snapshot_priority_gate_statesync_trigger_deferred_{}_{}_{}",
            path, local_height, peer_height
        ),
        every_ms: 30_000,
        target: "p2p.sync",
        "event=snapshot_priority_gate_statesync_trigger_deferred path={} local_height={} peer_height={} gap={} boot_phase={:?} peer={} reason=supervisor_not_ready action=retry_later",
        path,
        local_height,
        peer_height,
        gap,
        boot_phase,
        peer_label,
    );
    false
}

