impl CatchupProgressTracker {
    fn reset(&mut self) {
        *self = Self::default();
    }

    fn clear_blocked_attempt_state(&mut self, now: Instant) {
        self.first_seen_at = Some(now);
        self.rr_attempts = 0;
        self.rr_failures = 0;
        self.rr_backoff_suppressions = 0;
        self.local_consensus_invalid_hits = 0;
        self.deferred_retry_budget_exhaustions = 0;
        self.fork_no_backfill_hits = 0;
        self.last_sync_request_peer = None;
        self.last_sync_request_from = None;
        self.last_sync_request_target_height = None;
        self.last_sync_request_at = None;
        self.next_sync_request_allowed_at = None;
        self.last_escalated_next_height = None;
        self.last_escalated_at = None;
    }

    fn note_progress(&mut self, local_height: u64) {
        let now = Instant::now();
        match self.last_local_height {
            Some(prev) if prev != local_height => {
                self.last_local_height = Some(local_height);
                self.last_progress_at = Some(now);
                if self
                    .blocked_next_height
                    .map(|blocked| local_height.saturating_add(1) >= blocked)
                    .unwrap_or(true)
                {
                    self.reset();
                } else {
                    self.clear_blocked_attempt_state(now);
                }
            }
            None => {
                self.last_local_height = Some(local_height);
                self.last_progress_at = Some(now);
            }
            Some(_) => {
                self.last_progress_at.get_or_insert(now);
            }
        }
    }

    fn observe_blocked_height(&mut self, blocked_next_height: u64, local_height: u64) {
        let now = Instant::now();
        match self.last_local_height {
            Some(prev_local_height) if prev_local_height == local_height => {
                let merged_blocked_next_height = self
                    .blocked_next_height
                    .map(|prev| prev.max(blocked_next_height))
                    .unwrap_or(blocked_next_height);
                self.blocked_next_height = Some(merged_blocked_next_height);
                self.last_local_height = Some(local_height);
                self.first_seen_at.get_or_insert(now);
                self.last_progress_at.get_or_insert(now);
            }
            _ => {
                self.blocked_next_height = Some(blocked_next_height);
                self.last_local_height = Some(local_height);
                self.last_progress_at.get_or_insert(now);
                self.clear_blocked_attempt_state(now);
            }
        }
    }

    fn note_local_consensus_invalid(&mut self, blocked_next_height: u64, local_height: u64) {
        self.observe_blocked_height(blocked_next_height, local_height);
        self.local_consensus_invalid_hits = self.local_consensus_invalid_hits.saturating_add(1);
        self.rr_failures = self.rr_failures.saturating_add(1);
    }

    fn check_sync_request_backoff(
        &mut self,
        peer: &PeerId,
        from: u64,
        target_height: u64,
        local_height: u64,
    ) -> Option<Duration> {
        if self.state_sync_pending {
            return None;
        }
        let same_request = self.last_sync_request_peer.as_ref() == Some(peer)
            && self.last_sync_request_from == Some(from)
            && self.last_sync_request_target_height == Some(target_height)
            && self.last_local_height == Some(local_height);
        if !same_request {
            return None;
        }
        let now = Instant::now();
        let until = self.next_sync_request_allowed_at?;
        if until > now {
            self.rr_backoff_suppressions = self.rr_backoff_suppressions.saturating_add(1);
            return Some(until.duration_since(now));
        }
        None
    }

    fn note_sync_request_sent(
        &mut self,
        peer: PeerId,
        from: u64,
        target_height: u64,
        local_height: u64,
        base_backoff: Duration,
        max_backoff: Duration,
    ) {
        let now = Instant::now();
        self.observe_blocked_height(
            target_height.max(local_height.saturating_add(1)),
            local_height,
        );
        self.rr_attempts = self.rr_attempts.saturating_add(1).max(1);
        self.last_sync_request_peer = Some(peer);
        self.last_sync_request_from = Some(from);
        self.last_sync_request_target_height = Some(target_height);
        self.last_sync_request_at = Some(now);

        let repeat_budget = self.rr_attempts.saturating_sub(1).min(6);
        let failure_budget = self.rr_failures.min(6);
        let exponent = repeat_budget.saturating_add(failure_budget).min(10);
        let factor = 1u64 << exponent;
        let base_ms = (base_backoff.as_millis().min(u128::from(u64::MAX))) as u64;
        let max_ms = (max_backoff.as_millis().min(u128::from(u64::MAX))) as u64;
        let backoff_ms = base_ms
            .saturating_mul(factor)
            .clamp(base_ms, max_ms.max(base_ms));
        self.next_sync_request_allowed_at = Some(now + Duration::from_millis(backoff_ms));
    }

    fn note_rr_failure(&mut self, blocked_next_height: u64, local_height: u64) {
        self.observe_blocked_height(blocked_next_height, local_height);
        self.rr_failures = self.rr_failures.saturating_add(1);
    }

    fn note_deferred_retry_budget_exhausted(
        &mut self,
        blocked_next_height: u64,
        local_height: u64,
    ) {
        self.observe_blocked_height(blocked_next_height, local_height);
        self.deferred_retry_budget_exhaustions =
            self.deferred_retry_budget_exhaustions.saturating_add(1);
        self.rr_failures = self.rr_failures.saturating_add(1);
    }

    fn note_fork_no_backfill(&mut self, blocked_next_height: u64, local_height: u64) {
        self.observe_blocked_height(blocked_next_height, local_height);
        self.fork_no_backfill_hits = self.fork_no_backfill_hits.saturating_add(1);
        self.rr_failures = self.rr_failures.saturating_add(1);
    }

    fn state_sync_pending(&self) -> bool {
        self.state_sync_pending
    }

    fn maybe_escalate(
        &self,
        blocker: Option<&LocalSyncRetryBlock>,
        blocked_for_limit: Duration,
        rr_repeat_limit: u32,
        fault_hit_limit: u32,
        deferred_exhaustion_limit: u32,
        cooldown: Duration,
    ) -> Option<CatchupEscalationDecision> {
        if self.state_sync_pending {
            return None;
        }
        let blocked_next_height = blocker
            .map(|active| active.next_height)
            .or(self.blocked_next_height)?;
        let now = Instant::now();
        if self.last_escalated_next_height == Some(blocked_next_height)
            && self
                .last_escalated_at
                .map(|ts| now.duration_since(ts) < cooldown)
                .unwrap_or(false)
        {
            return None;
        }

        let blocked_for = self
            .first_seen_at
            .map(|ts| now.duration_since(ts))
            .unwrap_or_default();
        let no_progress_for = self
            .last_progress_at
            .map(|ts| now.duration_since(ts))
            .unwrap_or(blocked_for);
        let local_height = self.last_local_height.unwrap_or(0);
        let from_height = self.last_sync_request_from.unwrap_or(0);
        let target_height = self
            .last_sync_request_target_height
            .unwrap_or(blocked_next_height);
        let peer = self.last_sync_request_peer.clone();
        let source_peer = blocker.and_then(|active| active.source_peer.clone());
        let fault_class = blocker
            .map(|active| local_consensus_fault_class_str(&active.fault.class).to_string())
            .unwrap_or_else(|| "unknown".to_string());
        let fault_scope = blocker
            .map(|active| active.fault.scope.clone())
            .unwrap_or_else(|| "unknown".to_string());
        let fault_detail = blocker
            .and_then(|active| active.fault.detail.clone())
            .unwrap_or_default();

        let build = |reason: &'static str| CatchupEscalationDecision {
            reason,
            blocked_next_height,
            local_height,
            blocked_for_ms: blocked_for.as_millis(),
            no_progress_ms: no_progress_for.as_millis(),
            from_height,
            target_height,
            peer: peer.clone(),
            rr_attempts: self.rr_attempts,
            rr_failures: self.rr_failures,
            rr_backoff_suppressions: self.rr_backoff_suppressions,
            fault_hit_count: self.local_consensus_invalid_hits,
            deferred_retry_budget_exhaustions: self.deferred_retry_budget_exhaustions,
            fork_no_backfill_hits: self.fork_no_backfill_hits,
            fault_class: fault_class.clone(),
            fault_scope: fault_scope.clone(),
            fault_detail: fault_detail.clone(),
            source_peer: source_peer.clone(),
        };

        // Prioritize more specific typed wedge causes before the generic
        // local-height-no-progress bucket so diagnostics and escalation reasons
        // preserve the real root symptom that drove the wedge.
        if blocker.is_some() && self.local_consensus_invalid_hits >= fault_hit_limit {
            return Some(build("local_consensus_context_invalid_repeated"));
        }
        if self.fork_no_backfill_hits >= rr_repeat_limit.max(1) {
            return Some(build("fork_losing_no_backfill_repeated"));
        }
        if no_progress_for >= blocked_for_limit && self.rr_attempts >= rr_repeat_limit.max(1) {
            return Some(build("local_height_no_progress"));
        }
        if self.rr_attempts >= rr_repeat_limit {
            return Some(build("repeated_sync_request_no_progress"));
        }
        if self.deferred_retry_budget_exhaustions >= deferred_exhaustion_limit.max(1) {
            return Some(build("deferred_retry_budget_exhausted"));
        }
        if blocked_for >= blocked_for_limit.saturating_mul(2) {
            return Some(build("blocked_too_long"));
        }
        None
    }

    fn note_state_sync_triggered(&mut self, blocked_next_height: u64) {
        self.last_escalated_next_height = Some(blocked_next_height);
        self.last_escalated_at = Some(Instant::now());
        self.state_sync_pending = true;
    }
}

impl LocalSyncRetryBlock {
    fn from_fault(
        next_height: u64,
        sync_from: Option<u64>,
        source_peer: Option<PeerId>,
        fault: LocalConsensusBootstrapFaultView,
    ) -> Self {
        let now = Instant::now();
        Self {
            next_height,
            sync_from,
            fault,
            first_seen_at: now,
            last_seen_at: now,
            hit_count: 1,
            source_peer,
        }
    }

    fn from_error(
        next_height: u64,
        sync_from: Option<u64>,
        source_peer: Option<PeerId>,
        err: &str,
    ) -> Option<Self> {
        let inner = unwrap_block_validation_error_prefixes(err);
        let fault = Blockchain::extract_local_post_snapshot_consensus_fault(inner)?;
        Some(Self::from_fault(next_height, sync_from, source_peer, fault))
    }

    fn summary(&self) -> String {
        format!(
            "next_height={} fault_class={} scope={} detail={} hits={} blocked_for_ms={} last_seen_ms_ago={}",
            self.next_height,
            local_consensus_fault_class_str(&self.fault.class),
            self.fault.scope,
            self.fault.detail.as_deref().unwrap_or(""),
            self.hit_count,
            self.first_seen_at.elapsed().as_millis(),
            self.last_seen_at.elapsed().as_millis(),
        )
    }
}

impl BlockValidationFaultClass {
    fn penalize_peer(self) -> bool {
        matches!(self, Self::PeerInvalid)
    }

    fn intake_state(self) -> InboundBlockIntakeState {
        match self {
            Self::PeerInvalid => InboundBlockIntakeState::RejectedPermanent,
            Self::LocalConsensusContextInvalid | Self::LocalPolicyBlocked => {
                InboundBlockIntakeState::RejectedTransient
            }
        }
    }

    fn intake_disposition(self) -> InboundBlockDisposition {
        match self {
            Self::PeerInvalid => InboundBlockDisposition::RejectedPermanent,
            Self::LocalConsensusContextInvalid | Self::LocalPolicyBlocked => {
                InboundBlockDisposition::DroppedTransient
            }
        }
    }

    fn rejection_reason(self, base: &'static str) -> &'static str {
        match self {
            Self::PeerInvalid => base,
            Self::LocalConsensusContextInvalid => "local_snapshot_consensus_context_invalid",
            Self::LocalPolicyBlocked => "local_validation_policy_blocked",
        }
    }
}

fn unwrap_block_validation_error_prefixes(mut err: &str) -> &str {
    loop {
        let trimmed = err.trim();
        if let Some(rest) = trimmed.strip_prefix("competing tip invalid:") {
            err = rest;
            continue;
        }
        if let Some(rest) = trimmed.strip_prefix("strict_validation_failed:") {
            err = rest;
            continue;
        }
        return trimmed;
    }
}

fn classify_block_validation_fault(err: &str) -> BlockValidationFaultClass {
    let inner = unwrap_block_validation_error_prefixes(err);
    if Blockchain::extract_local_post_snapshot_consensus_fault(inner).is_some() {
        return BlockValidationFaultClass::LocalConsensusContextInvalid;
    }
    if inner.contains("competing tip adoption disabled when base_height>0")
        || inner.contains("chain too short for competing tip adoption")
        || inner.contains("missing local tip")
        || inner.contains("missing local parent")
        || inner.contains("competing tip adoption aborted: local tip changed during processing")
    {
        return BlockValidationFaultClass::LocalPolicyBlocked;
    }
    BlockValidationFaultClass::PeerInvalid
}

fn arm_local_sync_retry_block(
    blocker: &mut Option<LocalSyncRetryBlock>,
    chain_arc: &Arc<Mutex<Blockchain>>,
    next_height: u64,
    sync_from: Option<u64>,
    peer: Option<PeerId>,
    err: &str,
    context: &str,
) {
    let Some(new_block) = LocalSyncRetryBlock::from_error(next_height, sync_from, peer, err) else {
        return;
    };
    match blocker.as_mut() {
        Some(existing)
            if existing.next_height == new_block.next_height
                && existing.fault == new_block.fault =>
        {
            existing.sync_from = new_block.sync_from;
            existing.last_seen_at = Instant::now();
            existing.hit_count = existing.hit_count.saturating_add(1);
            if existing.source_peer.is_none() {
                existing.source_peer = new_block.source_peer;
            }
        }
        _ => {
            *blocker = Some(new_block);
        }
    }
    if let Some(active) = blocker.as_ref() {
        let local_height = {
            let mut g = chain_arc.lock().unwrap_or_else(|e| e.into_inner());
            g.set_runtime_sync_retry_blocked(active.next_height, active.fault.clone());
            g.set_runtime_sync_caught_up(false);
            g.set_proposal_gate_open(false);
            g.set_p2p_ready_for_mining(false);
            g.tip_height_u64()
        };
        ng_warn_throttle!(
            key: format!("local_sync_retry_block_{}_{}", context, active.next_height),
            every_ms: 15_000,
            target: "p2p.sync",
            "event=local_sync_retry_blocked context={} next_height={} fault_class={} fault_scope={} fault_detail={} hit_count={} source_peer={} local_height={} elapsed_ms={}",
            context,
            active.next_height,
            local_consensus_fault_class_str(&active.fault.class),
            active.fault.scope,
            active.fault.detail.as_deref().unwrap_or(""),
            active.hit_count,
            active
                .source_peer
                .as_ref()
                .map(|peer_id| peer_id.to_string())
                .unwrap_or_else(|| "none".to_string()),
            local_height,
            active.first_seen_at.elapsed().as_millis(),
        );
    }
}

fn clear_local_sync_retry_block(
    blocker: &mut Option<LocalSyncRetryBlock>,
    chain_arc: &Arc<Mutex<Blockchain>>,
    reason: &str,
) {
    let Some(active) = blocker.take() else {
        let mut g = chain_arc.lock().unwrap_or_else(|e| e.into_inner());
        g.clear_runtime_sync_retry_blocked();
        return;
    };
    {
        let mut g = chain_arc.lock().unwrap_or_else(|e| e.into_inner());
        g.clear_runtime_sync_retry_blocked();
    }
    ng_info!(
        target: "p2p.sync",
        "event=local_sync_retry_block_cleared reason={} {}",
        reason,
        active.summary(),
    );
}

fn arm_local_sync_retry_block_from_status(
    blocker: &mut Option<LocalSyncRetryBlock>,
    chain_arc: &Arc<Mutex<Blockchain>>,
    status: &crate::blockchain::LocalConsensusBootstrapStatusView,
    context: &str,
) -> bool {
    if status.ready {
        return false;
    }
    let Some(fault) = status.fault.clone() else {
        return false;
    };
    let sync_from = Some(status.next_height.max(1));
    let new_block = LocalSyncRetryBlock::from_fault(status.next_height, sync_from, None, fault);
    let mut inserted = false;
    match blocker.as_mut() {
        Some(existing)
            if existing.next_height == new_block.next_height
                && existing.fault == new_block.fault =>
        {
            existing.sync_from = new_block.sync_from;
            existing.last_seen_at = Instant::now();
            existing.hit_count = existing.hit_count.saturating_add(1);
        }
        _ => {
            *blocker = Some(new_block);
            inserted = true;
        }
    }
    if let Some(active) = blocker.as_ref() {
        let local_height = {
            let mut g = chain_arc.lock().unwrap_or_else(|e| e.into_inner());
            g.set_runtime_sync_retry_blocked(active.next_height, active.fault.clone());
            g.set_runtime_sync_caught_up(false);
            g.set_proposal_gate_open(false);
            g.set_p2p_ready_for_mining(false);
            g.tip_height_u64()
        };
        ng_warn_throttle!(
            key: format!("local_sync_retry_block_from_status_{}_{}", context, active.next_height),
            every_ms: 15_000,
            target: "p2p.sync",
            "event=local_sync_retry_blocked_from_status context={} next_height={} fault_class={} fault_scope={} fault_detail={} hit_count={} local_height={} elapsed_ms={}",
            context,
            active.next_height,
            local_consensus_fault_class_str(&active.fault.class),
            active.fault.scope,
            active.fault.detail.as_deref().unwrap_or(""),
            active.hit_count,
            local_height,
            active.first_seen_at.elapsed().as_millis(),
        );
    }
    inserted
}

fn maybe_arm_local_sync_retry_block_from_runtime_status(
    blocker: &mut Option<LocalSyncRetryBlock>,
    chain_arc: &Arc<Mutex<Blockchain>>,
    boot_phase: P2pBootPhase,
    context: &str,
) -> bool {
    if !matches!(
        boot_phase,
        P2pBootPhase::RestartCatchup | P2pBootPhase::FallbackLiveSync
    ) {
        return false;
    }
    let status = {
        let g = chain_arc.lock().unwrap_or_else(|e| e.into_inner());
        g.runtime_consensus_bootstrap_status_for_next_height_view()
    };
    arm_local_sync_retry_block_from_status(blocker, chain_arc, &status, context)
}

fn reconcile_local_sync_retry_block(
    blocker: &mut Option<LocalSyncRetryBlock>,
    chain_arc: &Arc<Mutex<Blockchain>>,
) -> Option<LocalSyncRetryBlock> {
    let Some(active) = blocker.as_ref().cloned() else {
        let mut g = chain_arc.lock().unwrap_or_else(|e| e.into_inner());
        g.clear_runtime_sync_retry_blocked();
        return None;
    };
    let status = {
        let g = chain_arc.lock().unwrap_or_else(|e| e.into_inner());
        g.runtime_consensus_bootstrap_status_for_next_height_view()
    };
    if status.ready {
        clear_local_sync_retry_block(blocker, chain_arc, "consensus_bootstrap_ready");
        return None;
    }
    if status.next_height != active.next_height {
        clear_local_sync_retry_block(blocker, chain_arc, "local_next_height_changed");
        return None;
    }
    let mut g = chain_arc.lock().unwrap_or_else(|e| e.into_inner());
    g.set_runtime_sync_retry_blocked(active.next_height, active.fault.clone());
    Some(active)
}

fn maybe_trigger_local_consensus_wedged_statesync(
    tracker: &mut CatchupProgressTracker,
    blocker: Option<&LocalSyncRetryBlock>,
    local_consensus_source_bound_verified_v246: Option<LocalConsensusWedgedStateSyncPermitV246>,
    chain_arc: &Arc<Mutex<Blockchain>>,
    pending_sync_from: &mut Option<u64>,
    pending_sync_peer: &mut Option<PeerId>,
    pending_sync_limit: &mut Option<u32>,
    current_sync_intent: &mut Option<SyncIntent>,
    deferred_blocks: &mut DeferredBlockCache,
    local_tip_height: u64,
    blocked_for_limit: Duration,
    rr_repeat_limit: u32,
    fault_hit_limit: u32,
    deferred_exhaustion_limit: u32,
    cooldown: Duration,
) -> bool {
    if local_consensus_source_bound_verified_v246.is_none() {
        ng_warn_throttle!(
            key: "statesync_trigger_suppressed_local_consensus_unverified_v246".to_string(),
            every_ms: 5_000,
            target: "p2p.sync",
            "event=statesync_trigger_suppressed_v246 path=local_consensus_wedged reason=missing_verified_operational_source_bound",
        );
        return false;
    }

    let Some(decision) = tracker.maybe_escalate(
        blocker,
        blocked_for_limit,
        rr_repeat_limit,
        fault_hit_limit,
        deferred_exhaustion_limit,
        cooldown,
    ) else {
        return false;
    };
    let blocked_next_height = decision.blocked_next_height;
    *pending_sync_from = None;
    *pending_sync_peer = None;
    *pending_sync_limit = None;
    *current_sync_intent = None;
    let pruned = deferred_blocks.remove_recovery_incompatible_above_tip(local_tip_height);
    {
        let mut g = chain_arc.lock().unwrap_or_else(|e| e.into_inner());
        g.set_runtime_sync_caught_up(false);
        g.set_proposal_gate_open(false);
        g.set_p2p_ready_for_mining(false);
    }
    ng_warn!(
        target: "p2p.sync",
        "event=catchup_no_progress reason={} from_height={} peer={} attempts={} rr_failures={} local_height={} blocked_next_height={} elapsed_ms={} no_progress_ms={} rr_backoff_suppressions={} fork_no_backfill_hits={} fault_class={} fault_scope={} fault_detail={} hit_count={} source_peer={} deferred_retry_budget_exhaustions={}",
        decision.reason,
        decision.from_height,
        decision
            .peer
            .as_ref()
            .map(|peer| peer.to_string())
            .unwrap_or_else(|| "none".to_string()),
        decision.rr_attempts,
        decision.rr_failures,
        decision.local_height,
        decision.blocked_next_height,
        decision.blocked_for_ms,
        decision.no_progress_ms,
        decision.rr_backoff_suppressions,
        decision.fork_no_backfill_hits,
        decision.fault_class,
        decision.fault_scope,
        decision.fault_detail,
        decision.fault_hit_count,
        decision
            .source_peer
            .as_ref()
            .map(|peer| peer.to_string())
            .unwrap_or_else(|| "none".to_string()),
        decision.deferred_retry_budget_exhaustions,
    );
    let reason_detail = format!(
        "reason={} local_tip={} pruned_deferred={} pending_sync_peer=none from_height={} target_height={} peer={} attempts={} rr_failures={} rr_backoff_suppressions={} fork_no_backfill_hits={} no_progress_ms={} fault_class={} fault_scope={} fault_detail={} hit_count={} source_peer={} deferred_retry_budget_exhaustions={}",
        decision.reason,
        local_tip_height,
        pruned,
        decision.from_height,
        decision.target_height,
        decision
            .peer
            .as_ref()
            .map(|peer| peer.to_string())
            .unwrap_or_else(|| "none".to_string()),
        decision.rr_attempts,
        decision.rr_failures,
        decision.rr_backoff_suppressions,
        decision.fork_no_backfill_hits,
        decision.no_progress_ms,
        decision.fault_class,
        decision.fault_scope,
        decision.fault_detail,
        decision.fault_hit_count,
        decision
            .source_peer
            .as_ref()
            .map(|peer| peer.to_string())
            .unwrap_or_else(|| "none".to_string()),
        decision.deferred_retry_budget_exhaustions,
    );
    ng_error!(
        target: "p2p.sync",
        "event=catchup_escalated_to_state_sync reason={} blocked_next_height={} peer={} elapsed_ms={} local_height={} from_height={} target_height={} attempts={} rr_failures={} rr_backoff_suppressions={} fork_no_backfill_hits={} fault_class={} fault_scope={} fault_detail={} hit_count={} source_peer={} deferred_retry_budget_exhaustions={} pruned_deferred={}",
        decision.reason,
        decision.blocked_next_height,
        decision
            .peer
            .as_ref()
            .map(|peer| peer.to_string())
            .unwrap_or_else(|| "none".to_string()),
        decision.blocked_for_ms,
        decision.local_height,
        decision.from_height,
        decision.target_height,
        decision.rr_attempts,
        decision.rr_failures,
        decision.rr_backoff_suppressions,
        decision.fork_no_backfill_hits,
        decision.fault_class,
        decision.fault_scope,
        decision.fault_detail,
        decision.fault_hit_count,
        decision
            .source_peer
            .as_ref()
            .map(|peer| peer.to_string())
            .unwrap_or_else(|| "none".to_string()),
        decision.deferred_retry_budget_exhaustions,
        pruned,
    );
    if statesync_trigger_verified_local_consensus_wedged_v246(
        StateSyncReason::LocalConsensusWedged {
            detail: reason_detail.clone(),
        },
    ) {
        tracker.note_state_sync_triggered(blocked_next_height);
        return true;
    }

    ng_warn_throttle!(
        key: format!("statesync_trigger_deferred_local_consensus_{}", blocked_next_height),
        every_ms: 5_000,
        target: "p2p.sync",
        "event=statesync_trigger_deferred path=local_consensus_wedged blocked_next_height={} reason=supervisor_not_ready action=retry_later",
        blocked_next_height,
    );
    false
}

fn maybe_penalize_peer_for_block_fault(
    rep_man: &Arc<Mutex<PeerReputationManager>>,
    net_score: &mut HashMap<PeerId, i32>,
    net_score_first_seen: &mut HashMap<PeerId, Instant>,
    peer: PeerId,
    p2p_policy: &P2PPolicy,
    err: &str,
    context: &str,
) -> BlockValidationFaultClass {
    let class = classify_block_validation_fault(err);
    if class.penalize_peer() {
        rep_event!(
            rep_man,
            &peer,
            ReputationEvent::InvalidBlock,
            p2p_policy.peer_scoring_enabled
        );
        net_score_apply(net_score, net_score_first_seen, peer, -15);
    } else {
        let inner = unwrap_block_validation_error_prefixes(err);
        if let Some(fault) = Blockchain::extract_local_post_snapshot_consensus_fault(inner) {
            ng_warn!(
                target: "p2p.sync",
                "[P2P] local block validation fault class={:?} scope={} peer={} context={} detail={} raw={}",
                class,
                fault.scope,
                peer,
                context,
                fault.detail.as_deref().unwrap_or(""),
                err,
            );
        } else {
            ng_warn!(
                target: "p2p.sync",
                "[P2P] local block validation fault class={:?} peer={} context={} err={}",
                class,
                peer,
                context,
                err,
            );
        }
    }
    class
}

