fn snapshot_v2_select_validator_bootstrap_dir(
    paths: &NodePaths,
    requested_height: Option<u64>,
) -> Option<std::path::PathBuf> {
    snapshot_v2_select_validator_bootstrap_dir_with_tip_v200(
        paths,
        requested_height,
        if requested_height.is_none() {
            crate::api::runtime_status_cache_height_v1()
        } else {
            None
        },
        false,
    )
}

fn snapshot_v2_select_validator_bootstrap_dir_with_tip_v200(
    paths: &NodePaths,
    requested_height: Option<u64>,
    local_tip_hint: Option<u64>,
    require_local_tip_for_latest: bool,
) -> Option<std::path::PathBuf> {
    let mut candidates: Vec<(String, std::path::PathBuf)> = Vec::new();
    if let Ok(v) = std::env::var("NEWGEN_SNAPSHOT_V2_DIR") {
        let t = v.trim();
        if !t.is_empty() {
            candidates.push(("env_override".to_string(), std::path::PathBuf::from(t)));
        }
    }
    candidates.push((
        "bootstrap_latest".to_string(),
        snapshot_v2_bootstrap_latest_dir_from_root(&paths.snapshots_dir),
    ));
    candidates.push((
        "auto_latest".to_string(),
        snapshot_v2_latest_dir_from_root(&paths.snapshots_dir),
    ));
    if !crate::runtime_mode::public_mode_enabled()
        || env_truthy_v192("NEWGEN_ALLOW_LEGACY_SNAPSHOT_DIR")
    {
        candidates.push((
            "legacy_latest".to_string(),
            snapshot_v2_legacy_latest_dir_from_root(&paths.snapshots_dir),
        ));
    }

    if requested_height.is_none() && require_local_tip_for_latest && local_tip_hint.is_none() {
        ng_warn_throttle!(
            key: "snapshot_latest_provider_local_tip_unknown_v200".to_string(),
            every_ms: 30_000,
            target: "p2p.snapshot",
            "event=snapshot_latest_provider_local_tip_unknown action=fail_closed reason=latest_snapshot_requires_local_tip"
        );
        return None;
    }

    let max_latest_staleness = snapshot_v2_latest_max_staleness_blocks_v199();
    let mut best: Option<(u64, String, std::path::PathBuf)> = None;

    for (label, dir) in candidates {
        if !dir.join("meta.json").exists() {
            continue;
        }
        match read_snapshot_v2_meta_for_advertise(&dir) {
            Some((meta, _sha)) => {
                // V191/V190 hardening: candidate selection must evaluate the same
                // RRv3 transport view that will actually be advertised. Legacy
                // bootstrap bundles can carry governance/compute sidecar JSON
                // without precomputed hashes; the transport view derives those
                // hashes before stripping the sidecars, so do not reject them
                // using raw on-disk validate_basic() here.
                let transport_meta = snapshot_meta_for_rrv3_transport(&meta);
                if !snapshot_meta_is_validator_bootstrap_capable(&transport_meta) {
                    ng_warn_throttle!(
                        key: format!("snapshot_bootstrap_not_advertised_{}_{}", label, meta.height),
                        every_ms: 30_000,
                        target: "p2p.snapshot",
                        "event=snapshot_bootstrap_not_advertised candidate={} height={} role={:?} validator_bootstrap_capable={} reason=not_validator_bootstrap_capable",
                        label,
                        meta.height,
                        transport_meta.snapshot_bootstrap_role,
                        transport_meta.validator_bootstrap_capable
                    );
                    continue;
                }

                if let Some(height) = requested_height {
                    if transport_meta.height != height {
                        ng_debug!(
                            target: "p2p.snapshot",
                            "event=snapshot_bootstrap_candidate_height_mismatch candidate={} requested_height={} candidate_height={} action=skip",
                            label,
                            height,
                            transport_meta.height
                        );
                        continue;
                    }
                } else if let Some(local_tip) = local_tip_hint {
                    if local_tip > transport_meta.height {
                        let staleness = local_tip.saturating_sub(transport_meta.height);
                        if staleness > max_latest_staleness {
                            ng_warn_throttle!(
                                key: format!("snapshot_latest_candidate_stale_{}_{}_{}", label, transport_meta.height, local_tip),
                                every_ms: 30_000,
                                target: "p2p.snapshot",
                                "event=snapshot_latest_candidate_stale candidate={} height={} local_tip={} staleness_blocks={} max_staleness_blocks={} action=skip",
                                label,
                                transport_meta.height,
                                local_tip,
                                staleness,
                                max_latest_staleness
                            );
                            continue;
                        }
                    }
                }

                let replace = match best.as_ref() {
                    None => true,
                    Some((best_height, best_label, _best_dir)) => {
                        transport_meta.height > *best_height
                            || (transport_meta.height == *best_height && label < *best_label)
                    }
                };
                if replace {
                    best = Some((transport_meta.height, label, dir));
                }
            }
            None => {
                ng_warn_throttle!(
                    key: format!("snapshot_bootstrap_not_advertised_invalid_{}", label),
                    every_ms: 30_000,
                    target: "p2p.snapshot",
                    "event=snapshot_bootstrap_not_advertised candidate={} reason=invalid_or_unreadable_meta",
                    label,
                );
            }
        }
    }

    if let Some((height, label, dir)) = best {
        ng_debug!(
            target: "p2p.snapshot",
            "event=snapshot_bootstrap_candidate_selected candidate={} height={} requested_height={:?}",
            label,
            height,
            requested_height
        );
        Some(dir)
    } else {
        None
    }
}

#[allow(dead_code)]
pub(crate) fn snapshot_v2_validator_bootstrap_unavailable_dir_from_root(
    root: &std::path::Path,
) -> std::path::PathBuf {
    root.join("auto").join("validator_bootstrap_unavailable")
}
#[allow(dead_code)]
pub(crate) fn snapshot_v2_meta_path_for_advertise(dir: &std::path::Path) -> std::path::PathBuf {
    dir.join("meta.json")
}

#[allow(dead_code)]
pub(crate) fn read_snapshot_v2_meta_for_advertise(
    dir: &std::path::Path,
) -> Option<(SnapshotMeta, String)> {
    let meta_path = snapshot_v2_meta_path_for_advertise(dir);
    let bytes = fs::read(meta_path).ok()?;
    let meta: SnapshotMeta = serde_json::from_slice(&bytes).ok()?;
    let sha = Sha256::digest(&bytes);
    let sha_hex = hex::encode(sha);
    Some((meta, sha_hex))
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) struct SnapshotMetaTransportAdvertiseError {
    pub code: u32,
    pub message: String,
}

#[allow(dead_code)]
pub(crate) fn read_snapshot_v2_meta_for_transport_advertise(
    dir: &std::path::Path,
    max_frame_bytes: usize,
) -> Result<Option<(SnapshotMeta, String, Vec<u8>)>, SnapshotMetaTransportAdvertiseError> {
    let meta_path = snapshot_v2_meta_path_for_advertise(dir);
    let full_meta_bytes = match fs::read(&meta_path) {
        Ok(bytes) => bytes,
        Err(_) => return Ok(None),
    };
    let full_meta_len = full_meta_bytes.len();
    let meta: SnapshotMeta = match serde_json::from_slice(&full_meta_bytes) {
        Ok(meta) => meta,
        Err(_) => return Ok(None),
    };

    let transport_meta = snapshot_meta_for_rrv3_transport(&meta);
    let transport_meta_bytes = serde_json::to_vec_pretty(&transport_meta).ok();
    let transport_meta_len = transport_meta_bytes.as_ref().map(|b| b.len()).unwrap_or(0);
    let encoded_probe_len = transport_meta_bytes
        .as_ref()
        .map(|bytes| {
            let sha = format!("{:x}", Sha256::digest(bytes));
            encode_rr_v3(&RrV3Msg::SnapshotV2Meta {
                meta: Some(transport_meta.clone()),
                meta_sha256_hex: Some(sha),
            })
            .len()
        })
        .unwrap_or(0);

    match encode_snapshot_meta_for_rrv3(&meta, max_frame_bytes) {
        Some((transport_meta, sha, encoded)) => {
            if full_meta_len != transport_meta_len {
                ng_info!(
                    target: "p2p.snapshot",
                    "event=snapshot_meta_transport_stripped dir={} snapshot_height={} full_meta_bytes={} transport_meta_bytes={} encoded_frame_bytes={} max_frame={} action=strip_sidecars",
                    dir.display(),
                    meta.height,
                    full_meta_len,
                    transport_meta_len,
                    encoded.len(),
                    max_frame_bytes
                );
            }
            Ok(Some((transport_meta, sha, encoded)))
        }
        None => {
            let message = format!(
                "rr_v3_resp_too_large snapshot_height={} full_meta_bytes={} transport_meta_bytes={} encoded_frame_bytes={} max_frame={} chunk_size={} rr_safe_chunk_bytes={}",
                meta.height,
                full_meta_len,
                transport_meta_len,
                encoded_probe_len,
                max_frame_bytes,
                meta.chunk_size,
                rrv3_safe_snapshot_chunk_bytes(max_frame_bytes)
            );
            ng_warn!(
                target: "p2p.snapshot",
                "event=snapshot_meta_transport_oversize dir={} meta_path={} snapshot_height={} full_meta_bytes={} transport_meta_bytes={} encoded_frame_bytes={} max_frame={} chunk_size={} rr_safe_chunk_bytes={} action=reject",
                dir.display(),
                meta_path.display(),
                meta.height,
                full_meta_len,
                transport_meta_len,
                encoded_probe_len,
                max_frame_bytes,
                meta.chunk_size,
                rrv3_safe_snapshot_chunk_bytes(max_frame_bytes)
            );
            Err(SnapshotMetaTransportAdvertiseError { code: 413, message })
        }
    }
}

/// Derived per-peer inflight cap for RRv3 serves.
/// SyncPolicy currently exposes only a global inflight cap; we derive a conservative per-peer cap
/// to prevent a single peer from monopolizing all serve slots.
#[inline]
fn rr_v3_max_inflight_per_peer(sync_policy: &SyncPolicy) -> u32 {
    let g = sync_policy.rr_v3_max_inflight_global;
    // 25% of global, at least 1.
    std::cmp::max(1, g / 4)
}

