fn runtime_snapshot_meta_request_v219(height_opt: Option<u64>) -> RrV3Msg {
    if let Some(height) = height_opt {
        RrV3Msg::GetSnapshotV2Meta { height }
    } else {
        RrV3Msg::GetSnapshotV2Latest
    }
}

fn runtime_snapshot_outbound_failure_retryable_v219(error_debug: &str) -> bool {
    error_debug.contains("ConnectionClosed")
        || error_debug.contains("DialFailure")
        || error_debug.contains("Timeout")
}

fn runtime_snapshot_chunk_attempt_timeout_ms_v231(requested_timeout_ms: u64) -> u64 {
    let env_ms = std::env::var("NEWGEN_RUNTIME_SNAPSHOT_CHUNK_ATTEMPT_TIMEOUT_MS")
        .ok()
        .and_then(|s| s.trim().parse::<u64>().ok());
    env_ms
        .unwrap_or_else(|| requested_timeout_ms.max(30_000))
        .clamp(5_000, 120_000)
}

fn runtime_snapshot_chunk_retry_floor_v278() -> u8 {
    // V280: keep inner P2P chunk retries very small. State-sync now owns
    // provider failover, sticky success, local cooldown, and cross-family
    // fallback; long inner retry loops only make D look stuck on a silent
    // provider. The env knob remains operator-tunable, but the default is two
    // retries after the first attempt instead of the previous 6/12.
    std::env::var("NEWGEN_RUNTIME_SNAPSHOT_CHUNK_RETRY_FLOOR")
        .ok()
        .and_then(|s| s.trim().parse::<u8>().ok())
        .unwrap_or(2)
        .clamp(1, 16)
}

fn runtime_snapshot_chunk_retries_v231() -> u8 {
    std::env::var("NEWGEN_RUNTIME_SNAPSHOT_CHUNK_RETRIES")
        .ok()
        .and_then(|s| s.trim().parse::<u8>().ok())
        .unwrap_or_else(runtime_snapshot_chunk_retry_floor_v278)
        .clamp(1, 16)
}

fn runtime_snapshot_chunk_retry_deadline_v231(now: Instant, attempt_timeout_ms: u64) -> Instant {
    now + Duration::from_millis(runtime_snapshot_chunk_attempt_timeout_ms_v231(
        attempt_timeout_ms,
    ))
}

fn runtime_snapshot_chunk_transport_refetch_meta_error_v231(
    peer: PeerId,
    height: u64,
    chunk_index: u32,
    err: &str,
) -> String {
    format!(
        "snapshot_chunk_transport_retry_exhausted_refetch_meta peer={} height={} chunk_index={} err={}",
        peer, height, chunk_index, err
    )
}

fn runtime_snapshot_recovery_false_debounce_v231(base: Duration) -> Duration {
    let secs = std::env::var("NEWGEN_RUNTIME_RECOVERY_PEER_FALSE_DEBOUNCE_SECS")
        .ok()
        .and_then(|s| s.trim().parse::<u64>().ok())
        .unwrap_or(180)
        .clamp(30, 600);
    base.max(Duration::from_secs(secs))
}

fn runtime_snapshot_recovery_pressure_active_v231(
    boot_phase: P2pBootPhase,
    snapshot_recovery_peer_count: usize,
    snapshot_pending_count: usize,
    snapshot_retry_count: usize,
) -> bool {
    matches!(boot_phase, P2pBootPhase::SteadyState)
        && (snapshot_recovery_peer_count > 0
            || snapshot_pending_count > 0
            || snapshot_retry_count > 0)
}

fn runtime_state_sync_recovery_guard_active_v232(
    boot_phase: P2pBootPhase,
    was_runtime_caught_up: bool,
    was_p2p_ready: bool,
    snapshot_recovery_peer_count: usize,
    snapshot_pending_count: usize,
    snapshot_retry_count: usize,
) -> bool {
    // V232: if this validator is already healthy/operational and the only new
    // pressure comes from snapshot/recovery peers, local state-sync supervisors
    // must not flip A/B/C to not-ready or arm rescue sync from global heights.
    // This is stricter than the V231 debounce: it protects the state-sync paths
    // that run before readiness export and before operational scopes are rebuilt.
    runtime_snapshot_recovery_pressure_active_v231(
        boot_phase,
        snapshot_recovery_peer_count,
        snapshot_pending_count,
        snapshot_retry_count,
    ) && was_runtime_caught_up
        && was_p2p_ready
}

fn runtime_telemetry_operational_candidate_v234(
    telemetry_peer: Option<PeerId>,
    recovery_peers: &HashSet<PeerId>,
    telemetry_height: u64,
    runtime_sync_caught_up: bool,
    runtime_bootstrap_complete: bool,
    _p2p_ready_for_mining: bool,
) -> bool {
    // V261: break the p2p-ready circular dependency observed on A/B/C restart.
    // `p2p_ready_for_mining` is a derived local proposal/mining gate. If peer
    // telemetry admission requires that derived gate to already be true, then a
    // clean multi-node restart can deadlock at self-only readiness: every node
    // exports p2p=false because it has no operational peers yet, and every other
    // node rejects the telemetry because p2p=false.
    //
    // Operational admission remains fail-closed for the safety-critical signals:
    // known peer, not in snapshot/recovery lifecycle, height > 0, caught-up
    // runtime, and completed bootstrap. V236/V237 still enforce validator-set
    // hash and finalized-head compatibility before the peer enters the
    // Operational scope. Non-operational D recovery telemetry remains rejected.
    let Some(peer) = telemetry_peer else {
        return false;
    };
    if recovery_peers.contains(&peer) {
        return false;
    }

    telemetry_height > 0 && runtime_sync_caught_up && runtime_bootstrap_complete
}

fn runtime_telemetry_should_skip_non_operational_v234(
    telemetry_peer: Option<PeerId>,
    recovery_peers: &HashSet<PeerId>,
    telemetry_height: u64,
    runtime_sync_caught_up: bool,
    runtime_bootstrap_complete: bool,
    p2p_ready_for_mining: bool,
) -> bool {
    !runtime_telemetry_operational_candidate_v234(
        telemetry_peer,
        recovery_peers,
        telemetry_height,
        runtime_sync_caught_up,
        runtime_bootstrap_complete,
        p2p_ready_for_mining,
    )
}

fn runtime_snapshot_chunk_session_ttl_v220() -> Duration {
    let ms = std::env::var("NEWGEN_RUNTIME_SNAPSHOT_CHUNK_SESSION_TTL_MS")
        .ok()
        .and_then(|s| s.trim().parse::<u64>().ok())
        .unwrap_or(300_000)
        .clamp(60_000, 900_000);
    Duration::from_millis(ms)
}

fn runtime_snapshot_chunk_session_valid_v220(
    sessions: &HashMap<(PeerId, u64), Instant>,
    peer: &PeerId,
    height: u64,
    now: Instant,
) -> bool {
    sessions
        .get(&(*peer, height))
        .map(|until| *until > now)
        .unwrap_or(false)
}

fn runtime_snapshot_chunk_session_refresh_v222(
    sessions: &mut HashMap<(PeerId, u64), Instant>,
    peer: PeerId,
    height: u64,
    now: Instant,
) -> Duration {
    let ttl = runtime_snapshot_chunk_session_ttl_v220();
    sessions.insert((peer, height), now + ttl);
    ttl
}

fn runtime_snapshot_progress_log_chunk_v222(chunk_index: u32, total_chunks: u32) -> bool {
    chunk_index == 0
        || chunk_index.saturating_add(1) == total_chunks
        || chunk_index.saturating_add(1) % 50 == 0
}

#[derive(Clone, Debug, PartialEq, Eq)]
enum RuntimeSnapshotServeSessionStateV233 {
    Open,
    Progressing,
    Stalled,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct RuntimeSnapshotChunkResponseProgressV249 {
    height: u64,
    chunk_index: u32,
    raw_bytes: u64,
    encoded_bytes: usize,
    pinned_v221: bool,
}

#[derive(Clone, Debug)]
struct RuntimeSnapshotServeSessionV221 {
    dir: std::path::PathBuf,
    meta_sha256_hex: String,
    height: u64,
    chunks: u32,
    chunk_hashes_hex: Vec<String>,
    expires_at: Instant,
    // V233: serve sessions are progress-aware. A session must stay alive
    // because chunks are actually moving, not simply because a peer keeps
    // retrying the same stalled chunk forever.
    last_progress_at: Instant,
    last_chunk_served: Option<u32>,
    bytes_served: u64,
    consecutive_failures: u32,
    // V249 separates lifecycle stages so "success" is never recorded at read/encode time.
    // last_chunk_served/bytes_served now mean response accepted by libp2p send_response.
    // last_successful_chunk now means implicit client ACK, observed when the client asks for chunk + 1.
    last_successful_chunk: Option<u32>,
    last_attempt_started_chunk: Option<u32>,
    last_encoded_chunk: Option<u32>,
    last_response_sent_chunk: Option<u32>,
    last_acknowledged_chunk: Option<u32>,
    last_attempt_started_at: Option<Instant>,
    last_encoded_at: Option<Instant>,
    last_sent_at: Option<Instant>,
    last_acknowledged_at: Option<Instant>,
    bytes_encoded: u64,
    bytes_sent: u64,
    state: RuntimeSnapshotServeSessionStateV233,
}

fn runtime_snapshot_serve_session_ttl_v221() -> Duration {
    let ms = std::env::var("NEWGEN_RUNTIME_SNAPSHOT_SERVE_SESSION_TTL_MS")
        .ok()
        .and_then(|s| s.trim().parse::<u64>().ok())
        .unwrap_or(300_000)
        .clamp(60_000, 900_000);
    Duration::from_millis(ms)
}

fn runtime_snapshot_serve_session_inactivity_timeout_v233() -> Duration {
    let ms = std::env::var("NEWGEN_RUNTIME_SNAPSHOT_SERVE_SESSION_INACTIVITY_TIMEOUT_MS")
        .ok()
        .and_then(|s| s.trim().parse::<u64>().ok())
        .unwrap_or(180_000)
        .clamp(30_000, 900_000);
    Duration::from_millis(ms)
}

fn runtime_snapshot_serve_session_stall_repeated_chunk_threshold_v233() -> u32 {
    std::env::var("NEWGEN_RUNTIME_SNAPSHOT_SERVE_SESSION_STALL_REPEATED_CHUNKS")
        .ok()
        .and_then(|s| s.trim().parse::<u32>().ok())
        .unwrap_or(4)
        .clamp(2, 32)
}

fn runtime_snapshot_serve_session_expiry_v233(now: Instant) -> Instant {
    now + runtime_snapshot_serve_session_inactivity_timeout_v233()
}

fn runtime_snapshot_serve_session_id_v221(
    peer: PeerId,
    height: u64,
    meta_sha256_hex: &str,
) -> String {
    let peer_s: String = peer
        .to_string()
        .chars()
        .filter(|c| c.is_ascii_alphanumeric())
        .take(96)
        .collect();
    let sha_s: String = meta_sha256_hex
        .chars()
        .filter(|c| c.is_ascii_hexdigit())
        .take(32)
        .collect();
    format!("peer_{}_height_{}_sha_{}", peer_s, height, sha_s)
}

fn runtime_snapshot_serve_session_root_v221(paths: &NodePaths) -> std::path::PathBuf {
    paths.snapshots_dir.join("auto").join("serve_sessions_v221")
}

fn runtime_snapshot_link_or_copy_file_v221(
    src: &std::path::Path,
    dst: &std::path::Path,
) -> Result<(), String> {
    if let Some(parent) = dst.parent() {
        fs::create_dir_all(parent)
            .map_err(|e| format!("mkdir {} failed: {}", parent.display(), e))?;
    }
    match fs::hard_link(src, dst) {
        Ok(()) => Ok(()),
        Err(link_err) => fs::copy(src, dst).map(|_| ()).map_err(|copy_err| {
            format!(
                "link_or_copy src={} dst={} hard_link_err={} copy_err={}",
                src.display(),
                dst.display(),
                link_err,
                copy_err
            )
        }),
    }
}

fn runtime_snapshot_serve_session_validate_dir_v221(
    dir: &std::path::Path,
    height: u64,
    chunks: u32,
    meta_sha256_hex: &str,
    max_frame: usize,
) -> Result<(), String> {
    let Some((meta, sha, _encoded)) = read_snapshot_v2_meta_for_transport_advertise(dir, max_frame)
        .map_err(|e| format!("meta_transport_error code={} message={}", e.code, e.message))?
    else {
        return Err(format!("meta_missing dir={}", dir.display()));
    };

    if meta.height != height {
        return Err(format!(
            "height_mismatch dir={} expected={} actual={}",
            dir.display(),
            height,
            meta.height
        ));
    }
    if meta.chunks != chunks {
        return Err(format!(
            "chunks_mismatch dir={} expected={} actual={}",
            dir.display(),
            chunks,
            meta.chunks
        ));
    }
    if sha != meta_sha256_hex {
        return Err(format!(
            "meta_sha_mismatch dir={} expected={} actual={}",
            dir.display(),
            meta_sha256_hex,
            sha
        ));
    }

    for idx in 0..chunks {
        let chunk_path = dir.join("chunks").join(format!("{:06}.bin", idx));
        if !chunk_path.is_file() {
            return Err(format!(
                "chunk_missing dir={} chunk_index={}",
                dir.display(),
                idx
            ));
        }
    }
    Ok(())
}

fn runtime_snapshot_make_pinned_serve_dir_v221(
    paths: &NodePaths,
    peer: PeerId,
    source_dir: &std::path::Path,
    meta: &SnapshotMeta,
    meta_sha256_hex: &str,
    max_frame: usize,
) -> Result<std::path::PathBuf, String> {
    let root = runtime_snapshot_serve_session_root_v221(paths);
    fs::create_dir_all(&root).map_err(|e| format!("mkdir {} failed: {}", root.display(), e))?;

    let session_id = runtime_snapshot_serve_session_id_v221(peer, meta.height, meta_sha256_hex);
    let final_dir = root.join(session_id);

    if final_dir.exists() {
        match runtime_snapshot_serve_session_validate_dir_v221(
            &final_dir,
            meta.height,
            meta.chunks,
            meta_sha256_hex,
            max_frame,
        ) {
            Ok(()) => return Ok(final_dir),
            Err(err) => {
                ng_warn!(
                    target: "p2p.snapshot",
                    "event=runtime_snapshot_serve_session_stale_pin_removed_v221 peer={} height={} dir={} err={}",
                    peer,
                    meta.height,
                    final_dir.display(),
                    err
                );
                let _ = fs::remove_dir_all(&final_dir);
            }
        }
    }

    let now_ms = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_else(|_| Duration::from_secs(0))
        .as_nanos();
    let tmp_dir = root.join(format!(
        ".tmp_{}_{}_{}",
        std::process::id(),
        meta.height,
        now_ms
    ));
    if tmp_dir.exists() {
        let _ = fs::remove_dir_all(&tmp_dir);
    }
    fs::create_dir_all(tmp_dir.join("chunks"))
        .map_err(|e| format!("mkdir tmp {} failed: {}", tmp_dir.display(), e))?;

    runtime_snapshot_link_or_copy_file_v221(
        &source_dir.join("meta.json"),
        &tmp_dir.join("meta.json"),
    )?;
    for idx in 0..meta.chunks {
        let src = source_dir.join("chunks").join(format!("{:06}.bin", idx));
        let dst = tmp_dir.join("chunks").join(format!("{:06}.bin", idx));
        runtime_snapshot_link_or_copy_file_v221(&src, &dst)?;
    }

    runtime_snapshot_serve_session_validate_dir_v221(
        &tmp_dir,
        meta.height,
        meta.chunks,
        meta_sha256_hex,
        max_frame,
    )?;

    fs::rename(&tmp_dir, &final_dir)
        .or_else(|rename_err| {
            if final_dir.exists() {
                let _ = fs::remove_dir_all(&tmp_dir);
                Ok(())
            } else {
                Err(rename_err)
            }
        })
        .map_err(|e| {
            format!(
                "rename pin {} -> {} failed: {}",
                tmp_dir.display(),
                final_dir.display(),
                e
            )
        })?;

    runtime_snapshot_serve_session_validate_dir_v221(
        &final_dir,
        meta.height,
        meta.chunks,
        meta_sha256_hex,
        max_frame,
    )?;

    Ok(final_dir)
}

fn runtime_snapshot_open_serve_session_v221(
    sessions: &Arc<Mutex<HashMap<(PeerId, u64), RuntimeSnapshotServeSessionV221>>>,
    paths: &NodePaths,
    peer: PeerId,
    source_dir: &std::path::Path,
    meta: &SnapshotMeta,
    meta_sha256_hex: &str,
    max_frame: usize,
) -> Result<std::path::PathBuf, String> {
    let pinned_dir = runtime_snapshot_make_pinned_serve_dir_v221(
        paths,
        peer,
        source_dir,
        meta,
        meta_sha256_hex,
        max_frame,
    )?;
    let ttl = runtime_snapshot_serve_session_ttl_v221();
    let now = Instant::now();
    let session = RuntimeSnapshotServeSessionV221 {
        dir: pinned_dir.clone(),
        meta_sha256_hex: meta_sha256_hex.to_string(),
        height: meta.height,
        chunks: meta.chunks,
        chunk_hashes_hex: meta.chunk_hashes_hex.clone(),
        expires_at: now + ttl,
        last_progress_at: now,
        last_chunk_served: None,
        bytes_served: 0,
        consecutive_failures: 0,
        last_successful_chunk: None,
        last_attempt_started_chunk: None,
        last_encoded_chunk: None,
        last_response_sent_chunk: None,
        last_acknowledged_chunk: None,
        last_attempt_started_at: None,
        last_encoded_at: None,
        last_sent_at: None,
        last_acknowledged_at: None,
        bytes_encoded: 0,
        bytes_sent: 0,
        state: RuntimeSnapshotServeSessionStateV233::Open,
    };
    {
        let mut guard = sessions.lock().unwrap_or_else(|e| e.into_inner());
        guard.insert((peer, meta.height), session);
    }
    ng_info!(
        target: "p2p.snapshot",
        "event=runtime_snapshot_serve_session_opened_v221 peer={} height={} chunks={} dir={} source_dir={} meta_sha256_hex={} expires_in_ms={}",
        peer,
        meta.height,
        meta.chunks,
        pinned_dir.display(),
        source_dir.display(),
        meta_sha256_hex,
        ttl.as_millis()
    );
    Ok(pinned_dir)
}

fn runtime_snapshot_get_serve_session_v221(
    sessions: &Arc<Mutex<HashMap<(PeerId, u64), RuntimeSnapshotServeSessionV221>>>,
    peer: PeerId,
    height: u64,
    now: Instant,
) -> Option<RuntimeSnapshotServeSessionV221> {
    let mut guard = sessions.lock().unwrap_or_else(|e| e.into_inner());
    guard.retain(|_, session| {
        session.expires_at > now && session.state != RuntimeSnapshotServeSessionStateV233::Stalled
    });
    guard.get(&(peer, height)).cloned()
}

fn runtime_snapshot_mark_serve_session_stalled_v249(
    session: &mut RuntimeSnapshotServeSessionV221,
    peer: PeerId,
    height: u64,
    chunk_index: u32,
    now: Instant,
    reason: &str,
) {
    session.state = RuntimeSnapshotServeSessionStateV233::Stalled;
    session.expires_at = now;
    ng_warn!(
        target: "p2p.snapshot",
        "event=runtime_snapshot_serve_session_stalled_v249 peer={} height={} chunk_index={} reason={} last_attempt_started_chunk={:?} last_encoded_chunk={:?} last_response_sent_chunk={:?} last_acknowledged_chunk={:?} last_attempt_started_at={:?} last_encoded_at={:?} last_sent_at={:?} last_acknowledged_at={:?} bytes_encoded={} bytes_sent={} repeated_attempts={} action=refetch_meta",
        peer,
        height,
        chunk_index,
        reason,
        session.last_attempt_started_chunk,
        session.last_encoded_chunk,
        session.last_response_sent_chunk,
        session.last_acknowledged_chunk,
        session.last_attempt_started_at,
        session.last_encoded_at,
        session.last_sent_at,
        session.last_acknowledged_at,
        session.bytes_encoded,
        session.bytes_sent,
        session.consecutive_failures
    );
}

fn runtime_snapshot_mark_serve_session_chunk_request_started_v249(
    sessions: &Arc<Mutex<HashMap<(PeerId, u64), RuntimeSnapshotServeSessionV221>>>,
    peer: PeerId,
    height: u64,
    chunk_index: u32,
    now: Instant,
) -> Option<RuntimeSnapshotServeSessionV221> {
    let mut guard = sessions.lock().unwrap_or_else(|e| e.into_inner());
    guard.retain(|_, session| {
        session.expires_at > now && session.state != RuntimeSnapshotServeSessionStateV233::Stalled
    });
    let session = guard.get_mut(&(peer, height))?;

    // V249: without a protocol ACK, the only reliable server-side ACK signal is the
    // client asking for the next chunk after a response was accepted by send_response.
    if chunk_index > 0 {
        if let Some(sent_chunk) = session.last_response_sent_chunk {
            let already_acked = session
                .last_acknowledged_chunk
                .map(|acked| acked >= sent_chunk)
                .unwrap_or(false);
            if chunk_index == sent_chunk.saturating_add(1) && !already_acked {
                session.last_acknowledged_chunk = Some(sent_chunk);
                session.last_successful_chunk = Some(sent_chunk);
                session.last_acknowledged_at = Some(now);
                session.last_progress_at = now;
                session.consecutive_failures = 0;
                session.state = RuntimeSnapshotServeSessionStateV233::Progressing;
                session.expires_at = runtime_snapshot_serve_session_expiry_v233(now);
                ng_debug!(
                    target: "p2p.snapshot",
                    "event=runtime_snapshot_chunk_implicit_ack_v249 peer={} height={} acked_chunk={} next_chunk_requested={} last_response_sent_chunk={:?}",
                    peer,
                    height,
                    sent_chunk,
                    chunk_index,
                    session.last_response_sent_chunk
                );
            }
        }
    }

    let repeated_already_acked = session
        .last_acknowledged_chunk
        .map(|acked| chunk_index <= acked)
        .unwrap_or(false);
    let repeated_unacked_attempt = session
        .last_attempt_started_chunk
        .map(|last| last == chunk_index)
        .unwrap_or(false)
        && session
            .last_acknowledged_chunk
            .map(|acked| acked < chunk_index)
            .unwrap_or(true);
    let repeated_unacked_sent = session
        .last_response_sent_chunk
        .map(|last| last == chunk_index)
        .unwrap_or(false)
        && session
            .last_acknowledged_chunk
            .map(|acked| acked < chunk_index)
            .unwrap_or(true);

    if repeated_already_acked || repeated_unacked_attempt || repeated_unacked_sent {
        // V272: chunk serving must be idempotent. During a cold-start bootstrap a
        // client may retry the same chunk after a timeout, dropped response, or
        // local decode race even when the server side session is still valid.
        // Treating those retries as serve-session failures caused D to lose its
        // pinned snapshot session and to loop on `refetch_meta` instead of
        // completing the bundle. Repeated chunk requests are therefore accepted
        // and re-served; real corruption is still caught by per-chunk hash checks
        // in `runtime_snapshot_encode_chunk_response_v221`.
        let repeat_reason = if repeated_already_acked {
            "repeated_already_acknowledged_chunk"
        } else if repeated_unacked_sent {
            "repeated_unacknowledged_sent_chunk"
        } else {
            "repeated_unacknowledged_attempt"
        };
        session.consecutive_failures = 0;
        session.state = RuntimeSnapshotServeSessionStateV233::Progressing;
        session.last_progress_at = now;
        session.expires_at = runtime_snapshot_serve_session_expiry_v233(now);
        ng_debug!(
            target: "p2p.snapshot",
            "event=runtime_snapshot_repeated_chunk_request_idempotent_v272 peer={} height={} chunk_index={} reason={} last_acknowledged_chunk={:?} last_response_sent_chunk={:?} action=reserve_same_chunk",
            peer,
            height,
            chunk_index,
            repeat_reason,
            session.last_acknowledged_chunk,
            session.last_response_sent_chunk
        );
    } else {
        session.state = RuntimeSnapshotServeSessionStateV233::Progressing;
        session.last_progress_at = now;
        session.expires_at = runtime_snapshot_serve_session_expiry_v233(now);
    }

    session.last_attempt_started_chunk = Some(chunk_index);
    session.last_attempt_started_at = Some(now);

    Some(session.clone())
}

fn runtime_snapshot_mark_serve_session_chunk_response_encoded_v249(
    sessions: &Arc<Mutex<HashMap<(PeerId, u64), RuntimeSnapshotServeSessionV221>>>,
    peer: PeerId,
    height: u64,
    chunk_index: u32,
    raw_bytes: u64,
    encoded_bytes: usize,
    now: Instant,
) -> Option<RuntimeSnapshotServeSessionV221> {
    let mut guard = sessions.lock().unwrap_or_else(|e| e.into_inner());
    guard.retain(|_, session| {
        session.expires_at > now && session.state != RuntimeSnapshotServeSessionStateV233::Stalled
    });
    let session = guard.get_mut(&(peer, height))?;
    session.last_encoded_chunk = Some(chunk_index);
    session.last_encoded_at = Some(now);
    session.bytes_encoded = session.bytes_encoded.saturating_add(encoded_bytes as u64);
    session.state = RuntimeSnapshotServeSessionStateV233::Progressing;
    session.expires_at = runtime_snapshot_serve_session_expiry_v233(now);
    ng_debug!(
        target: "p2p.snapshot",
        "event=runtime_snapshot_chunk_response_encoded_v249 peer={} height={} chunk_index={} raw_bytes={} encoded_bytes={} last_successful_chunk={:?}",
        peer,
        height,
        chunk_index,
        raw_bytes,
        encoded_bytes,
        session.last_successful_chunk
    );
    Some(session.clone())
}

fn runtime_snapshot_mark_serve_session_chunk_response_sent_v249(
    sessions: &Arc<Mutex<HashMap<(PeerId, u64), RuntimeSnapshotServeSessionV221>>>,
    peer: PeerId,
    height: u64,
    chunk_index: u32,
    raw_bytes: u64,
    encoded_bytes: usize,
    pinned_v221: bool,
    send_ok: bool,
    now: Instant,
) -> Option<RuntimeSnapshotServeSessionV221> {
    let mut guard = sessions.lock().unwrap_or_else(|e| e.into_inner());
    guard.retain(|_, session| {
        session.expires_at > now && session.state != RuntimeSnapshotServeSessionStateV233::Stalled
    });
    let session = guard.get_mut(&(peer, height))?;

    if send_ok {
        session.last_response_sent_chunk = Some(chunk_index);
        session.last_chunk_served = Some(chunk_index);
        session.last_sent_at = Some(now);
        session.bytes_sent = session.bytes_sent.saturating_add(raw_bytes);
        session.bytes_served = session.bytes_served.saturating_add(raw_bytes);
        session.state = RuntimeSnapshotServeSessionStateV233::Progressing;
        session.expires_at = runtime_snapshot_serve_session_expiry_v233(now);
        ng_debug!(
            target: "p2p.snapshot",
            "event=runtime_snapshot_chunk_response_sent_v249 peer={} height={} chunk_index={} raw_bytes={} encoded_bytes={} pinned_v221={} last_acknowledged_chunk={:?}",
            peer,
            height,
            chunk_index,
            raw_bytes,
            encoded_bytes,
            pinned_v221,
            session.last_acknowledged_chunk
        );
    } else {
        // V272: a failed `send_response` usually means the requester timed out or
        // closed the channel while the server was encoding/sending a large
        // snapshot chunk. This is not proof that the pinned snapshot bundle is
        // bad. Keep the session open so the client can retry the same chunk
        // idempotently instead of forcing a meta-refetch loop.
        session.consecutive_failures = session.consecutive_failures.saturating_add(1);
        session.state = RuntimeSnapshotServeSessionStateV233::Progressing;
        session.expires_at = runtime_snapshot_serve_session_expiry_v233(now);
        ng_warn!(
            target: "p2p.snapshot",
            "event=runtime_snapshot_chunk_response_send_failed_idempotent_v272 peer={} height={} chunk_index={} raw_bytes={} encoded_bytes={} pinned_v221={} send_failures={} last_successful_chunk={:?} action=keep_session_open_for_chunk_retry",
            peer,
            height,
            chunk_index,
            raw_bytes,
            encoded_bytes,
            pinned_v221,
            session.consecutive_failures,
            session.last_successful_chunk
        );
    }

    Some(session.clone())
}

fn runtime_snapshot_serve_session_is_stalled_v233(
    sessions: &Arc<Mutex<HashMap<(PeerId, u64), RuntimeSnapshotServeSessionV221>>>,
    peer: PeerId,
    height: u64,
    now: Instant,
) -> bool {
    let guard = sessions.lock().unwrap_or_else(|e| e.into_inner());
    guard
        .get(&(peer, height))
        .map(|session| {
            session.state == RuntimeSnapshotServeSessionStateV233::Stalled
                || session.expires_at <= now
        })
        .unwrap_or(false)
}

fn runtime_snapshot_serve_sessions_len_v221(
    sessions: &Arc<Mutex<HashMap<(PeerId, u64), RuntimeSnapshotServeSessionV221>>>,
) -> usize {
    let guard = sessions.lock().unwrap_or_else(|e| e.into_inner());
    guard.len()
}

fn runtime_snapshot_active_serve_peers_v223(
    sessions: &Arc<Mutex<HashMap<(PeerId, u64), RuntimeSnapshotServeSessionV221>>>,
    now: Instant,
) -> HashSet<PeerId> {
    let mut guard = sessions.lock().unwrap_or_else(|e| e.into_inner());
    guard.retain(|_, session| {
        session.expires_at > now && session.state != RuntimeSnapshotServeSessionStateV233::Stalled
    });
    guard.keys().map(|(peer, _height)| *peer).collect()
}

fn runtime_recovery_non_operational_peers_v231(
    active_serve_peers: &HashSet<PeerId>,
    snapshot_chunk_pending: &HashMap<
        request_response::OutboundRequestId,
        PendingRuntimeSnapshotChunk,
    >,
    snapshot_retry_queue: &VecDeque<RuntimeSnapshotRetryV220>,
) -> HashSet<PeerId> {
    let mut peers = active_serve_peers.clone();
    for pending in snapshot_chunk_pending.values() {
        peers.insert(pending.peer);
    }
    for item in snapshot_retry_queue.iter() {
        match item {
            RuntimeSnapshotRetryV220::Meta { pending, .. } => {
                peers.insert(pending.peer);
            }
            RuntimeSnapshotRetryV220::Chunk { pending, .. } => {
                peers.insert(pending.peer);
            }
        }
    }
    peers
}

fn runtime_snapshot_bootstrap_client_ttl_v264() -> Duration {
    Duration::from_secs(15 * 60)
}

fn runtime_note_snapshot_bootstrap_client_v264(
    clients: &mut HashMap<PeerId, Instant>,
    peer: PeerId,
    telemetry_height: u64,
    runtime_sync_caught_up: bool,
    runtime_bootstrap_complete: bool,
    now: Instant,
) -> bool {
    // V269/V285: do not classify a high-height disk-restart peer as a snapshot/bootstrap
    // client solely because its exported caught/boot flags are still false.
    // During a simultaneous A/B/C restart, each node can load a pruned tip from
    // disk and initially export caught=false/p2p_ready=false until it observes
    // the other peers. Treating every !caught/!boot peer as recovery created a
    // circular fail-closed deadlock: no peer could become an operational
    // candidate because all peers were marked non-operational.
    //
    // V285: real cold-start snapshot clients remain in the recovery/non-operational
    // scope even after their telemetry height jumps above genesis, until they
    // export both runtime_sync_caught_up and runtime_bootstrap_complete. This
    // prevents the warm-restart shortcut from admitting SnapshotColdStart peers
    // into quorum/mining admission before post-snapshot reconciliation.
    let was_bootstrap_client = clients.contains_key(&peer);
    let still_reconciling_after_snapshot_v285 =
        was_bootstrap_client && !(runtime_sync_caught_up && runtime_bootstrap_complete);
    let is_bootstrap_client = telemetry_height <= 1 || still_reconciling_after_snapshot_v285;
    if is_bootstrap_client {
        clients.insert(peer, now);
    } else {
        clients.remove(&peer);
    }
    is_bootstrap_client
}

fn runtime_restart_warm_candidate_v269(
    telemetry_height: u64,
    telemetry_finalized_height: Option<u64>,
    telemetry_finalized_hash: Option<&str>,
    finalized_hash_compatible: bool,
    runtime_sync_caught_up: bool,
    runtime_bootstrap_complete: bool,
) -> bool {
    // V269: restart-warm peers that have loaded real chain state from disk may
    // temporarily export caught=false/boot=false before the operational quorum is
    // re-established. If they provide non-genesis height plus compatible
    // finalized evidence, they are safe to admit as lifecycle candidates. This
    // breaks the simultaneous-restart deadlock without admitting cold-start D
    // during snapshot download: D has height 0/1 or is in an active snapshot
    // serve scope and remains recovery/non-operational.
    if runtime_sync_caught_up && runtime_bootstrap_complete {
        return true;
    }
    telemetry_height > 1
        && finalized_hash_compatible
        && telemetry_finalized_height.unwrap_or(0) > 0
        && telemetry_finalized_hash
            .map(|h| !h.trim().is_empty())
            .unwrap_or(false)
}

fn runtime_note_snapshot_bootstrap_client_into_recovery_scope_v265(
    clients: &mut HashMap<PeerId, Instant>,
    recovery_scope: &mut HashSet<PeerId>,
    peer: PeerId,
    telemetry_height: u64,
    runtime_sync_caught_up: bool,
    runtime_bootstrap_complete: bool,
    now: Instant,
) -> bool {
    // V265: the current telemetry event must affect the recovery scope immediately.
    // V264 recorded the bootstrap client, but the already-built recovery set used by
    // the same hello/pulse could miss that peer until the next actor tick. That left
    // a one-cycle window where a cold-start validator could be evaluated by the
    // operational-candidate path. Keep the scope synchronous with the observation.
    let is_bootstrap_client = runtime_note_snapshot_bootstrap_client_v264(
        clients,
        peer,
        telemetry_height,
        runtime_sync_caught_up,
        runtime_bootstrap_complete,
        now,
    );
    if is_bootstrap_client {
        recovery_scope.insert(peer);
    } else {
        recovery_scope.remove(&peer);
    }
    is_bootstrap_client
}

fn runtime_snapshot_bootstrap_clients_prune_v264(
    clients: &mut HashMap<PeerId, Instant>,
    now: Instant,
) {
    let ttl = runtime_snapshot_bootstrap_client_ttl_v264();
    clients.retain(|_, observed_at| now.duration_since(*observed_at) <= ttl);
}

fn runtime_recovery_non_operational_peers_v264(
    active_serve_peers: &HashSet<PeerId>,
    snapshot_chunk_pending: &HashMap<
        request_response::OutboundRequestId,
        PendingRuntimeSnapshotChunk,
    >,
    snapshot_retry_queue: &VecDeque<RuntimeSnapshotRetryV220>,
    snapshot_bootstrap_clients: &mut HashMap<PeerId, Instant>,
    now: Instant,
) -> HashSet<PeerId> {
    runtime_snapshot_bootstrap_clients_prune_v264(snapshot_bootstrap_clients, now);
    let mut peers = runtime_recovery_non_operational_peers_v231(
        active_serve_peers,
        snapshot_chunk_pending,
        snapshot_retry_queue,
    );
    peers.extend(snapshot_bootstrap_clients.keys().copied());
    peers
}

fn runtime_snapshot_mark_served_bootstrap_client_v289(
    snapshot_bootstrap_clients: &mut HashMap<PeerId, Instant>,
    peer: PeerId,
    now: Instant,
) {
    // V289: a peer that requests a runtime snapshot from an already-operational
    // validator is a recovery client until it later exports both boot=true and
    // caught=true. V285 kept cold-start peers quarantined only if their own
    // telemetry had already been seen at height 0/1; in the real D test the
    // server first observed D while serving snapshot meta/chunks, and later saw
    // D at height 52255 but still in RestartCatchup. Persisting this marker
    // prevents that post-snapshot peer from entering operational readiness or
    // overwriting ready validator observations while it is still reconciling.
    snapshot_bootstrap_clients.insert(peer, now);
}

fn runtime_recovery_quarantine_peer_caches_v289(
    recovery_peers: &HashSet<PeerId>,
    runtime_candidates: &mut HashMap<PeerId, PeerRuntimeOperationalCandidateV236>,
    catchup_candidates: &mut HashMap<PeerId, PeerRuntimeCatchupCandidateV287>,
    lifecycle_registry: &mut HashMap<PeerId, PeerLifecycleObservationV236>,
) {
    // V289: recovery/catch-up peers must not leave stale OperationalCandidate
    // or catch-up-source entries behind after their phase changes or after the
    // connection drops/reconnects. Removing only the affected peers keeps A/B/C
    // operational evidence intact and avoids broad cache resets.
    for peer in recovery_peers {
        runtime_candidates.remove(peer);
        catchup_candidates.remove(peer);
        lifecycle_registry.remove(peer);
    }
}

fn runtime_peer_identity_quarantine_ttl_v292() -> Duration {
    Duration::from_secs(10 * 60)
}

fn runtime_peer_identity_quarantine_prune_v292(
    quarantined: &mut HashMap<PeerId, Instant>,
    connected: &HashSet<PeerId>,
    now: Instant,
) {
    let ttl = runtime_peer_identity_quarantine_ttl_v292();
    quarantined.retain(|peer, observed_at| {
        connected.contains(peer) && now.duration_since(*observed_at) <= ttl
    });
}

#[allow(clippy::too_many_arguments)]
fn runtime_peer_identity_quarantine_consensus_caches_v292(
    peer: &PeerId,
    hello_ok: &mut HashSet<PeerId>,
    hello_received: &mut HashSet<PeerId>,
    hello_sent_after_connect: &mut HashSet<PeerId>,
    hello_pending: &mut HashSet<PeerId>,
    peer_vsh_mismatch: &mut HashSet<PeerId>,
    peer_heights: &mut HashMap<PeerId, u64>,
    peer_tip_hashes: &mut HashMap<PeerId, String>,
    runtime_candidates: &mut HashMap<PeerId, PeerRuntimeOperationalCandidateV236>,
    catchup_candidates: &mut HashMap<PeerId, PeerRuntimeCatchupCandidateV287>,
    lifecycle_registry: &mut HashMap<PeerId, PeerLifecycleObservationV236>,
) {
    // V292: an identity/chain/genesis-mismatched peer may keep using public
    // data-plane RRv3 snapshot/chunk paths, but it must be invisible to
    // consensus/admission/quorum/proposal state until it later sends a direct,
    // valid Hello and ready telemetry.
    hello_ok.remove(peer);
    hello_received.remove(peer);
    hello_sent_after_connect.remove(peer);
    hello_pending.remove(peer);
    peer_vsh_mismatch.remove(peer);
    peer_heights.remove(peer);
    peer_tip_hashes.remove(peer);
    runtime_candidates.remove(peer);
    catchup_candidates.remove(peer);
    lifecycle_registry.remove(peer);
}

#[allow(clippy::too_many_arguments)]
fn runtime_peer_identity_quarantine_mark_v292(
    quarantined: &mut HashMap<PeerId, Instant>,
    peer: PeerId,
    now: Instant,
    hello_ok: &mut HashSet<PeerId>,
    hello_received: &mut HashSet<PeerId>,
    hello_sent_after_connect: &mut HashSet<PeerId>,
    hello_pending: &mut HashSet<PeerId>,
    peer_vsh_mismatch: &mut HashSet<PeerId>,
    peer_heights: &mut HashMap<PeerId, u64>,
    peer_tip_hashes: &mut HashMap<PeerId, String>,
    runtime_candidates: &mut HashMap<PeerId, PeerRuntimeOperationalCandidateV236>,
    catchup_candidates: &mut HashMap<PeerId, PeerRuntimeCatchupCandidateV287>,
    lifecycle_registry: &mut HashMap<PeerId, PeerLifecycleObservationV236>,
) {
    quarantined.insert(peer, now);
    runtime_peer_identity_quarantine_consensus_caches_v292(
        &peer,
        hello_ok,
        hello_received,
        hello_sent_after_connect,
        hello_pending,
        peer_vsh_mismatch,
        peer_heights,
        peer_tip_hashes,
        runtime_candidates,
        catchup_candidates,
        lifecycle_registry,
    );
}

fn runtime_peer_identity_quarantined_v292(
    quarantined: &HashMap<PeerId, Instant>,
    peer: &PeerId,
    now: Instant,
) -> bool {
    quarantined
        .get(peer)
        .map(|observed_at| {
            now.duration_since(*observed_at) <= runtime_peer_identity_quarantine_ttl_v292()
        })
        .unwrap_or(false)
}

fn runtime_ready_telemetry_may_update_operational_observation_v289(
    runtime_sync_caught_up: bool,
    runtime_bootstrap_complete: bool,
) -> bool {
    // V289: operational quorum status only consumes boot+caught telemetry.
    // Non-ready telemetry is still logged and can keep a peer quarantined, but
    // it must not overwrite a fresh ready observation for A/B/C and collapse
    // the runtime quorum until TTL expiry or a real ready update arrives.
    runtime_sync_caught_up && runtime_bootstrap_complete
}

fn runtime_snapshot_recovery_hold_steady_operational_v264(
    boot_phase: P2pBootPhase,
    was_runtime_caught_up: bool,
    was_p2p_ready: bool,
    snapshot_recovery_peer_count: usize,
    snapshot_pending_count: usize,
    snapshot_retry_count: usize,
) -> bool {
    // V264 hard invariant: if this validator is already steady/caught-up/ready,
    // inbound cold-start snapshot clients must not flip local readiness false.
    // Real local regressions still fail closed when there is no snapshot/recovery
    // pressure or when the node was not healthy before the recovery peer arrived.
    runtime_snapshot_recovery_pressure_active_v231(
        boot_phase,
        snapshot_recovery_peer_count,
        snapshot_pending_count,
        snapshot_retry_count,
    ) && was_runtime_caught_up
        && was_p2p_ready
}

fn runtime_snapshot_serve_sessions_clear_v221(
    sessions: &Arc<Mutex<HashMap<(PeerId, u64), RuntimeSnapshotServeSessionV221>>>,
    remove_dirs: bool,
) {
    let dirs: Vec<std::path::PathBuf> = {
        let mut guard = sessions.lock().unwrap_or_else(|e| e.into_inner());
        let dirs = guard.values().map(|s| s.dir.clone()).collect::<Vec<_>>();
        guard.clear();
        dirs
    };
    if remove_dirs {
        for dir in dirs {
            if let Err(err) = fs::remove_dir_all(&dir) {
                ng_debug!(
                    target: "p2p.snapshot",
                    "event=runtime_snapshot_serve_session_remove_dir_failed_v221 dir={} err={}",
                    dir.display(),
                    err
                );
            }
        }
    }
}

fn runtime_snapshot_serve_sessions_prune_v221(
    sessions: &Arc<Mutex<HashMap<(PeerId, u64), RuntimeSnapshotServeSessionV221>>>,
    now: Instant,
) {
    let expired_dirs: Vec<std::path::PathBuf> = {
        let mut guard = sessions.lock().unwrap_or_else(|e| e.into_inner());
        let mut expired_dirs = Vec::new();
        guard.retain(|_, session| {
            let keep = session.expires_at > now
                && session.state != RuntimeSnapshotServeSessionStateV233::Stalled;
            if !keep {
                expired_dirs.push(session.dir.clone());
            }
            keep
        });
        expired_dirs
    };
    for dir in expired_dirs {
        match fs::remove_dir_all(&dir) {
            Ok(()) => ng_info!(
                target: "p2p.snapshot",
                "event=runtime_snapshot_serve_session_expired_removed_v221 dir={}",
                dir.display()
            ),
            Err(err) => ng_debug!(
                target: "p2p.snapshot",
                "event=runtime_snapshot_serve_session_expired_remove_failed_v221 dir={} err={}",
                dir.display(),
                err
            ),
        }
    }
}

fn runtime_snapshot_encode_chunk_response_v221(
    dir: &std::path::Path,
    height: u64,
    chunk_index: u32,
    max_frame: usize,
    peer: PeerId,
    pinned_v221: bool,
    expected_chunk_sha_hex: Option<&str>,
) -> (Vec<u8>, Option<RrV3StrikeReason>) {
    let chunk_path = dir.join("chunks").join(format!("{:06}.bin", chunk_index));
    match fs::read(&chunk_path) {
        Ok(chunk_bytes) => {
            if let Some(expected_sha) = expected_chunk_sha_hex {
                let actual_sha = format!("{:x}", Sha256::digest(&chunk_bytes));
                if actual_sha != expected_sha {
                    ng_warn!(
                        target: "p2p.snapshot",
                        "event=pinned_snapshot_chunk_hash_mismatch_v221 peer={} height={} chunk_index={} expected_sha={} actual_sha={} path={} pinned_v221={}",
                        peer,
                        height,
                        chunk_index,
                        expected_sha,
                        actual_sha,
                        chunk_path.display(),
                        pinned_v221
                    );
                    return (
                        encode_rr_v3(&RrV3Msg::Error {
                            code: 409,
                            message: "pinned_snapshot_chunk_hash_mismatch_v221".to_string(),
                        }),
                        None,
                    );
                }
            }

            let max_payload = rrv3_safe_snapshot_chunk_bytes(max_frame);
            if chunk_bytes.len() > max_payload {
                ng_warn!(
                    target: "p2p.snapshot",
                    "event=runtime_snapshot_chunk_oversize_v221 height={} chunk_index={} raw_bytes={} max_payload={} frame_bytes={} peer={} path={} pinned_v221={}",
                    height,
                    chunk_index,
                    chunk_bytes.len(),
                    max_payload,
                    max_frame,
                    peer,
                    chunk_path.display(),
                    pinned_v221
                );
                let err = encode_rr_v3(&RrV3Msg::Error {
                    code: 413,
                    message: "rrv3_resp_too_large".to_string(),
                });
                (err, Some(RrV3StrikeReason::Oversize))
            } else {
                let b64 = STANDARD.encode(&chunk_bytes);
                let msg = RrV3Msg::SnapshotV2Chunk {
                    height,
                    chunk_index,
                    data_b64: b64,
                };
                let out = encode_rr_v3(&msg);
                if out.len() > max_frame {
                    let err = encode_rr_v3(&RrV3Msg::Error {
                        code: 413,
                        message: "rrv3_resp_too_large".to_string(),
                    });
                    (err, Some(RrV3StrikeReason::Oversize))
                } else {
                    if runtime_snapshot_progress_log_chunk_v222(chunk_index, u32::MAX) {
                        ng_info!(
                            target: "p2p.snapshot",
                            "event=runtime_snapshot_chunk_encoded_progress_v249 peer={} height={} chunk_index={} path={} pinned_v221={} bytes={}",
                            peer,
                            height,
                            chunk_index,
                            chunk_path.display(),
                            pinned_v221,
                            chunk_bytes.len()
                        );
                    } else {
                        ng_debug!(
                            target: "p2p.snapshot",
                            "event=runtime_snapshot_chunk_encoded_v249 peer={} height={} chunk_index={} path={} pinned_v221={} bytes={}",
                            peer,
                            height,
                            chunk_index,
                            chunk_path.display(),
                            pinned_v221,
                            chunk_bytes.len()
                        );
                    }
                    (out, None)
                }
            }
        }
        Err(err) => {
            let message = if pinned_v221 {
                "pinned_snapshot_chunk_missing_v221"
            } else {
                "chunk_not_found"
            };
            ng_warn!(
                target: "p2p.snapshot",
                "event=runtime_snapshot_chunk_missing_v221 peer={} height={} chunk_index={} path={} pinned_v221={} err={}",
                peer,
                height,
                chunk_index,
                chunk_path.display(),
                pinned_v221,
                err
            );
            (
                encode_rr_v3(&RrV3Msg::Error {
                    code: 404,
                    message: message.to_string(),
                }),
                None,
            )
        }
    }
}

fn runtime_snapshot_retry_backoff_v220(initial_retries: u8, retries_left_after: u8) -> Duration {
    let attempts_used = initial_retries.saturating_sub(retries_left_after).max(1);
    let ms = match attempts_used {
        0 | 1 => 250,
        2 => 500,
        3 => 1_000,
        4 => 1_500,
        _ => 2_000,
    };
    Duration::from_millis(ms)
}

enum RuntimeSnapshotRetryV220 {
    Meta {
        due_at: Instant,
        pending: PendingRuntimeSnapshotMeta,
    },
    Chunk {
        due_at: Instant,
        pending: PendingRuntimeSnapshotChunk,
    },
}

fn rr_v3_msg_kind_name(msg: &RrV3Msg) -> &'static str {
    match msg {
        RrV3Msg::GetHeaders { .. } => "GetHeaders",
        RrV3Msg::Headers { .. } => "Headers",
        RrV3Msg::GetSnapshotV2Latest => "GetSnapshotV2Latest",
        RrV3Msg::GetSnapshotV2Meta { .. } => "GetSnapshotV2Meta",
        RrV3Msg::SnapshotV2Meta { .. } => "SnapshotV2Meta",
        RrV3Msg::GetSnapshotV2Chunk { .. } => "GetSnapshotV2Chunk",
        RrV3Msg::SnapshotV2Chunk { .. } => "SnapshotV2Chunk",
        RrV3Msg::GetCheckpointCertLatest => "GetCheckpointCertLatest",
        RrV3Msg::CheckpointCertLatest { .. } => "CheckpointCertLatest",
        RrV3Msg::Error { .. } => "Error",
    }
}

fn runtime_snapshot_chunk_kind_mismatch_error(
    response_peer: PeerId,
    pending: &PendingRuntimeSnapshotChunk,
    received_kind: &str,
) -> String {
    format!(
        "runtime snapshot chunk response kind mismatch expected=SnapshotV2Chunk received={} peer={} expected_peer={} request_id={:?} height={} chunk_index={}",
        received_kind,
        response_peer,
        pending.peer,
        pending.request_id,
        pending.height,
        pending.chunk_index,
    )
}

fn runtime_snapshot_chunk_correlation_mismatch_error(
    response_peer: PeerId,
    pending: &PendingRuntimeSnapshotChunk,
    received_height: u64,
    received_chunk_index: u32,
) -> String {
    format!(
        "runtime snapshot chunk response correlation mismatch peer={} expected_peer={} request_id={:?} expected_height={} expected_chunk_index={} received_height={} received_chunk_index={}",
        response_peer,
        pending.peer,
        pending.request_id,
        pending.height,
        pending.chunk_index,
        received_height,
        received_chunk_index,
    )
}

fn rr_v3_error_response(code: u16, message: impl Into<String>) -> Vec<u8> {
    encode_rr_v3(&RrV3Msg::Error {
        code: u32::from(code),
        message: message.into(),
    })
}

struct PendingRuntimeBootstrapProbe {
    peer: PeerId,
    deadline: Instant,
}

#[derive(Clone, Copy, Debug)]
struct RuntimeBootstrapSnapshotSignal {
    height: u64,
    seen_at: Instant,
}

/// Clears all non-canonical live P2P caches for a hard-banned peer.
/// Returns the last known dial address, if any, so the caller can demote it in PeerBook
/// before disconnecting. This keeps hard-ban enforcement consistent across connect,
/// gossip, RR and periodic reputation ticks.
fn clear_hard_banned_peer_runtime_caches_v1(
    peer: &PeerId,
    hello_pending: &mut HashSet<PeerId>,
    hello_ok: &mut HashSet<PeerId>,
    hello_received: &mut HashSet<PeerId>,
    hello_sent_after_connect: &mut HashSet<PeerId>,
    peer_vsh_mismatch: &mut HashSet<PeerId>,
    peer_heights: &mut HashMap<PeerId, u64>,
    peer_tip_hashes: &mut HashMap<PeerId, String>,
    peer_snapshot_v2: &mut HashMap<PeerId, PeerSnapshotV2Advert>,
    connected_bootstrap_peers: &mut HashSet<PeerId>,
    runtime_rr_bootstrap_ready: &mut HashMap<PeerId, RuntimeBootstrapSnapshotSignal>,
    peer_last_seen: &mut HashMap<PeerId, Instant>,
    peer_last_addr: &mut HashMap<PeerId, String>,
    rep_protected: &mut HashSet<PeerId>,
) -> Option<String> {
    hello_pending.remove(peer);
    hello_ok.remove(peer);
    hello_received.remove(peer);
    hello_sent_after_connect.remove(peer);
    peer_vsh_mismatch.remove(peer);
    peer_heights.remove(peer);
    peer_tip_hashes.remove(peer);
    peer_snapshot_v2.remove(peer);
    connected_bootstrap_peers.remove(peer);
    runtime_rr_bootstrap_ready.remove(peer);
    peer_last_seen.remove(peer);
    rep_protected.remove(peer);
    peer_last_addr.remove(peer)
}

fn runtime_bootstrap_ready_lag_max() -> u64 {
    std::env::var("NEWGEN_RUNTIME_BOOTSTRAP_READY_LAG_MAX")
        .ok()
        .and_then(|s| s.trim().parse::<u64>().ok())
        .unwrap_or(64)
        .clamp(0, 4096)
}

fn runtime_bootstrap_signal_for_peer(
    peer: &PeerId,
    peer_snapshot_v2: &HashMap<PeerId, PeerSnapshotV2Advert>,
    runtime_rr_bootstrap_ready: &HashMap<PeerId, RuntimeBootstrapSnapshotSignal>,
) -> Option<RuntimeBootstrapSnapshotSignal> {
    let advert = peer_snapshot_v2
        .get(peer)
        .map(|adv| RuntimeBootstrapSnapshotSignal {
            height: adv.height,
            seen_at: adv.seen_at,
        });
    match (advert, runtime_rr_bootstrap_ready.get(peer).copied()) {
        (Some(a), Some(b)) => Some(if b.height > a.height {
            b
        } else if b.height < a.height {
            a
        } else if b.seen_at > a.seen_at {
            b
        } else {
            a
        }),
        (Some(a), None) => Some(a),
        (None, Some(b)) => Some(b),
        (None, None) => None,
    }
}

fn cold_start_snapshot_chunk_peer_eligible_v212(
    boot_phase: P2pBootPhase,
    peer: &PeerId,
    snapshot_height: u64,
    connected_bootstrap_peers: &HashSet<PeerId>,
    peer_snapshot_v2: &HashMap<PeerId, PeerSnapshotV2Advert>,
    runtime_rr_bootstrap_ready: &HashMap<PeerId, RuntimeBootstrapSnapshotSignal>,
) -> bool {
    if !matches!(boot_phase, P2pBootPhase::ColdStartSnapshot) {
        return true;
    }

    if connected_bootstrap_peers.contains(peer) {
        return true;
    }

    // V212: if this peer already returned a valid SnapshotV2Meta through the
    // runtime RRv3 bootstrap path for the exact bundle height, it is allowed to
    // serve chunks for that same bundle. This keeps cold-start fail-closed while
    // avoiding a race where connected_bootstrap_peers is pruned between meta
    // selection and chunk download.
    runtime_bootstrap_signal_for_peer(peer, peer_snapshot_v2, runtime_rr_bootstrap_ready)
        .map(|signal| signal.height >= snapshot_height)
        .unwrap_or(false)
}

fn runtime_bootstrap_required_height(
    height_opt: Option<u64>,
    connected_bootstrap_peers: &HashSet<PeerId>,
    peer_heights: &HashMap<PeerId, u64>,
    lag_max: u64,
) -> Option<u64> {
    if let Some(height) = height_opt {
        return Some(height);
    }
    let max_known = connected_bootstrap_peers
        .iter()
        .filter_map(|peer| peer_heights.get(peer).copied())
        .max();
    max_known.map(|h| h.saturating_sub(lag_max))
}

fn runtime_bootstrap_signal_is_adequate(
    peer: &PeerId,
    height_opt: Option<u64>,
    connected_bootstrap_peers: &HashSet<PeerId>,
    peer_heights: &HashMap<PeerId, u64>,
    peer_snapshot_v2: &HashMap<PeerId, PeerSnapshotV2Advert>,
    runtime_rr_bootstrap_ready: &HashMap<PeerId, RuntimeBootstrapSnapshotSignal>,
    lag_max: u64,
) -> bool {
    let Some(signal) =
        runtime_bootstrap_signal_for_peer(peer, peer_snapshot_v2, runtime_rr_bootstrap_ready)
    else {
        return false;
    };
    let Some(required_height) = runtime_bootstrap_required_height(
        height_opt,
        connected_bootstrap_peers,
        peer_heights,
        lag_max,
    ) else {
        return true;
    };
    signal.height >= required_height
}

fn runtime_bootstrap_ready_with_lag(
    boot_phase: P2pBootPhase,
    connected_now: &HashSet<PeerId>,
    connected_bootstrap_peers: &HashSet<PeerId>,
    peer_heights: &HashMap<PeerId, u64>,
    peer_snapshot_v2: &HashMap<PeerId, PeerSnapshotV2Advert>,
    runtime_rr_bootstrap_ready: &HashMap<PeerId, RuntimeBootstrapSnapshotSignal>,
    height_opt: Option<u64>,
    lag_max: u64,
) -> bool {
    match boot_phase {
        P2pBootPhase::ColdStartSnapshot => connected_bootstrap_peers.iter().any(|peer| {
            runtime_bootstrap_signal_is_adequate(
                peer,
                height_opt,
                connected_bootstrap_peers,
                peer_heights,
                peer_snapshot_v2,
                runtime_rr_bootstrap_ready,
                lag_max,
            )
        }),
        P2pBootPhase::RestartCatchup | P2pBootPhase::FallbackLiveSync => !connected_now.is_empty(),
        P2pBootPhase::SteadyState => true,
    }
}

fn runtime_bootstrap_ready(
    boot_phase: P2pBootPhase,
    connected_now: &HashSet<PeerId>,
    connected_bootstrap_peers: &HashSet<PeerId>,
    peer_heights: &HashMap<PeerId, u64>,
    peer_snapshot_v2: &HashMap<PeerId, PeerSnapshotV2Advert>,
    runtime_rr_bootstrap_ready: &HashMap<PeerId, RuntimeBootstrapSnapshotSignal>,
    height_opt: Option<u64>,
) -> bool {
    runtime_bootstrap_ready_with_lag(
        boot_phase,
        connected_now,
        connected_bootstrap_peers,
        peer_heights,
        peer_snapshot_v2,
        runtime_rr_bootstrap_ready,
        height_opt,
        runtime_bootstrap_ready_lag_max(),
    )
}

#[inline]
fn runtime_snapshot_ctrl_housekeeping_active(
    bootstrap_waiters_len: usize,
    meta_pending_len: usize,
    cert_pending_len: usize,
    chunk_pending_len: usize,
    probe_pending_len: usize,
    retry_pending_len: usize,
    chunk_session_len: usize,
    serve_session_len_v221: usize,
) -> bool {
    bootstrap_waiters_len > 0
        || meta_pending_len > 0
        || cert_pending_len > 0
        || chunk_pending_len > 0
        || probe_pending_len > 0
        || retry_pending_len > 0
        || chunk_session_len > 0
        || serve_session_len_v221 > 0
}

fn runtime_snapshot_connected_scope(
    boot_phase: P2pBootPhase,
    connected: &HashSet<PeerId>,
    connected_bootstrap_peers: &HashSet<PeerId>,
) -> HashSet<PeerId> {
    if matches!(boot_phase, P2pBootPhase::ColdStartSnapshot) {
        connected
            .iter()
            .copied()
            .filter(|peer| connected_bootstrap_peers.contains(peer))
            .collect()
    } else {
        connected.clone()
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PeerLifecycleStateV223 {
    Unknown,
    SnapshotServingClient,
    ColdStartSnapshot,
    SnapshotApplied,
    RestartCatchup,
    OperationalCandidate,
    Operational,
}

impl PeerLifecycleStateV223 {
    fn is_operational(self) -> bool {
        matches!(self, PeerLifecycleStateV223::Operational)
    }

    fn is_recovery_or_snapshot(self) -> bool {
        matches!(
            self,
            PeerLifecycleStateV223::SnapshotServingClient
                | PeerLifecycleStateV223::ColdStartSnapshot
                | PeerLifecycleStateV223::SnapshotApplied
                | PeerLifecycleStateV223::RestartCatchup
                | PeerLifecycleStateV223::OperationalCandidate
        )
    }
}

#[derive(Clone, Debug)]
struct PeerRuntimeOperationalCandidateV236 {
    height: u64,
    validator_set_hash: String,
    finalized_height: u64,
    finalized_hash: String,
    observed_at: Instant,
}

#[derive(Clone, Debug)]
struct PeerRuntimeCatchupCandidateV287 {
    height: u64,
    validator_set_hash: String,
    finalized_height: u64,
    finalized_hash: String,
    runtime_sync_caught_up: bool,
    runtime_bootstrap_complete: bool,
    observed_at: Instant,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct StateSyncCatchupSourceV287 {
    peer: PeerId,
    height: u64,
}

#[derive(Clone, Debug)]
struct PeerLifecycleObservationV236 {
    state: PeerLifecycleStateV223,
    candidate_streak: u8,
    last_state_change_at: Instant,
    last_update_at: Instant,
    last_candidate_height: u64,
    last_validator_set_hash: String,
    last_finalized_height: u64,
    last_finalized_hash: String,
}

impl PeerLifecycleObservationV236 {
    fn new(now: Instant) -> Self {
        Self {
            state: PeerLifecycleStateV223::Unknown,
            candidate_streak: 0,
            last_state_change_at: now,
            last_update_at: now,
            last_candidate_height: 0,
            last_validator_set_hash: String::new(),
            last_finalized_height: 0,
            last_finalized_hash: String::new(),
        }
    }
}

fn runtime_peer_lifecycle_required_streak_v236() -> u8 {
    std::env::var("NEWGEN_PEER_LIFECYCLE_OPERATIONAL_STREAK_TICKS")
        .ok()
        .and_then(|s| s.trim().parse::<u8>().ok())
        .unwrap_or(2)
        .clamp(1, 10)
}

fn runtime_peer_lifecycle_candidate_ttl_v236() -> Duration {
    let secs = std::env::var("NEWGEN_PEER_LIFECYCLE_CANDIDATE_TTL_SECS")
        .ok()
        .and_then(|s| s.trim().parse::<u64>().ok())
        .unwrap_or(90)
        .clamp(15, 600);
    Duration::from_secs(secs)
}

fn runtime_peer_lifecycle_candidate_ready_v236(
    telemetry: Option<&PeerRuntimeOperationalCandidateV236>,
    expected_validator_set_hash: &str,
    now: Instant,
) -> bool {
    let Some(candidate) = telemetry else {
        return false;
    };
    if candidate.height == 0
        || candidate.finalized_height == 0
        || candidate.finalized_hash.trim().is_empty()
    {
        return false;
    }
    if now.duration_since(candidate.observed_at) > runtime_peer_lifecycle_candidate_ttl_v236() {
        return false;
    }
    !expected_validator_set_hash.trim().is_empty()
        && candidate.validator_set_hash.trim() == expected_validator_set_hash.trim()
}

fn runtime_peer_lifecycle_next_v236(
    previous: Option<&PeerLifecycleObservationV236>,
    boot_phase: P2pBootPhase,
    peer: PeerId,
    raw_connected: &HashSet<PeerId>,
    recovery_non_operational_peers: &HashSet<PeerId>,
    hello_ok: &HashSet<PeerId>,
    peer_heights: &HashMap<PeerId, u64>,
    runtime_candidates: &HashMap<PeerId, PeerRuntimeOperationalCandidateV236>,
    expected_validator_set_hash: &str,
    require_hello_ok: bool,
    now: Instant,
) -> PeerLifecycleObservationV236 {
    let mut next = previous
        .cloned()
        .unwrap_or_else(|| PeerLifecycleObservationV236::new(now));

    let old_state = next.state;
    let connected = raw_connected.contains(&peer);
    let in_recovery = recovery_non_operational_peers.contains(&peer);
    let has_hello = hello_ok.contains(&peer);
    let peer_height = peer_heights.get(&peer).copied().unwrap_or(0);
    let telemetry = runtime_candidates.get(&peer);
    let telemetry_height_matches_peer_view = telemetry
        .map(|candidate| candidate.height == peer_height)
        .unwrap_or(false);
    let candidate_ready = connected
        && !in_recovery
        && (!require_hello_ok || has_hello)
        && peer_height > 0
        && telemetry_height_matches_peer_view
        && runtime_peer_lifecycle_candidate_ready_v236(telemetry, expected_validator_set_hash, now);

    let new_state = if !connected {
        next.candidate_streak = 0;
        PeerLifecycleStateV223::Unknown
    } else if in_recovery {
        next.candidate_streak = 0;
        PeerLifecycleStateV223::SnapshotServingClient
    } else if matches!(boot_phase, P2pBootPhase::ColdStartSnapshot) {
        next.candidate_streak = 0;
        PeerLifecycleStateV223::ColdStartSnapshot
    } else if candidate_ready {
        let candidate_height = telemetry.map(|t| t.height).unwrap_or(peer_height);
        let candidate_hash = telemetry
            .map(|t| t.validator_set_hash.clone())
            .unwrap_or_default();
        let candidate_finalized_height = telemetry.map(|t| t.finalized_height).unwrap_or(0);
        let candidate_finalized_hash = telemetry
            .map(|t| t.finalized_hash.clone())
            .unwrap_or_default();
        // V239: lifecycle stability is persistent but must not require the exact same
        // height/finality tuple forever. On a healthy live chain, a peer can advance
        // height/finality between lifecycle ticks. Treat monotonic progress on the
        // same validator-set/finality lineage as stable, and reset only on rollback,
        // validator-set change, finalized-hash change at the same height, or loss of
        // readiness evidence. This avoids the opposite bug where a genuinely healthy
        // peer never reaches Operational because it keeps making progress.
        let finalized_lineage_ok = if next.last_finalized_height == 0 {
            true
        } else if candidate_finalized_height > next.last_finalized_height {
            true
        } else if candidate_finalized_height == next.last_finalized_height {
            next.last_finalized_hash == candidate_finalized_hash
        } else {
            false
        };
        let same_candidate = matches!(
            old_state,
            PeerLifecycleStateV223::Operational | PeerLifecycleStateV223::OperationalCandidate
        ) && next.last_validator_set_hash == candidate_hash
            && candidate_height >= next.last_candidate_height
            && finalized_lineage_ok;
        next.candidate_streak = if same_candidate {
            next.candidate_streak.saturating_add(1)
        } else {
            1
        };
        next.last_candidate_height = candidate_height;
        next.last_validator_set_hash = candidate_hash;
        next.last_finalized_height = candidate_finalized_height;
        next.last_finalized_hash = candidate_finalized_hash;
        if next.candidate_streak >= runtime_peer_lifecycle_required_streak_v236() {
            PeerLifecycleStateV223::Operational
        } else {
            PeerLifecycleStateV223::OperationalCandidate
        }
    } else {
        next.candidate_streak = 0;
        if peer_height > 0 {
            PeerLifecycleStateV223::RestartCatchup
        } else {
            PeerLifecycleStateV223::Unknown
        }
    };

    if new_state != old_state {
        next.last_state_change_at = now;
    }
    next.state = new_state;
    next.last_update_at = now;
    next
}

fn runtime_refresh_peer_lifecycle_registry_v236(
    registry: &mut HashMap<PeerId, PeerLifecycleObservationV236>,
    boot_phase: P2pBootPhase,
    connected_raw: &HashSet<PeerId>,
    recovery_non_operational_peers: &HashSet<PeerId>,
    hello_ok: &HashSet<PeerId>,
    peer_heights: &HashMap<PeerId, u64>,
    runtime_candidates: &HashMap<PeerId, PeerRuntimeOperationalCandidateV236>,
    expected_validator_set_hash: &str,
    require_hello_ok: bool,
    now: Instant,
) {
    registry.retain(|peer, _| connected_raw.contains(peer));
    for peer in connected_raw.iter().copied() {
        let next = runtime_peer_lifecycle_next_v236(
            registry.get(&peer),
            boot_phase,
            peer,
            connected_raw,
            recovery_non_operational_peers,
            hello_ok,
            peer_heights,
            runtime_candidates,
            expected_validator_set_hash,
            require_hello_ok,
            now,
        );
        registry.insert(peer, next);
    }
}

fn runtime_operational_peer_scope_v236(
    boot_phase: P2pBootPhase,
    connected_raw: &HashSet<PeerId>,
    recovery_non_operational_peers: &HashSet<PeerId>,
    hello_ok: &HashSet<PeerId>,
    peer_heights: &HashMap<PeerId, u64>,
    runtime_candidates: &HashMap<PeerId, PeerRuntimeOperationalCandidateV236>,
    peer_lifecycle_registry: &mut HashMap<PeerId, PeerLifecycleObservationV236>,
    expected_validator_set_hash: &str,
    require_hello_ok: bool,
    now: Instant,
) -> HashSet<PeerId> {
    if !boot_phase.allows_mining() {
        peer_lifecycle_registry.retain(|peer, _| connected_raw.contains(peer));
        return HashSet::new();
    }

    runtime_refresh_peer_lifecycle_registry_v236(
        peer_lifecycle_registry,
        boot_phase,
        connected_raw,
        recovery_non_operational_peers,
        hello_ok,
        peer_heights,
        runtime_candidates,
        expected_validator_set_hash,
        require_hello_ok,
        now,
    );

    connected_raw
        .iter()
        .copied()
        .filter(|peer| {
            peer_lifecycle_registry
                .get(peer)
                .map(|obs| obs.state.is_operational())
                .unwrap_or(false)
        })
        .collect()
}

fn runtime_quorum_reformation_peer_scope_v283(
    boot_phase: P2pBootPhase,
    connected_raw: &HashSet<PeerId>,
    recovery_non_operational_peers: &HashSet<PeerId>,
    hello_ok: &HashSet<PeerId>,
    peer_heights: &HashMap<PeerId, u64>,
    runtime_candidates: &HashMap<PeerId, PeerRuntimeOperationalCandidateV236>,
    expected_validator_set_hash: &str,
    require_hello_ok: bool,
    now: Instant,
) -> HashSet<PeerId> {
    if !boot_phase.allows_mining() {
        return HashSet::new();
    }

    runtime_admission_peer_scope_v226(
        connected_raw,
        recovery_non_operational_peers,
        hello_ok,
        peer_heights,
        require_hello_ok,
    )
    .into_iter()
    .filter(|peer| {
        let Some(candidate) = runtime_candidates.get(peer) else {
            return false;
        };
        let peer_height = peer_heights.get(peer).copied().unwrap_or(0);
        candidate.height == peer_height
            && runtime_peer_lifecycle_candidate_ready_v236(
                Some(candidate),
                expected_validator_set_hash,
                now,
            )
    })
    .collect()
}

#[derive(Clone, Debug, Default, PartialEq, Eq)]
struct RuntimeQuorumReformationDiagnosticsV284 {
    runtime_candidates_count: usize,
    candidate_missing_count: usize,
    candidate_height_mismatch_count: usize,
    candidate_validator_set_mismatch_count: usize,
    candidate_stale_count: usize,
    candidate_missing_finalized_count: usize,
}

fn runtime_quorum_reformation_diagnostics_v284(
    boot_phase: P2pBootPhase,
    connected_raw: &HashSet<PeerId>,
    recovery_non_operational_peers: &HashSet<PeerId>,
    hello_ok: &HashSet<PeerId>,
    peer_heights: &HashMap<PeerId, u64>,
    runtime_candidates: &HashMap<PeerId, PeerRuntimeOperationalCandidateV236>,
    expected_validator_set_hash: &str,
    require_hello_ok: bool,
    now: Instant,
) -> RuntimeQuorumReformationDiagnosticsV284 {
    if !boot_phase.allows_mining() {
        return RuntimeQuorumReformationDiagnosticsV284::default();
    }

    let admission = runtime_admission_peer_scope_v226(
        connected_raw,
        recovery_non_operational_peers,
        hello_ok,
        peer_heights,
        require_hello_ok,
    );
    let mut out = RuntimeQuorumReformationDiagnosticsV284::default();
    let ttl = runtime_peer_lifecycle_candidate_ttl_v236();
    let expected = expected_validator_set_hash.trim();

    for peer in admission {
        let Some(candidate) = runtime_candidates.get(&peer) else {
            out.candidate_missing_count = out.candidate_missing_count.saturating_add(1);
            continue;
        };
        out.runtime_candidates_count = out.runtime_candidates_count.saturating_add(1);

        let peer_height = peer_heights.get(&peer).copied().unwrap_or(0);
        if candidate.height != peer_height || candidate.height == 0 {
            out.candidate_height_mismatch_count =
                out.candidate_height_mismatch_count.saturating_add(1);
        }
        if expected.is_empty() || candidate.validator_set_hash.trim() != expected {
            out.candidate_validator_set_mismatch_count =
                out.candidate_validator_set_mismatch_count.saturating_add(1);
        }
        if candidate.finalized_height == 0 || candidate.finalized_hash.trim().is_empty() {
            out.candidate_missing_finalized_count =
                out.candidate_missing_finalized_count.saturating_add(1);
        }
        if now.duration_since(candidate.observed_at) > ttl {
            out.candidate_stale_count = out.candidate_stale_count.saturating_add(1);
        }
    }

    out
}

fn runtime_quorum_reformation_stable_ticks_v284() -> u8 {
    std::env::var("NEWGEN_RUNTIME_QUORUM_REFORMATION_OPERATIONAL_STABLE_TICKS")
        .ok()
        .and_then(|s| s.trim().parse::<u8>().ok())
        .unwrap_or(2)
        .clamp(1, 10)
}

fn runtime_quorum_reformation_readiness_active_v284(
    multi_validator: bool,
    operational_quorum_ready: bool,
    operational_connected: usize,
    reformation_connected: usize,
    effective_min_peers_for_mining: usize,
    operational_stable_streak: u8,
    required_stable_ticks: u8,
) -> bool {
    if !multi_validator {
        return false;
    }
    if !operational_quorum_ready {
        return true;
    }
    if reformation_connected < effective_min_peers_for_mining.max(1) {
        return false;
    }
    if operational_connected >= effective_min_peers_for_mining.max(1)
        && operational_stable_streak >= required_stable_ticks.max(1)
    {
        return false;
    }
    true
}

fn runtime_peer_finality_non_contradicting_for_catchup_v287(
    chain: &Blockchain,
    peer_finalized_height: Option<u64>,
    peer_finalized_hash: Option<&str>,
) -> bool {
    let Some(peer_finalized_height) = peer_finalized_height else {
        return false;
    };
    let Some(peer_finalized_hash) = peer_finalized_hash else {
        return false;
    };
    let peer_finalized_hash = peer_finalized_hash.trim();
    if peer_finalized_height == 0 || peer_finalized_hash.is_empty() {
        return false;
    }

    let (local_finalized_height, local_finalized_hash) = chain.finalized_view();
    if peer_finalized_height <= local_finalized_height {
        if let Some(block) = chain.block_at_height(peer_finalized_height) {
            return block.hash.trim() == peer_finalized_hash;
        }
        return peer_finalized_height == local_finalized_height
            && !local_finalized_hash.trim().is_empty()
            && local_finalized_hash.trim() == peer_finalized_hash;
    }

    // V287: a peer ahead of local finality may be used only as a data recovery
    // source. The local finalized prefix is not contradicted by the peer's
    // advertised newer finalized head; imported blocks/snapshots remain verified
    // by the normal state-sync/block validation paths before any quorum/mining
    // authority is granted.
    true
}

fn runtime_note_state_sync_catchup_candidate_v287(
    catchup_candidates: &mut HashMap<PeerId, PeerRuntimeCatchupCandidateV287>,
    recovery_peers: &HashSet<PeerId>,
    telemetry_peer: PeerId,
    telemetry_height: u64,
    telemetry_validator_set_hash: &str,
    expected_validator_set_hash: &str,
    telemetry_finalized_height: Option<u64>,
    telemetry_finalized_hash: Option<&str>,
    finality_non_contradicting: bool,
    runtime_sync_caught_up: bool,
    runtime_bootstrap_complete: bool,
    now: Instant,
) -> bool {
    if recovery_peers.contains(&telemetry_peer)
        || telemetry_height == 0
        || telemetry_validator_set_hash.trim() != expected_validator_set_hash.trim()
        || !runtime_sync_caught_up
        || !runtime_bootstrap_complete
        || !finality_non_contradicting
        || telemetry_finalized_height.unwrap_or(0) == 0
        || telemetry_finalized_hash
            .map(|h| h.trim().is_empty())
            .unwrap_or(true)
    {
        catchup_candidates.remove(&telemetry_peer);
        return false;
    }

    catchup_candidates.insert(
        telemetry_peer,
        PeerRuntimeCatchupCandidateV287 {
            height: telemetry_height,
            validator_set_hash: telemetry_validator_set_hash.to_string(),
            finalized_height: telemetry_finalized_height.unwrap_or(0),
            finalized_hash: telemetry_finalized_hash.unwrap_or_default().to_string(),
            runtime_sync_caught_up,
            runtime_bootstrap_complete,
            observed_at: now,
        },
    );
    true
}

fn peer_valid_for_state_sync_catchup_v287(
    peer: &PeerId,
    boot_phase: P2pBootPhase,
    admission_peers: &HashSet<PeerId>,
    catchup_candidates: &HashMap<PeerId, PeerRuntimeCatchupCandidateV287>,
    peer_heights: &HashMap<PeerId, u64>,
    expected_validator_set_hash: &str,
    local_height: u64,
    local_finalized_height: u64,
    now: Instant,
) -> bool {
    if !boot_phase.allows_live_sync() || !admission_peers.contains(peer) {
        return false;
    }
    let Some(candidate) = catchup_candidates.get(peer) else {
        return false;
    };
    let peer_height = peer_heights.get(peer).copied().unwrap_or(0);
    if peer_height == 0 || candidate.height != peer_height {
        return false;
    }
    if now.duration_since(candidate.observed_at) > runtime_peer_lifecycle_candidate_ttl_v236() {
        return false;
    }
    if expected_validator_set_hash.trim().is_empty()
        || candidate.validator_set_hash.trim() != expected_validator_set_hash.trim()
    {
        return false;
    }
    if !candidate.runtime_sync_caught_up || !candidate.runtime_bootstrap_complete {
        return false;
    }
    if candidate.finalized_height == 0 || candidate.finalized_hash.trim().is_empty() {
        return false;
    }
    candidate.height > local_height || candidate.finalized_height > local_finalized_height
}

fn runtime_best_state_sync_catchup_source_v287(
    boot_phase: P2pBootPhase,
    admission_peers: &HashSet<PeerId>,
    catchup_candidates: &HashMap<PeerId, PeerRuntimeCatchupCandidateV287>,
    peer_heights: &HashMap<PeerId, u64>,
    expected_validator_set_hash: &str,
    local_height: u64,
    local_finalized_height: u64,
    now: Instant,
) -> Option<StateSyncCatchupSourceV287> {
    admission_peers
        .iter()
        .copied()
        .filter(|peer| {
            peer_valid_for_state_sync_catchup_v287(
                peer,
                boot_phase,
                admission_peers,
                catchup_candidates,
                peer_heights,
                expected_validator_set_hash,
                local_height,
                local_finalized_height,
                now,
            )
        })
        .filter_map(|peer| {
            peer_heights
                .get(&peer)
                .copied()
                .map(|height| StateSyncCatchupSourceV287 { peer, height })
        })
        .max_by_key(|source| source.height)
}

fn runtime_bound_state_sync_catchup_source_height_v287(
    catchup_candidates: &HashMap<PeerId, PeerRuntimeCatchupCandidateV287>,
    peer_heights: &HashMap<PeerId, u64>,
    source_peer: Option<&PeerId>,
    claimed_peer_height: u64,
) -> Result<StateSyncCatchupSourceV287, &'static str> {
    let Some(peer) = source_peer else {
        return Err("missing_catchup_source_peer");
    };
    let Some(candidate) = catchup_candidates.get(peer) else {
        return Err("source_peer_not_catchup_candidate");
    };
    let Some(height) = peer_heights.get(peer).copied().filter(|height| *height > 0) else {
        return Err("source_peer_missing_height");
    };
    if candidate.height != height {
        return Err("source_peer_height_candidate_mismatch");
    }
    if height != claimed_peer_height {
        return Err("source_peer_height_mismatch");
    }
    Ok(StateSyncCatchupSourceV287 {
        peer: *peer,
        height,
    })
}

