fn runtime_peer_finalized_hash_compatible_v237(
    chain: &Blockchain,
    peer_finalized_height: Option<u64>,
    peer_finalized_hash: Option<&str>,
) -> bool {
    let Some(peer_finalized_height) = peer_finalized_height else {
        return false;
    };
    let Some(peer_finalized_hash) = peer_finalized_hash else {
        return false;
    };
    let peer_finalized_hash = peer_finalized_hash.trim();
    if peer_finalized_height == 0 || peer_finalized_hash.is_empty() {
        return false;
    }

    let (local_finalized_height, local_finalized_hash) = chain.finalized_view();
    if peer_finalized_height > local_finalized_height {
        return false;
    }

    if let Some(block) = chain.block_at_height(peer_finalized_height) {
        return block.hash.trim() == peer_finalized_hash;
    }

    peer_finalized_height == local_finalized_height
        && !local_finalized_hash.trim().is_empty()
        && local_finalized_hash.trim() == peer_finalized_hash
}

fn runtime_note_operational_candidate_telemetry_v236(
    runtime_candidates: &mut HashMap<PeerId, PeerRuntimeOperationalCandidateV236>,
    recovery_peers: &HashSet<PeerId>,
    telemetry_peer: PeerId,
    telemetry_height: u64,
    telemetry_validator_set_hash: &str,
    expected_validator_set_hash: &str,
    telemetry_finalized_height: Option<u64>,
    telemetry_finalized_hash: Option<&str>,
    finalized_hash_compatible: bool,
    runtime_sync_caught_up: bool,
    runtime_bootstrap_complete: bool,
    _p2p_ready_for_mining: bool,
    now: Instant,
) -> bool {
    let restart_warm_candidate_v269 = runtime_restart_warm_candidate_v269(
        telemetry_height,
        telemetry_finalized_height,
        telemetry_finalized_hash,
        finalized_hash_compatible,
        runtime_sync_caught_up,
        runtime_bootstrap_complete,
    );

    if recovery_peers.contains(&telemetry_peer)
        || telemetry_height == 0
        || !restart_warm_candidate_v269
        || telemetry_validator_set_hash.trim() != expected_validator_set_hash.trim()
        || !finalized_hash_compatible
        || telemetry_finalized_height.unwrap_or(0) == 0
        || telemetry_finalized_hash
            .map(|h| h.trim().is_empty())
            .unwrap_or(true)
    {
        runtime_candidates.remove(&telemetry_peer);
        return false;
    }

    runtime_candidates.insert(
        telemetry_peer,
        PeerRuntimeOperationalCandidateV236 {
            height: telemetry_height,
            validator_set_hash: telemetry_validator_set_hash.to_string(),
            finalized_height: telemetry_finalized_height.unwrap_or(0),
            finalized_hash: telemetry_finalized_hash.unwrap_or_default().to_string(),
            observed_at: now,
        },
    );
    true
}

fn classify_peer_lifecycle_v223(
    boot_phase: P2pBootPhase,
    peer: &PeerId,
    raw_connected: &HashSet<PeerId>,
    operational_peers: &HashSet<PeerId>,
    recovery_non_operational_peers: &HashSet<PeerId>,
    hello_ok: &HashSet<PeerId>,
    peer_heights: &HashMap<PeerId, u64>,
) -> PeerLifecycleStateV223 {
    if !raw_connected.contains(peer) {
        return PeerLifecycleStateV223::Unknown;
    }
    // V238 hard boundary: the legacy/transient lifecycle classifier must never
    // promote a peer to Operational from an ephemeral scope. Operational requires
    // the persistent lifecycle registry (runtime_operational_peer_scope_v236+)
    // with signed ready telemetry, finalized-hash compatibility and a stability
    // streak. Treat the legacy operational_peers input only as an
    // OperationalCandidate hint so old helper paths fail closed.
    if operational_peers.contains(peer) {
        return PeerLifecycleStateV223::OperationalCandidate;
    }
    if recovery_non_operational_peers.contains(peer)
        && !matches!(boot_phase, P2pBootPhase::ColdStartSnapshot)
    {
        return PeerLifecycleStateV223::SnapshotServingClient;
    }
    if matches!(boot_phase, P2pBootPhase::ColdStartSnapshot) {
        return PeerLifecycleStateV223::ColdStartSnapshot;
    }
    let has_hello = hello_ok.contains(peer);
    let has_height = peer_heights.get(peer).copied().unwrap_or(0) > 0;
    match boot_phase {
        P2pBootPhase::RestartCatchup | P2pBootPhase::FallbackLiveSync => {
            if has_hello && has_height {
                PeerLifecycleStateV223::OperationalCandidate
            } else if has_height {
                PeerLifecycleStateV223::SnapshotApplied
            } else {
                PeerLifecycleStateV223::RestartCatchup
            }
        }
        P2pBootPhase::SteadyState => {
            if has_hello && has_height {
                PeerLifecycleStateV223::OperationalCandidate
            } else {
                PeerLifecycleStateV223::Unknown
            }
        }
        P2pBootPhase::ColdStartSnapshot => PeerLifecycleStateV223::ColdStartSnapshot,
    }
}

// Admission/catch-up peer view. This is intentionally independent from
// `boot_phase.allows_mining()`: RestartCatchup and FallbackLiveSync must be
// able to see live peers for hello/status/height admission without opening
// mining/proposal gates. Snapshot/recovery peers remain excluded.
fn runtime_admission_peer_scope_v226(
    connected_raw: &HashSet<PeerId>,
    recovery_non_operational_peers: &HashSet<PeerId>,
    hello_ok: &HashSet<PeerId>,
    peer_heights: &HashMap<PeerId, u64>,
    require_hello_ok: bool,
) -> HashSet<PeerId> {
    connected_raw
        .iter()
        .copied()
        .filter(|peer| !recovery_non_operational_peers.contains(peer))
        .filter(|peer| !require_hello_ok || hello_ok.contains(peer))
        .filter(|peer| peer_heights.get(peer).copied().unwrap_or(0) > 0)
        .collect()
}

// Mining/quorum-only peer view. Sync/catchup must keep using the raw/admission
// peer set, because recovering nodes still need live peers for handshakes,
// status, snapshot meta and live catch-up.
// V238: kept only as a legacy admission/candidate helper for old tests.
// It is intentionally fail-closed for Operational membership because it has no
// access to the persistent peer lifecycle registry or signed runtime/finality
// telemetry. Runtime code must use runtime_operational_peer_scope_v236+.
fn runtime_operational_peer_scope_v223(
    boot_phase: P2pBootPhase,
    connected_raw: &HashSet<PeerId>,
    recovery_non_operational_peers: &HashSet<PeerId>,
    hello_ok: &HashSet<PeerId>,
    peer_heights: &HashMap<PeerId, u64>,
    require_hello_ok: bool,
) -> HashSet<PeerId> {
    let _candidate_hint = if boot_phase.allows_mining() {
        runtime_admission_peer_scope_v226(
            connected_raw,
            recovery_non_operational_peers,
            hello_ok,
            peer_heights,
            require_hello_ok,
        )
    } else {
        HashSet::new()
    };

    // Without persistent lifecycle proof, signed ready telemetry, compatible
    // validator-set/finality evidence and stability streak, no peer may enter
    // the operational mining/quorum scope. This closes the old V223 hole where
    // hello_ok + height>0 + !recovery could be treated as Operational.
    HashSet::new()
}

fn runtime_scope_max_known_height_v227(scoped_peer_heights: &[u64], local_next: u64) -> u64 {
    scoped_peer_heights
        .iter()
        .copied()
        .max()
        .unwrap_or(local_next)
        .max(local_next)
}

fn runtime_peer_is_operational_v240(
    peer_lifecycle_registry: &HashMap<PeerId, PeerLifecycleObservationV236>,
    peer: &PeerId,
) -> bool {
    peer_lifecycle_registry
        .get(peer)
        .map(|obs| obs.state.is_operational())
        .unwrap_or(false)
}

fn runtime_operational_peer_height_v240(
    peer_lifecycle_registry: &HashMap<PeerId, PeerLifecycleObservationV236>,
    peer_heights: &HashMap<PeerId, u64>,
    peer: &PeerId,
) -> Option<u64> {
    if !runtime_peer_is_operational_v240(peer_lifecycle_registry, peer) {
        return None;
    }
    peer_heights.get(peer).copied().filter(|h| *h > 0)
}

fn runtime_best_operational_peer_height_v241(
    peer_lifecycle_registry: &HashMap<PeerId, PeerLifecycleObservationV236>,
    peer_heights: &HashMap<PeerId, u64>,
) -> Option<(PeerId, u64)> {
    peer_lifecycle_registry
        .iter()
        .filter(|(_, obs)| obs.state.is_operational())
        .filter_map(|(peer, _)| {
            peer_heights
                .get(peer)
                .copied()
                .filter(|h| *h > 0)
                .map(|h| (*peer, h))
        })
        .max_by_key(|(_, height)| *height)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct OperationalStateSyncSourceV243 {
    peer: PeerId,
    height: u64,
}

fn runtime_operational_statesync_source_for_peer_v243(
    peer_lifecycle_registry: &HashMap<PeerId, PeerLifecycleObservationV236>,
    peer_heights: &HashMap<PeerId, u64>,
    peer: &PeerId,
) -> Option<OperationalStateSyncSourceV243> {
    runtime_operational_peer_height_v240(peer_lifecycle_registry, peer_heights, peer)
        .filter(|height| *height > 0)
        .map(|height| OperationalStateSyncSourceV243 {
            peer: *peer,
            height,
        })
}

fn runtime_best_operational_statesync_source_v243(
    peer_lifecycle_registry: &HashMap<PeerId, PeerLifecycleObservationV236>,
    peer_heights: &HashMap<PeerId, u64>,
) -> Option<OperationalStateSyncSourceV243> {
    runtime_best_operational_peer_height_v241(peer_lifecycle_registry, peer_heights)
        .map(|(peer, height)| OperationalStateSyncSourceV243 { peer, height })
}

fn runtime_bound_operational_source_height_v243(
    peer_lifecycle_registry: &HashMap<PeerId, PeerLifecycleObservationV236>,
    peer_heights: &HashMap<PeerId, u64>,
    source_peer: Option<&PeerId>,
    claimed_peer_height: u64,
) -> Result<OperationalStateSyncSourceV243, &'static str> {
    let Some(peer) = source_peer else {
        return Err("missing_operational_source_peer");
    };
    let Some(source) = runtime_operational_statesync_source_for_peer_v243(
        peer_lifecycle_registry,
        peer_heights,
        peer,
    ) else {
        return Err("source_peer_not_operational_or_missing_height");
    };
    if source.height != claimed_peer_height {
        return Err("source_peer_height_mismatch");
    }
    Ok(source)
}

fn runtime_operational_max_known_height_v240(
    peer_lifecycle_registry: &HashMap<PeerId, PeerLifecycleObservationV236>,
    peer_heights: &HashMap<PeerId, u64>,
    local_next: u64,
) -> u64 {
    runtime_best_operational_peer_height_v241(peer_lifecycle_registry, peer_heights)
        .map(|(_, height)| height)
        .unwrap_or(local_next)
        .max(local_next)
}

