#[cfg(test)]
fn snapshot_priority_trigger_state_sync_recovery_source_bound_v243(
    tracker: &mut CatchupProgressTracker,
    boot_phase: P2pBootPhase,
    local_height: u64,
    peer_height: u64,
    path: &'static str,
    source_peer: Option<&PeerId>,
    peer_heights: &HashMap<PeerId, u64>,
    peer_lifecycle_registry: &HashMap<PeerId, PeerLifecycleObservationV236>,
) -> bool {
    let source = match runtime_bound_operational_source_height_v243(
        peer_lifecycle_registry,
        peer_heights,
        source_peer,
        peer_height,
    ) {
        Ok(source) => source,
        Err("missing_operational_source_peer") => {
            ng_info_throttle!(
                key: format!("snapshot_priority_statesync_missing_source_v243_{}", path),
                every_ms: 10_000,
                target: "p2p.sync",
                "event=snapshot_priority_statesync_trigger_suppressed_v243 path={} local_height={} peer_height={} boot_phase={:?} reason=missing_operational_source_peer",
                path,
                local_height,
                peer_height,
                boot_phase,
            );
            return false;
        }
        Err("source_peer_not_operational_or_missing_height") => {
            let peer_label = source_peer
                .map(|peer| peer.to_string())
                .unwrap_or_else(|| "none".to_string());
            ng_info_throttle!(
                key: format!("snapshot_priority_statesync_non_operational_or_missing_source_v243_{}_{}", path, peer_label),
                every_ms: 10_000,
                target: "p2p.sync",
                "event=snapshot_priority_statesync_trigger_suppressed_v243 path={} peer={} local_height={} peer_height={} boot_phase={:?} reason=source_peer_not_operational_or_missing_height",
                path,
                peer_label,
                local_height,
                peer_height,
                boot_phase,
            );
            return false;
        }
        Err("source_peer_height_mismatch") => {
            let peer = source_peer.expect("source_peer present for height mismatch");
            let source_height =
                runtime_operational_peer_height_v240(peer_lifecycle_registry, peer_heights, peer)
                    .unwrap_or(0);
            ng_info_throttle!(
                key: format!("snapshot_priority_statesync_height_mismatch_v243_{}_{}", path, peer),
                every_ms: 10_000,
                target: "p2p.sync",
                "event=snapshot_priority_statesync_trigger_suppressed_v243 path={} peer={} local_height={} requested_peer_height={} source_peer_height={} boot_phase={:?} reason=source_peer_height_mismatch",
                path,
                peer,
                local_height,
                peer_height,
                source_height,
                boot_phase,
            );
            return false;
        }
        Err(_) => return false,
    };

    snapshot_priority_trigger_state_sync_recovery_verified_v245(
        tracker,
        boot_phase,
        local_height,
        source,
        path,
    )
}

