fn state_sync_reason_matches_bound_operational_source_v245(
    reason: &StateSyncReason,
    local_height: u64,
    source: OperationalStateSyncSourceV243,
) -> Result<(), &'static str> {
    match reason {
        StateSyncReason::GapStall {
            local_height: Some(reason_local_height),
            peer_height: Some(reason_peer_height),
            ..
        } => {
            if *reason_local_height != local_height {
                return Err("reason_local_height_mismatch");
            }
            if *reason_peer_height != source.height {
                return Err("reason_peer_height_mismatch");
            }
            Ok(())
        }
        StateSyncReason::GapStall { .. } => Err("reason_missing_height_hints"),
        StateSyncReason::NoOverlap {
            peer: Some(reason_peer),
        } => {
            let source_peer = source.peer.to_string();
            if reason_peer != &source_peer {
                return Err("reason_source_peer_mismatch");
            }
            Ok(())
        }
        StateSyncReason::NoOverlap { peer: None } => Err("reason_missing_source_peer"),
        StateSyncReason::LocalConsensusWedged { .. } => {
            Err("local_consensus_wedged_requires_dedicated_source_guard")
        }
        StateSyncReason::Manual { .. } => Err("manual_state_sync_not_allowed_from_peer_path"),
    }
}

fn state_sync_reason_matches_bound_catchup_source_v287(
    reason: &StateSyncReason,
    local_height: u64,
    source: StateSyncCatchupSourceV287,
) -> Result<(), &'static str> {
    state_sync_reason_matches_bound_operational_source_v245(
        reason,
        local_height,
        OperationalStateSyncSourceV243 {
            peer: source.peer,
            height: source.height,
        },
    )
}

fn state_sync_supervisor_trigger_catchup_source_bound_v287(
    reason: StateSyncReason,
    path: &'static str,
    local_height: u64,
    peer_height: u64,
    source_peer: Option<&PeerId>,
    peer_heights: &HashMap<PeerId, u64>,
    catchup_candidates: &HashMap<PeerId, PeerRuntimeCatchupCandidateV287>,
) -> bool {
    let source = match runtime_bound_state_sync_catchup_source_height_v287(
        catchup_candidates,
        peer_heights,
        source_peer,
        peer_height,
    ) {
        Ok(source) => source,
        Err(reason) => {
            let peer_label = source_peer
                .map(|peer| peer.to_string())
                .unwrap_or_else(|| "none".to_string());
            let source_height = source_peer
                .and_then(|peer| peer_heights.get(peer).copied())
                .unwrap_or(0);
            ng_info_throttle!(
                key: format!("statesync_supervisor_catchup_trigger_suppressed_v287_{}_{}", path, peer_label),
                every_ms: 10_000,
                target: "p2p.sync",
                "event=statesync_supervisor_trigger_suppressed_v287 path={} peer={} local_height={} requested_peer_height={} source_peer_height={} reason={}",
                path,
                peer_label,
                local_height,
                peer_height,
                source_height,
                reason,
            );
            return false;
        }
    };

    if source.height <= local_height {
        return false;
    }
    if let Err(reason_mismatch) =
        state_sync_reason_matches_bound_catchup_source_v287(&reason, local_height, source)
    {
        ng_info_throttle!(
            key: format!("statesync_supervisor_catchup_reason_unbound_v287_{}_{}", path, source.peer),
            every_ms: 10_000,
            target: "p2p.sync",
            "event=statesync_supervisor_trigger_suppressed_v287 path={} peer={} local_height={} source_peer_height={} reason={}",
            path,
            source.peer,
            local_height,
            source.height,
            reason_mismatch,
        );
        return false;
    }

    statesync_trigger_verified_catchup_peer_bound_v287(reason)
}

