#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PostSnapshotCatchupDecisionV228 {
    AwaitLivePeerHandshake,
    AwaitAdmissionStability,
    ArmLiveCatchup,
}

fn post_snapshot_catchup_decision_v228(
    admission_connected: usize,
    admission_max_known: u64,
    local_next_after_phase: u64,
) -> PostSnapshotCatchupDecisionV228 {
    if admission_connected == 0 {
        PostSnapshotCatchupDecisionV228::AwaitLivePeerHandshake
    } else if admission_max_known <= local_next_after_phase {
        PostSnapshotCatchupDecisionV228::AwaitAdmissionStability
    } else {
        PostSnapshotCatchupDecisionV228::ArmLiveCatchup
    }
}

