impl P2PPolicy {
    pub fn load() -> Self {
        let path = NodePaths::resolve_config_path("config/p2p_policy.toml");
        if path.exists() {
            ng_debug!(target: "p2p.misc", "  Caricamento policy da: {}", path.display());

            let cfg = match config::Config::builder()
                .add_source(config::File::from(path.clone()))
                .build()
            {
                Ok(v) => v,
                Err(e) => {
                    ng_warn!(
                        target: "p2p.misc",
                        "WARN: impossibile leggere {}: {}. Uso default hardcoded.",
                        path.display(),
                        e
                    );
                    return Self::default().normalized();
                }
            };

            match cfg.try_deserialize::<P2PPolicy>() {
                Ok(pol) => {
                    let pol = pol.normalized();
                    ng_debug!(
                        target: "p2p.misc",
                        "  P2P policy caricata: sync_timeout={}s chunk_size={} max_peers={} max_msg_bytes={}",
                        pol.sync_timeout_sec,
                        pol.chunk_size,
                        pol.max_peers,
                        pol.max_msg_bytes
                    );
                    return pol;
                }
                Err(e) => {
                    ng_warn!(
                        target: "p2p.misc",
                        "WARN: p2p_policy.toml non valido in {}: {}. Uso default hardcoded.",
                        path.display(),
                        e
                    );
                    return Self::default().normalized();
                }
            }
        }
        ng_warn!(target: "p2p.misc", "WARN: Nessun p2p_policy.toml valido trovato in {}. Uso default hardcoded.", path.display());
        Self::default().normalized()
    }

    /// Normalizza i parametri per evitare configurazioni incoerenti.
    /// In particolare: i cap per-topic non possono superare il cap globale `max_msg_bytes`.
    fn normalized(mut self) -> Self {
        // Hard cap globale
        self.blocks_max_msg_bytes = self.blocks_max_msg_bytes.min(self.max_msg_bytes);
        self.tx_max_msg_bytes = self.tx_max_msg_bytes.min(self.max_msg_bytes);
        self.finality_max_msg_bytes = self.finality_max_msg_bytes.min(self.max_msg_bytes);
        self.heartbeat_max_msg_bytes = self.heartbeat_max_msg_bytes.min(self.max_msg_bytes);
        self.reputation_max_msg_bytes = self.reputation_max_msg_bytes.min(self.max_msg_bytes);

        // Gossipsub sanity
        self.gsub_heartbeat_interval_ms = self.gsub_heartbeat_interval_ms.max(250);
        self.gsub_mesh_n = self.gsub_mesh_n.max(4);
        self.gsub_mesh_n_low = self.gsub_mesh_n_low.max(2).min(self.gsub_mesh_n);
        self.gsub_mesh_n_high = self.gsub_mesh_n_high.max(self.gsub_mesh_n);
        self.gsub_history_length = self.gsub_history_length.max(5);
        self.gsub_history_gossip = self
            .gsub_history_gossip
            .max(1)
            .min(self.gsub_history_length);
        // Fork/probe sanity

        self.fork_probe_limit = self.fork_probe_limit.max(1).min(4096);

        self.fork_probe_cooldown_sec = self.fork_probe_cooldown_sec.max(1).min(300);

        self.fork_quorum_k = self.fork_quorum_k.max(1);

        self.sync_apply_cap = self.sync_apply_cap.max(1).min(4096);

        // Fresh peer view gating should never be too small; keep it reasonably above pulse interval.
        self.fresh_peer_view_max_age_sec = self
            .fresh_peer_view_max_age_sec
            .max(5)
            .max(self.pulse_interval_sec.saturating_mul(3).max(6));

        // Bootstrap peers: trim, drop empty, cap size (anti-RAM / anti-dialstorm).
        {
            let mut seen = std::collections::HashSet::<String>::new();
            let mut out = Vec::new();
            for p in self.bootstrap_peers.into_iter() {
                let t = p.trim().to_string();
                if t.is_empty() {
                    continue;
                }
                if seen.insert(t.clone()) {
                    out.push(t);
                }
                if out.len() >= 64 {
                    break;
                }
            }
            self.bootstrap_peers = out;
        }

        // Production hardening clamps (fail-safe)
        if self.max_total_conns_per_ip24 == 0 {
            self.max_total_conns_per_ip24 = 8;
        }
        if self.max_inbound_conns_per_ip24 == 0 {
            self.max_inbound_conns_per_ip24 = 4;
        }
        if self.max_outbound_conns_per_ip24 == 0 {
            self.max_outbound_conns_per_ip24 = 2;
        }

        self.max_inbound_conns_per_ip24 = self
            .max_inbound_conns_per_ip24
            .min(self.max_total_conns_per_ip24);
        self.max_outbound_conns_per_ip24 = self
            .max_outbound_conns_per_ip24
            .min(self.max_total_conns_per_ip24);

        if self.max_total_conns_per_asn == 0 {
            self.max_total_conns_per_asn = 12;
        }
        if self.max_inbound_conns_per_asn == 0 {
            self.max_inbound_conns_per_asn = 8;
        }
        if self.max_outbound_conns_per_asn == 0 {
            self.max_outbound_conns_per_asn = 4;
        }
        self.max_inbound_conns_per_asn = self
            .max_inbound_conns_per_asn
            .min(self.max_total_conns_per_asn);
        self.max_outbound_conns_per_asn = self
            .max_outbound_conns_per_asn
            .min(self.max_total_conns_per_asn);

        // dial targets must be coherent with max_peers
        self.dial_target_outbound = self.dial_target_outbound.max(1).min(self.max_peers.max(1));
        self.dial_max_attempts_per_tick = self.dial_max_attempts_per_tick.max(1).min(16);
        self.dial_tick_ms = self.dial_tick_ms.max(250).min(30_000);
        self.dial_candidate_ttl_sec = self.dial_candidate_ttl_sec.max(30).min(86_400);
        self.dial_min_peer_lifetime_sec = self.dial_min_peer_lifetime_sec.max(10).min(86_400);
        self.peer_rotation_interval_sec = self.peer_rotation_interval_sec.max(30).min(86_400);
        self.peer_rotation_max_disconnects_per_tick =
            self.peer_rotation_max_disconnects_per_tick.max(1).min(8);

        self.min_outbound_unique_ip24 =
            self.min_outbound_unique_ip24.min(self.dial_target_outbound);
        self.min_outbound_unique_asn = self.min_outbound_unique_asn.min(self.dial_target_outbound);

        self
    }

    fn max_topic_bytes(&self, k: TopicKind) -> usize {
        match k {
            TopicKind::Blocks => self.blocks_max_msg_bytes,
            TopicKind::Tx => self.tx_max_msg_bytes,
            TopicKind::Heartbeat => self.heartbeat_max_msg_bytes,
            TopicKind::Reputation => self.reputation_max_msg_bytes,
            // Finality votes/certs can be larger than heartbeat, but should be bounded strictly.
            TopicKind::Finality => self.finality_max_msg_bytes,
        }
    }

    fn rl_params(&self, k: TopicKind) -> (f64, f64, f64, f64) {
        match k {
            TopicKind::Blocks => (
                self.rl_blocks_msgs_per_sec,
                self.rl_blocks_msgs_burst,
                self.rl_blocks_bytes_per_sec,
                self.rl_blocks_bytes_burst,
            ),
            TopicKind::Tx => (
                self.rl_tx_msgs_per_sec,
                self.rl_tx_msgs_burst,
                self.rl_tx_bytes_per_sec,
                self.rl_tx_bytes_burst,
            ),
            TopicKind::Finality => (
                self.rl_finality_msgs_per_sec,
                self.rl_finality_msgs_burst,
                self.rl_finality_bytes_per_sec,
                self.rl_finality_bytes_burst,
            ),
            TopicKind::Heartbeat => (
                self.rl_heartbeat_msgs_per_sec,
                self.rl_heartbeat_msgs_burst,
                self.rl_heartbeat_bytes_per_sec,
                self.rl_heartbeat_bytes_burst,
            ),
            TopicKind::Reputation => (
                self.rl_reputation_msgs_per_sec,
                self.rl_reputation_msgs_burst,
                self.rl_reputation_bytes_per_sec,
                self.rl_reputation_bytes_burst,
            ),
        }
    }
}

// ======================================================================================
//   REQUEST/RESPONSE (SYNC) - Reliable transport (NO gossip)
// ======================================================================================

const SYNC_PROTO_NAME: &str = RR_V2;
const HEADERS_PROTO_NAME: &str = RR_V3;
const RR_MAX_FRAME_BYTES: usize = 8 * 1024 * 1024; // hard safety cap, indipendente da max_msg_bytes
const MAX_REORG_DEPTH: u64 = 512; // cap difensivo: evita reorg profondi da peer sbagliati/malevoli

#[derive(Clone, Default)]
struct NewgenSyncCodec;

// Per semplicita: request/response sono "bytes" gia encoded con encode_msg(NetMsg::...)
// Request:  NetMsg::SyncRequest { from, limit }
// Response: NetMsg::SyncResponse { blocks }
type RRRequest = Vec<u8>;
type RRResponse = Vec<u8>;

impl request_response::Codec for NewgenSyncCodec {
    type Protocol = String;
    type Request = RRRequest;
    type Response = RRResponse;

    fn read_request<'life0, 'life1, 'life2, 'async_trait, T>(
        &'life0 mut self,
        _protocol: &'life1 Self::Protocol,
        io: &'life2 mut T,
    ) -> Pin<Box<dyn Future<Output = io::Result<Self::Request>> + Send + 'async_trait>>
    where
        T: AsyncRead + Unpin + Send + 'async_trait,
        'life0: 'async_trait,
        'life1: 'async_trait,
        'life2: 'async_trait,
        Self: 'async_trait,
    {
        Box::pin(async move {
            let mut len_buf = [0u8; 4];
            io.read_exact(&mut len_buf).await?;
            let len = u32::from_be_bytes(len_buf) as usize;
            if len > RR_MAX_FRAME_BYTES {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!("RR request frame too large: {}", len),
                ));
            }
            let mut buf = vec![0u8; len];
            io.read_exact(&mut buf).await?;
            Ok(buf)
        })
    }

    fn read_response<'life0, 'life1, 'life2, 'async_trait, T>(
        &'life0 mut self,
        _protocol: &'life1 Self::Protocol,
        io: &'life2 mut T,
    ) -> Pin<Box<dyn Future<Output = io::Result<Self::Response>> + Send + 'async_trait>>
    where
        T: AsyncRead + Unpin + Send + 'async_trait,
        'life0: 'async_trait,
        'life1: 'async_trait,
        'life2: 'async_trait,
        Self: 'async_trait,
    {
        Box::pin(async move {
            let mut len_buf = [0u8; 4];
            io.read_exact(&mut len_buf).await?;
            let len = u32::from_be_bytes(len_buf) as usize;
            if len > RR_MAX_FRAME_BYTES {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!("RR response frame too large: {}", len),
                ));
            }
            let mut buf = vec![0u8; len];
            io.read_exact(&mut buf).await?;
            Ok(buf)
        })
    }

    fn write_request<'life0, 'life1, 'life2, 'async_trait, T>(
        &'life0 mut self,
        _protocol: &'life1 Self::Protocol,
        io: &'life2 mut T,
        data: Self::Request,
    ) -> Pin<Box<dyn Future<Output = io::Result<()>> + Send + 'async_trait>>
    where
        T: AsyncWrite + Unpin + Send + 'async_trait,
        'life0: 'async_trait,
        'life1: 'async_trait,
        'life2: 'async_trait,
        Self: 'async_trait,
    {
        Box::pin(async move {
            let len = data.len();
            if len > RR_MAX_FRAME_BYTES {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidInput,
                    format!("RR request too large: {}", len),
                ));
            }
            io.write_all(&(len as u32).to_be_bytes()).await?;
            io.write_all(&data).await?;
            io.flush().await?;
            Ok(())
        })
    }

    fn write_response<'life0, 'life1, 'life2, 'async_trait, T>(
        &'life0 mut self,
        _protocol: &'life1 Self::Protocol,
        io: &'life2 mut T,
        data: Self::Response,
    ) -> Pin<Box<dyn Future<Output = io::Result<()>> + Send + 'async_trait>>
    where
        T: AsyncWrite + Unpin + Send + 'async_trait,
        'life0: 'async_trait,
        'life1: 'async_trait,
        'life2: 'async_trait,
        Self: 'async_trait,
    {
        Box::pin(async move {
            let len = data.len();
            if len > RR_MAX_FRAME_BYTES {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidInput,
                    format!("RR response too large: {}", len),
                ));
            }
            io.write_all(&(len as u32).to_be_bytes()).await?;
            io.write_all(&data).await?;
            io.flush().await?;
            Ok(())
        })
    }
}

// --- RR v3 (Step 57): RRv3Request/RRv3Response + NewgenHeadersCodec are shared in
