#[derive(NetworkBehaviour)]
#[behaviour(to_swarm = "NewgenBehaviourEvent")]
struct NewgenBehaviour {
    gossipsub:
        gossipsub::Behaviour<gossipsub::IdentityTransform, gossipsub::AllowAllSubscriptionFilter>,
    reqres: request_response::Behaviour<NewgenSyncCodec>,
    reqres_v3: request_response::Behaviour<NewgenHeadersCodec>,

    // --- Step 56 NAT / connectivity stack ---
    identify: identify::Behaviour,
    ping: ping::Behaviour,
    autonat: autonat::Behaviour,

    relay_client: relay::client::Behaviour,
    relay_server: relay::Behaviour,
    dcutr: dcutr::Behaviour,
}

#[derive(Debug)]
enum NewgenBehaviourEvent {
    Gossipsub(GossipsubEvent),
    ReqRes(request_response::Event<RRRequest, RRResponse>),

    Identify(identify::Event),
    Ping(ping::Event),
    Autonat(autonat::Event),
    ReqResV3(request_response::Event<RRv3Request, RRv3Response>),

    RelayClient(relay::client::Event),
    RelayServer(relay::Event),
    Dcutr(dcutr::Event),
}

impl From<request_response::Event<RRv3Request, RRv3Response>> for NewgenBehaviourEvent {
    fn from(e: request_response::Event<RRv3Request, RRv3Response>) -> Self {
        Self::ReqResV3(e)
    }
}

impl From<GossipsubEvent> for NewgenBehaviourEvent {
    fn from(e: GossipsubEvent) -> Self {
        Self::Gossipsub(e)
    }
}

impl From<request_response::Event<RRRequest, RRResponse>> for NewgenBehaviourEvent {
    fn from(e: request_response::Event<RRRequest, RRResponse>) -> Self {
        Self::ReqRes(e)
    }
}

impl From<identify::Event> for NewgenBehaviourEvent {
    fn from(e: identify::Event) -> Self {
        Self::Identify(e)
    }
}

impl From<ping::Event> for NewgenBehaviourEvent {
    fn from(e: ping::Event) -> Self {
        Self::Ping(e)
    }
}

impl From<autonat::Event> for NewgenBehaviourEvent {
    fn from(e: autonat::Event) -> Self {
        Self::Autonat(e)
    }
}

impl From<relay::client::Event> for NewgenBehaviourEvent {
    fn from(e: relay::client::Event) -> Self {
        Self::RelayClient(e)
    }
}

impl From<relay::Event> for NewgenBehaviourEvent {
    fn from(e: relay::Event) -> Self {
        Self::RelayServer(e)
    }
}

impl From<dcutr::Event> for NewgenBehaviourEvent {
    fn from(e: dcutr::Event) -> Self {
        Self::Dcutr(e)
    }
}

// ======================================================================================
//   UTILITY STRUCTS (Cache, Outbox, RateLimit)
// ======================================================================================

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum P2pBootPhase {
    /// Cold-start bootstrap from snapshot: allow dial/hello/RRv3 bootstrap only.
    ColdStartSnapshot,
    /// Node already has local state/DB but must complete runtime catch-up before it can propose again.
    RestartCatchup,
    /// Snapshot bootstrap failed or was skipped; allow normal live catch-up sync, but keep mining disabled
    /// until runtime convergence has been re-established.
    FallbackLiveSync,
    /// Normal steady-state runtime.
    SteadyState,
}

impl P2pBootPhase {
    fn allows_live_sync(self) -> bool {
        !matches!(self, P2pBootPhase::ColdStartSnapshot)
    }

    fn allows_mining(self) -> bool {
        matches!(self, P2pBootPhase::SteadyState)
    }

    fn as_str(self) -> &'static str {
        match self {
            Self::ColdStartSnapshot => "cold_start_snapshot",
            Self::RestartCatchup => "restart_catchup",
            Self::FallbackLiveSync => "fallback_live_sync",
            Self::SteadyState => "steady_state",
        }
    }
}

fn effective_runtime_quorum_k(
    configured_k: usize,
    eligible_peers: usize,
    connected: usize,
    multi_validator: bool,
) -> usize {
    let eligible = eligible_peers.max(1);
    let mut k = configured_k.max(1).min(eligible);
    if multi_validator {
        // V254: for a 4-validator concilium the operational quorum must be 3,
        // not the legacy 2-of-4 fallback. Keep small two-validator deployments
        // liveness-compatible, but require a 2/3 floor once the operational set
        // has at least three members.
        let two_thirds_floor = if eligible >= 3 {
            eligible.saturating_mul(2).saturating_add(2) / 3
        } else if connected >= 3 && eligible >= 2 {
            2
        } else {
            1
        };
        k = k.max(two_thirds_floor);
    }
    k.min(eligible)
}

fn effective_min_peers_for_mining_v254(
    configured_min_peers: usize,
    validator_count_canonical: usize,
    multi_validator: bool,
) -> usize {
    if !multi_validator {
        return configured_min_peers;
    }

    // effective_runtime_quorum_k counts operational validators. A local proposer
    // contributes one validator, while runtime_mining_ready checks connected peers;
    // therefore peer threshold = active-validator quorum - local validator.
    let active_validator_quorum = effective_runtime_quorum_k(
        1,
        validator_count_canonical.max(1),
        validator_count_canonical.max(1),
        true,
    );
    configured_min_peers
        .max(active_validator_quorum.saturating_sub(1))
        .max(1)
}

fn effective_min_peers_for_mining_v262(
    configured_min_peers: usize,
    validator_count_canonical: usize,
    multi_validator: bool,
    operational_quorum_ready: bool,
) -> usize {
    if !multi_validator {
        return configured_min_peers;
    }

    // V262: do not require every validator to have two direct libp2p links in a
    // star/bootnode topology once the runtime operational quorum has already
    // proved that three validators are booted, caught up, height-aligned and
    // visible. The V254 two-remote-peer floor is still used while quorum is not
    // ready, so two-node / self-only mining remains fail-closed.
    if operational_quorum_ready {
        return configured_min_peers.max(1);
    }

    effective_min_peers_for_mining_v254(
        configured_min_peers,
        validator_count_canonical,
        multi_validator,
    )
}

fn effective_min_peers_for_mining_v282(
    configured_min_peers: usize,
    validator_count_canonical: usize,
    multi_validator: bool,
    operational_quorum_ready: bool,
) -> usize {
    if !multi_validator {
        return configured_min_peers;
    }

    // V282: break the readiness/quorum circular dependency observed on the
    // 4-validator server after snapshot hardening. `p2p_ready_for_mining` is an
    // input to `runtime_operational_quorum_ready_for_next_block()`. If every
    // validator must first see quorum-1 direct libp2p links before exporting
    // p2p_ready=true, a partial/star topology can get stuck forever at
    // ready_count=1 even while A/B/C are booted, caught up, same-height and
    // mutually visible through at least one operational peer.
    //
    // This does NOT weaken final block production safety: mine_real_block(),
    // mine_empty_keepalive_block(), and tick_slot_pacing() still require
    // runtime_operational_quorum_ready_for_next_block() before producing the
    // next block. This helper only lets healthy validators export readiness so
    // the operational quorum can re-form.
    let configured = configured_min_peers.max(1);
    if operational_quorum_ready {
        return configured;
    }

    let _ = validator_count_canonical;
    configured
}

fn effective_fork_probe_hits_k(configured_k: usize, multi_validator: bool) -> u32 {
    let mut k = configured_k.max(1);
    if multi_validator {
        k = k.max(2);
    }
    k.min(u32::MAX as usize) as u32
}

fn runtime_sync_converged(
    connected: usize,
    multi_validator: bool,
    require_hello_ok_for_runtime: bool,
    hello_ok_count: usize,
    peer_heights_count: usize,
    syncing: bool,
    mine_behind: bool,
    catchup_ok: bool,
) -> bool {
    if connected == 0 {
        return !multi_validator;
    }

    let hello_ok_ready = (!require_hello_ok_for_runtime || hello_ok_count > 0)
        && (!multi_validator || hello_ok_count > 0);
    let peer_heights_ready = !multi_validator || peer_heights_count > 0;

    hello_ok_ready && peer_heights_ready && !syncing && !mine_behind && catchup_ok
}

fn runtime_bootstrap_transition_ready(
    connected: usize,
    runtime_sync_converged: bool,
    consensus_context_ready: bool,
    fork_ok: bool,
    fresh_view_effective_ok: bool,
) -> bool {
    connected > 0
        && runtime_sync_converged
        && consensus_context_ready
        && fork_ok
        && fresh_view_effective_ok
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct RuntimeBootPhaseStep {
    phase: P2pBootPhase,
    connected: usize,
    multi_validator: bool,
    require_hello_ok_for_runtime: bool,
    hello_ok_count: usize,
    peer_heights_count: usize,
    syncing: bool,
    mine_behind: bool,
    catchup_ok: bool,
    fork_ok: bool,
    fresh_view_effective_ok: bool,
    consensus_context_ready: bool,
    ready_streak: u8,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct RuntimeBootPhaseStepResult {
    runtime_sync_converged: bool,
    transition_ready_candidate: bool,
    next_phase: P2pBootPhase,
    next_ready_streak: u8,
    reached_steady_state: bool,
}

fn runtime_boot_phase_step(step: RuntimeBootPhaseStep) -> RuntimeBootPhaseStepResult {
    let runtime_sync_converged = runtime_sync_converged(
        step.connected,
        step.multi_validator,
        step.require_hello_ok_for_runtime,
        step.hello_ok_count,
        step.peer_heights_count,
        step.syncing,
        step.mine_behind,
        step.catchup_ok,
    );
    let transition_ready_candidate = runtime_bootstrap_transition_ready(
        step.connected,
        runtime_sync_converged,
        step.consensus_context_ready,
        step.fork_ok,
        step.fresh_view_effective_ok,
    );

    let mut next_phase = step.phase;
    let mut next_ready_streak: u8;
    let mut reached_steady_state = false;

    match step.phase {
        P2pBootPhase::RestartCatchup | P2pBootPhase::FallbackLiveSync => {
            next_ready_streak = if transition_ready_candidate {
                step.ready_streak.saturating_add(1)
            } else {
                0
            };
            if next_ready_streak >= 2 {
                next_phase = P2pBootPhase::SteadyState;
                next_ready_streak = 0;
                reached_steady_state = true;
            }
        }
        _ => {
            next_ready_streak = 0;
        }
    }

    RuntimeBootPhaseStepResult {
        runtime_sync_converged,
        transition_ready_candidate,
        next_phase,
        next_ready_streak,
        reached_steady_state,
    }
}

fn runtime_steady_state_local_sync_caught_up_v291(
    runtime_syncing: bool,
    runtime_mine_behind: bool,
    catchup_ok: bool,
    consensus_context_ready: bool,
    fork_hard: bool,
) -> bool {
    // V291: data/sync convergence is a local runtime property. Once the node is
    // already in SteadyState, absence of an operational/validator-ready peer in
    // the current tick must not by itself turn caught_up=false. Validator-ready
    // remains required only by consensus/mining surfaces (proposal gate, quorum,
    // voting/finality), not by snapshot/chunk transfer or local caught-up status.
    !runtime_syncing && !runtime_mine_behind && catchup_ok && consensus_context_ready && !fork_hard
}

fn runtime_sync_force_false_for_scope_v291(boot_phase: P2pBootPhase) -> bool {
    // V291: hard false is reserved for non-steady boot phases. In SteadyState,
    // remote operational scope loss is handled by p2p/proposal/quorum gates; it
    // must not be reinterpreted as local runtime sync loss.
    !matches!(boot_phase, P2pBootPhase::SteadyState)
}

fn runtime_mining_ready(
    connected: usize,
    multi_validator: bool,
    miner_authorized: bool,
    min_peers_for_mining: usize,
    runtime_sync_converged: bool,
    outbox_block_pending: bool,
    tip_gate_effective_ok: bool,
) -> bool {
    if connected == 0 {
        return miner_authorized && !multi_validator;
    }

    let peers_ok = connected >= min_peers_for_mining.max(1);
    miner_authorized
        && peers_ok
        && runtime_sync_converged
        && !outbox_block_pending
        && tip_gate_effective_ok
}

fn strict_proposal_gate_open(
    steady_state_gate: bool,
    connected: usize,
    multi_validator: bool,
    miner_authorized: bool,
    min_peers_for_mining: usize,
    runtime_sync_converged: bool,
    outbox_block_pending: bool,
    tip_gate_effective_ok: bool,
    fork_ok: bool,
    fresh_view_effective_ok: bool,
) -> bool {
    steady_state_gate
        && fork_ok
        && fresh_view_effective_ok
        && runtime_mining_ready(
            connected,
            multi_validator,
            miner_authorized,
            min_peers_for_mining,
            runtime_sync_converged,
            outbox_block_pending,
            tip_gate_effective_ok,
        )
}

fn observable_p2p_ready_candidate(
    steady_state_gate: bool,
    connected: usize,
    multi_validator: bool,
    miner_authorized: bool,
    min_peers_for_mining: usize,
    runtime_sync_caught_up_exported: bool,
    consensus_context_ready: bool,
    fork_hard: bool,
) -> bool {
    if connected == 0 {
        return steady_state_gate
            && miner_authorized
            && runtime_sync_caught_up_exported
            && consensus_context_ready
            && !fork_hard
            && !multi_validator;
    }

    let peers_ok = connected >= min_peers_for_mining.max(1);
    steady_state_gate
        && miner_authorized
        && peers_ok
        && runtime_sync_caught_up_exported
        && consensus_context_ready
        && !fork_hard
}

fn observable_p2p_ready_force_false(
    steady_state_gate: bool,
    connected: usize,
    multi_validator: bool,
    miner_authorized: bool,
    runtime_sync_caught_up_exported: bool,
) -> bool {
    let _ = connected;
    let _ = multi_validator;
    !steady_state_gate || !miner_authorized || !runtime_sync_caught_up_exported
}

#[derive(Debug)]
pub enum P2pControl {
    /// Supervisor applied a snapshot in-process; reset in-flight sync state and caches.
    StateSyncApplied { ack: oneshot::Sender<()> },
    /// Change runtime boot phase explicitly. Used to keep cold-start snapshot bootstrap
    /// separate from fallback live-sync / steady-state semantics while preserving one actor instance.
    SetBootPhase {
        phase: P2pBootPhase,
        ack: oneshot::Sender<()>,
    },
    /// Wait until the runtime network actor has reached a bootstrap-eligible connectivity state.
    /// In ColdStartSnapshot this requires a connected bootstrap seed peer and a semantic snapshot
    /// signal proving it is useful for cold-start bootstrap (snapshot advert or prior RRv3
    /// SnapshotV2Meta success). Hello-only connectivity is not sufficient. When `height_opt` is
    /// set, the bootstrap signal must also be height-compatible; otherwise a freshness floor is
    /// derived from connected bootstrap peer heights.
    AwaitBootstrapReady {
        height_opt: Option<u64>,
        timeout_ms: u64,
        response: oneshot::Sender<Result<(), String>>,
    },
    /// Fetch latest (or explicit-height) snapshot-v2 meta via the live runtime req/resp actor.
    FetchSnapshotV2Meta {
        height_opt: Option<u64>,
        timeout_ms: u64,
        response: oneshot::Sender<Result<SnapshotMetaRuntimeReply, String>>,
    },
    /// Return an ordered peer list suitable for runtime bootstrap snapshot/cert discovery.
    ListBootstrapSnapshotPeers {
        height_opt: Option<u64>,
        response: oneshot::Sender<Vec<PeerId>>,
    },
    /// Proactively requeue/redial configured bootstrap peers when runtime bootstrap fallback
    /// needs fresh connectivity. Best-effort and idempotent.
    NudgeBootstrapConnectivity { response: oneshot::Sender<()> },
    /// Fetch snapshot meta from a specific peer via the live runtime req/resp actor.
    FetchSnapshotV2MetaFromPeer {
        peer: PeerId,
        height_opt: Option<u64>,
        timeout_ms: u64,
        response: oneshot::Sender<Result<SnapshotMetaRuntimeReply, String>>,
    },
    /// Fetch latest checkpoint cert from a specific peer via the live runtime req/resp actor.
    FetchCheckpointCertLatestFromPeer {
        peer: PeerId,
        timeout_ms: u64,
        response: oneshot::Sender<Result<Option<CheckpointCert>, String>>,
    },
    /// Fetch a single snapshot-v2 chunk via the live runtime req/resp actor.
    FetchSnapshotV2Chunk {
        peer: PeerId,
        height: u64,
        chunk_index: u32,
        timeout_ms: u64,
        response: oneshot::Sender<Result<Vec<u8>, String>>,
    },
    /// Graceful shutdown for temporary bootstrap-only P2P runtimes.
    Shutdown { ack: oneshot::Sender<()> },
}

pub struct P2PHandle {
    pub tx_out: mpsc::UnboundedSender<NetMsg>,
    pub rx_in: mpsc::UnboundedReceiver<NetMsg>,
    pub ctrl: mpsc::UnboundedSender<P2pControl>,
}

const SEEN_CAP: usize = 2048;
const BLOCK_WIRE_SEEN_CAP: usize = 512;
const BLOCK_TERMINAL_SEEN_CAP: usize = 4096;
const DEFERRED_BLOCK_CAP: usize = 1024;
const DEFERRED_BLOCK_TTL_SECS: u64 = 120;
const DEFERRED_BLOCK_RETRY_BATCH: usize = 16;
const DEFERRED_BLOCK_MAX_RETRIES: u32 = 64;

struct SeenCache {
    block_wire: (HashSet<String>, VecDeque<String>),
    block_terminal: (HashSet<String>, VecDeque<String>),
    tx_msgs: HashSet<[u8; 32]>,
    tx_q: VecDeque<[u8; 32]>,
    finality_msgs: HashSet<[u8; 32]>,
    finality_q: VecDeque<[u8; 32]>,
    last_prune: Instant,
}

impl SeenCache {
    fn new() -> Self {
        Self {
            block_wire: (HashSet::new(), VecDeque::new()),
            block_terminal: (HashSet::new(), VecDeque::new()),
            tx_msgs: HashSet::new(),
            tx_q: VecDeque::new(),
            finality_msgs: HashSet::new(),
            finality_q: VecDeque::new(),
            last_prune: Instant::now(),
        }
    }

    fn reset(&mut self) {
        self.block_wire.0.clear();
        self.block_wire.1.clear();
        self.block_terminal.0.clear();
        self.block_terminal.1.clear();
        self.tx_msgs.clear();
        self.tx_q.clear();
        self.finality_msgs.clear();
        self.finality_q.clear();
        self.last_prune = Instant::now();
    }

    fn prune(&mut self) {
        if self.tx_q.len() > SEEN_CAP {
            let remove_count = self.tx_q.len() - SEEN_CAP;
            for _ in 0..remove_count {
                if let Some(h) = self.tx_q.pop_front() {
                    self.tx_msgs.remove(&h);
                }
            }
        }

        if self.finality_q.len() > SEEN_CAP {
            let remove_count = self.finality_q.len() - SEEN_CAP;
            for _ in 0..remove_count {
                if let Some(h) = self.finality_q.pop_front() {
                    self.finality_msgs.remove(&h);
                }
            }
        }

        self.last_prune = Instant::now();
    }

    fn contains_block_terminal(&self, h: &str) -> bool {
        self.block_terminal.0.contains(h)
    }

    fn insert_block_wire(&mut self, h: &str) -> bool {
        let (set, q) = &mut self.block_wire;
        if set.contains(h) {
            return false;
        }
        set.insert(h.to_string());
        q.push_back(h.to_string());
        if q.len() > BLOCK_WIRE_SEEN_CAP {
            if let Some(old) = q.pop_front() {
                set.remove(&old);
            }
        }
        true
    }

    fn mark_block_terminal(&mut self, h: &str) {
        if h.trim().is_empty() {
            return;
        }
        let (set, q) = &mut self.block_terminal;
        if set.insert(h.to_string()) {
            q.push_back(h.to_string());
            if q.len() > BLOCK_TERMINAL_SEEN_CAP {
                if let Some(old) = q.pop_front() {
                    set.remove(&old);
                }
            }
        }
    }

    fn insert_tx_msg(&mut self, id: [u8; 32]) -> bool {
        if self.tx_msgs.contains(&id) {
            return false;
        }
        self.tx_msgs.insert(id);
        self.tx_q.push_back(id);
        if self.tx_q.len() > SEEN_CAP {
            if let Some(old) = self.tx_q.pop_front() {
                self.tx_msgs.remove(&old);
            }
        }
        true
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum InboundBlockDisposition {
    Applied,
    DeferredForSync,
    ForkCandidate,
    RejectedPermanent,
    DroppedTransient,
}

impl InboundBlockDisposition {
    fn as_str(self) -> &'static str {
        match self {
            Self::Applied => "applied",
            Self::DeferredForSync => "deferred_for_sync",
            Self::ForkCandidate => "fork_candidate",
            Self::RejectedPermanent => "rejected_permanent",
            Self::DroppedTransient => "dropped_transient",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum InboundBlockIntakeState {
    Received,
    ValidatedBasic,
    AcceptedForProcessing,
    Applied,
    Deferred,
    RejectedPermanent,
    RejectedTransient,
}

impl InboundBlockIntakeState {
    fn as_str(self) -> &'static str {
        match self {
            Self::Received => "received",
            Self::ValidatedBasic => "validated_basic",
            Self::AcceptedForProcessing => "accepted_for_processing",
            Self::Applied => "applied",
            Self::Deferred => "deferred",
            Self::RejectedPermanent => "rejected_permanent",
            Self::RejectedTransient => "rejected_transient",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DeferredReason {
    AheadOfLocalTip,
    MissingParent,
    SyncInProgress,
    CompetingTip,
}

impl DeferredReason {
    fn as_str(self) -> &'static str {
        match self {
            Self::AheadOfLocalTip => "ahead_of_local_tip",
            Self::MissingParent => "missing_parent",
            Self::SyncInProgress => "sync_in_progress",
            Self::CompetingTip => "competing_tip",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DeferredBlockClass {
    LinearExtension,
    ForkCandidate,
    MissingParentDependency,
}

impl DeferredBlockClass {
    fn as_str(self) -> &'static str {
        match self {
            Self::LinearExtension => "linear_extension",
            Self::ForkCandidate => "fork_candidate",
            Self::MissingParentDependency => "missing_parent_dependency",
        }
    }

    fn from_reason(reason: DeferredReason) -> Self {
        match reason {
            DeferredReason::AheadOfLocalTip | DeferredReason::SyncInProgress => {
                Self::LinearExtension
            }
            DeferredReason::CompetingTip => Self::ForkCandidate,
            DeferredReason::MissingParent => Self::MissingParentDependency,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct DeferredBlockPlan {
    disposition: InboundBlockDisposition,
    reason: DeferredReason,
    class: DeferredBlockClass,
    retry_after_height: Option<u64>,
    sync_target_height: Option<u64>,
}

#[derive(Debug, Clone)]
struct SyncIntent {
    target_height: u64,
    trigger_block_hash: Option<String>,
    source_peer: String,
    created_at_ms: u64,
}

#[derive(Debug, Clone)]
struct DeferredInboundBlock {
    block: Block,
    received_from: PeerId,
    received_at: Instant,
    received_at_ms: u64,
    class: DeferredBlockClass,
    reason: DeferredReason,
    retry_after_height: Option<u64>,
    retries: u32,
}

struct DeferredBlockCache {
    entries: HashMap<String, DeferredInboundBlock>,
    order: VecDeque<String>,
}

impl DeferredBlockCache {
    fn new() -> Self {
        Self {
            entries: HashMap::new(),
            order: VecDeque::new(),
        }
    }

    fn reset(&mut self) {
        self.entries.clear();
        self.order.clear();
        perf_metrics::p2p_deferred_block_queue_set(0);
    }

    fn contains(&self, hash: &str) -> bool {
        self.entries.contains_key(hash)
    }

    #[cfg(test)]
    fn len(&self) -> usize {
        self.entries.len()
    }

    fn upsert(
        &mut self,
        block: Block,
        received_from: PeerId,
        reason: DeferredReason,
        retry_after_height: Option<u64>,
    ) {
        let hash = block.hash.clone();
        let now = Instant::now();
        let now_ms = unix_time_millis_now();
        if let Some(existing) = self.entries.get_mut(&hash) {
            existing.block = block;
            existing.received_from = received_from;
            existing.received_at = now;
            existing.received_at_ms = now_ms;
            existing.class = DeferredBlockClass::from_reason(reason);
            existing.reason = reason;
            existing.retry_after_height = retry_after_height;
            return;
        }
        if self.order.len() >= DEFERRED_BLOCK_CAP {
            while let Some(old_hash) = self.order.pop_front() {
                if self.entries.remove(&old_hash).is_some() {
                    break;
                }
            }
        }
        self.order.push_back(hash.clone());
        self.entries.insert(
            hash,
            DeferredInboundBlock {
                block,
                received_from,
                received_at: now,
                received_at_ms: now_ms,
                class: DeferredBlockClass::from_reason(reason),
                reason,
                retry_after_height,
                retries: 0,
            },
        );
        perf_metrics::p2p_deferred_block_queue_set(self.entries.len());
    }

    fn note_retry(&mut self, hash: &str, reason: DeferredReason, retry_after_height: Option<u64>) {
        if let Some(entry) = self.entries.get_mut(hash) {
            entry.reason = reason;
            entry.retry_after_height = retry_after_height;
            entry.received_at = Instant::now();
            entry.received_at_ms = unix_time_millis_now();
            entry.retries = entry.retries.saturating_add(1);
            perf_metrics::p2p_deferred_block_retry();
        }
    }

    fn get_cloned(&self, hash: &str) -> Option<DeferredInboundBlock> {
        self.entries.get(hash).cloned()
    }

    fn remove(&mut self, hash: &str) -> Option<DeferredInboundBlock> {
        let removed = self.entries.remove(hash);
        if removed.is_some() {
            self.order.retain(|h| h != hash);
            perf_metrics::p2p_deferred_block_queue_set(self.entries.len());
        }
        removed
    }

    fn ready_hashes(&self, local_next_height: u64, limit: usize) -> Vec<String> {
        let mut out = Vec::new();
        for hash in self.order.iter() {
            let Some(entry) = self.entries.get(hash) else {
                continue;
            };
            let ready = entry
                .retry_after_height
                .map(|h| local_next_height >= h)
                .unwrap_or(true);
            if ready {
                out.push(hash.clone());
                if out.len() >= limit {
                    break;
                }
            }
        }
        out
    }

    fn remove_recovery_incompatible_above_tip(&mut self, local_tip_height: u64) -> usize {
        let hashes: Vec<String> = self
            .entries
            .iter()
            .filter_map(|(hash, entry)| {
                (entry.block.index > local_tip_height
                    && matches!(entry.class, DeferredBlockClass::LinearExtension))
                .then(|| hash.clone())
            })
            .collect();
        let removed = hashes.len();
        for hash in hashes {
            let _ = self.remove(&hash);
        }
        removed
    }

    fn prune(&mut self) {
        let ttl = Duration::from_secs(DEFERRED_BLOCK_TTL_SECS);
        let now = Instant::now();
        self.order.retain(|hash| {
            self.entries
                .get(hash)
                .map(|entry| now.duration_since(entry.received_at) <= ttl)
                .unwrap_or(false)
        });
        self.entries
            .retain(|_, entry| now.duration_since(entry.received_at) <= ttl);
        while self.order.len() > DEFERRED_BLOCK_CAP {
            if let Some(old_hash) = self.order.pop_front() {
                self.entries.remove(&old_hash);
            }
        }
        perf_metrics::p2p_deferred_block_queue_set(self.entries.len());
    }
}

fn unix_time_millis_now() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis() as u64
}

const RUNTIME_TELEMETRY_SIG_CTX: &[u8] = b"P2P_RUNTIME_TELEMETRY_V2";
const RUNTIME_TELEMETRY_MAX_FUTURE_SKEW_SECS: u64 = 5;
const RUNTIME_TELEMETRY_MAX_AGE_SECS: u64 = 30;
const FULL_PULSE_PERIOD_SECS: u64 = 20;
const FULL_PULSE_TELEMETRY_TS_BUCKET_SECS: u64 = 30;
const VERIFIED_RUNTIME_TELEMETRY_CACHE_MAX_ENTRIES: usize = 4096;
const HELLO_RETRY_INTERVAL_AGGRESSIVE_SECS: u64 = 3;
const HELLO_RETRY_INTERVAL_STEADY_SECS: u64 = 15;
const RUNTIME_SYNC_EXPORT_FALSE_DEBOUNCE_SECS: u64 = 5;
const P2P_READY_EXPORT_FALSE_DEBOUNCE_SECS: u64 = 3;

#[derive(Clone, Debug, PartialEq, Eq, Hash)]
struct LocalPulseFullState {
    height: u64,
    tip_hash: Option<String>,
    finalized_height: u64,
    finalized_hash: String,
    genesis_hash: String,
    validator_set_hash: String,
    validator_pubkey: Option<String>,
    runtime_sync_caught_up: bool,
    runtime_bootstrap_complete: bool,
    p2p_ready_for_mining: bool,
}

#[derive(Clone, Debug)]
struct LocalP2pRuntimeSnapshot {
    pulse_state: LocalPulseFullState,
}

#[derive(Clone, Debug, PartialEq, Eq, Hash)]
struct CachedFullPulseKey {
    pulse_state: LocalPulseFullState,
    peer_id: String,
    chain_id: String,
    telemetry_ts: u64,
}

#[derive(Clone, Debug)]
struct CachedFullPulseEntry {
    key: CachedFullPulseKey,
    encoded: Vec<u8>,
}

#[derive(Clone, Debug, PartialEq, Eq, Hash)]
struct VerifiedRuntimeTelemetryCacheKey {
    kind: &'static str,
    sender_peer_id: String,
    validator_pubkey: String,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct VerifiedRuntimeTelemetryCacheEntry {
    runtime_telemetry_sig_b64: String,
    payload_fingerprint: String,
}

fn pulse_full_runtime_changed(prev: &LocalPulseFullState, next: &LocalPulseFullState) -> bool {
    prev.genesis_hash != next.genesis_hash
        || prev.validator_set_hash != next.validator_set_hash
        || prev.validator_pubkey != next.validator_pubkey
        || prev.runtime_sync_caught_up != next.runtime_sync_caught_up
        || prev.runtime_bootstrap_complete != next.runtime_bootstrap_complete
        || prev.p2p_ready_for_mining != next.p2p_ready_for_mining
}

fn pulse_full_progress_changed(prev: &LocalPulseFullState, next: &LocalPulseFullState) -> bool {
    prev.height != next.height
        || prev.tip_hash != next.tip_hash
        || prev.finalized_height != next.finalized_height
        || prev.finalized_hash != next.finalized_hash
}

fn should_send_full_pulse(
    last_sent_at: Option<Instant>,
    last_state: Option<&LocalPulseFullState>,
    next_state: &LocalPulseFullState,
) -> bool {
    let Some(prev) = last_state else {
        return true;
    };
    let elapsed = last_sent_at
        .map(|t| t.elapsed())
        .unwrap_or_else(|| Duration::from_secs(u64::MAX));
    let due_by_time = elapsed >= Duration::from_secs(FULL_PULSE_PERIOD_SECS);
    due_by_time
        || pulse_full_runtime_changed(prev, next_state)
        || pulse_full_progress_changed(prev, next_state)
}

fn full_pulse_telemetry_ts_bucket(now_secs: u64) -> u64 {
    if now_secs == 0 {
        return 0;
    }
    now_secs - (now_secs % FULL_PULSE_TELEMETRY_TS_BUCKET_SECS)
}

fn runtime_telemetry_payload_fingerprint(
    kind: &str,
    validator_pubkey: &str,
    telemetry_peer_id: &str,
    chain_id: &str,
    genesis_hash: &str,
    validator_set_hash: &str,
    height: u64,
    finalized_height: u64,
    finalized_hash: &str,
    ts: u64,
    runtime_sync_caught_up: bool,
    runtime_bootstrap_complete: bool,
    p2p_ready_for_mining: bool,
) -> String {
    let msg = runtime_telemetry_message(
        kind,
        validator_pubkey,
        telemetry_peer_id,
        chain_id,
        genesis_hash,
        validator_set_hash,
        height,
        finalized_height,
        finalized_hash,
        ts,
        runtime_sync_caught_up,
        runtime_bootstrap_complete,
        p2p_ready_for_mining,
    );
    {
        let digest = Sha256::digest(&msg);
        hex::encode(digest)
    }
}

fn reuse_verified_runtime_telemetry(
    cache: &HashMap<VerifiedRuntimeTelemetryCacheKey, VerifiedRuntimeTelemetryCacheEntry>,
    key: &VerifiedRuntimeTelemetryCacheKey,
    runtime_telemetry_sig_b64: &str,
    payload_fingerprint: &str,
) -> bool {
    cache
        .get(key)
        .map(|entry| {
            entry.runtime_telemetry_sig_b64 == runtime_telemetry_sig_b64
                && entry.payload_fingerprint == payload_fingerprint
        })
        .unwrap_or(false)
}

fn remember_verified_runtime_telemetry(
    cache: &mut HashMap<VerifiedRuntimeTelemetryCacheKey, VerifiedRuntimeTelemetryCacheEntry>,
    key: VerifiedRuntimeTelemetryCacheKey,
    runtime_telemetry_sig_b64: &str,
    payload_fingerprint: &str,
) {
    if cache.len() >= VERIFIED_RUNTIME_TELEMETRY_CACHE_MAX_ENTRIES {
        cache.clear();
    }
    cache.insert(
        key,
        VerifiedRuntimeTelemetryCacheEntry {
            runtime_telemetry_sig_b64: runtime_telemetry_sig_b64.to_string(),
            payload_fingerprint: payload_fingerprint.to_string(),
        },
    );
}

fn forget_verified_runtime_telemetry_for_sender(
    cache: &mut HashMap<VerifiedRuntimeTelemetryCacheKey, VerifiedRuntimeTelemetryCacheEntry>,
    sender_peer_id: &str,
) {
    cache.retain(|key, _| key.sender_peer_id != sender_peer_id);
}

fn hello_retry_interval(
    boot_phase: P2pBootPhase,
    connected_peer_count: usize,
    hello_ok_peer_count: usize,
    hello_pending_count: usize,
) -> Duration {
    if hello_pending_count == 0 || connected_peer_count == 0 {
        return Duration::from_secs(HELLO_RETRY_INTERVAL_STEADY_SECS);
    }

    let bootstrap_like = matches!(
        boot_phase,
        P2pBootPhase::ColdStartSnapshot
            | P2pBootPhase::RestartCatchup
            | P2pBootPhase::FallbackLiveSync
    );
    let initial_peer_discovery = connected_peer_count > 0 && hello_ok_peer_count == 0;

    if bootstrap_like || initial_peer_discovery {
        Duration::from_secs(HELLO_RETRY_INTERVAL_AGGRESSIVE_SECS)
    } else {
        Duration::from_secs(HELLO_RETRY_INTERVAL_STEADY_SECS)
    }
}

fn runtime_should_publish_operational_hello_v293(boot_phase: P2pBootPhase) -> bool {
    // V293: while a node is still downloading/verifying/applying snapshot
    // chunks, it must stay data-plane-only. Sending an operational Hello before
    // snapshot apply makes healthy validators see a half-formed identity
    // (wrong/partial chain context) and can pollute admission/quorum state.
    // StateSyncApplied moves the node out of ColdStartSnapshot; only then may
    // it start normal admission Hello exchange.
    !matches!(boot_phase, P2pBootPhase::ColdStartSnapshot)
}

fn runtime_should_publish_operational_heartbeat_v293(boot_phase: P2pBootPhase) -> bool {
    // Pulse/PulseLight are operational heartbeat surfaces: peers consume them
    // for height, tip, runtime telemetry and fork/readiness decisions. During
    // cold snapshot, RRv3 snapshot/chunk transfer remains allowed, but heartbeat
    // gossip is suppressed until the snapshot has been applied.
    !matches!(boot_phase, P2pBootPhase::ColdStartSnapshot)
}

fn runtime_should_publish_operational_hello_v307(
    boot_phase: P2pBootPhase,
    post_snapshot_tail_recovery_active: bool,
) -> bool {
    runtime_should_publish_operational_hello_v293(boot_phase) && !post_snapshot_tail_recovery_active
}

fn runtime_should_publish_operational_heartbeat_v307(
    boot_phase: P2pBootPhase,
    post_snapshot_tail_recovery_active: bool,
) -> bool {
    runtime_should_publish_operational_heartbeat_v293(boot_phase)
        && !post_snapshot_tail_recovery_active
}

fn cold_snapshot_inbound_operational_message_is_data_plane_only_v307(
    boot_phase: P2pBootPhase,
) -> bool {
    matches!(boot_phase, P2pBootPhase::ColdStartSnapshot)
}

fn post_snapshot_tail_data_plane_sync_should_arm_v307(
    post_snapshot_tail_recovery_active: bool,
    boot_phase: P2pBootPhase,
    connected_peers: usize,
    local_next: u64,
) -> bool {
    post_snapshot_tail_recovery_active
        && matches!(
            boot_phase,
            P2pBootPhase::RestartCatchup | P2pBootPhase::FallbackLiveSync
        )
        && connected_peers > 0
        && local_next > 1
}

fn post_snapshot_tail_missing_retry_should_continue_v307(
    post_snapshot_tail_recovery_active: bool,
    boot_phase: P2pBootPhase,
    retry_block_present: bool,
    applied_blocks: usize,
    local_next: u64,
    raw_connected_peers: usize,
) -> bool {
    post_snapshot_tail_data_plane_sync_should_arm_v307(
        post_snapshot_tail_recovery_active,
        boot_phase,
        raw_connected_peers,
        local_next,
    ) && !retry_block_present
        && applied_blocks > 0
}

fn post_snapshot_tail_response_page_should_continue_v308(
    post_snapshot_tail_recovery_active: bool,
    boot_phase: P2pBootPhase,
    applied_blocks: usize,
    response_blocks: usize,
    request_limit: usize,
    local_next: u64,
    raw_connected_peers: usize,
) -> bool {
    if !post_snapshot_tail_data_plane_sync_should_arm_v307(
        post_snapshot_tail_recovery_active,
        boot_phase,
        raw_connected_peers,
        local_next,
    ) {
        return false;
    }

    if applied_blocks == 0 || response_blocks == 0 {
        return false;
    }

    // V308: during post-snapshot tail recovery, an almost-full RR page is
    // evidence that the provider may still have more blocks after local_next.
    // Do not infer "tail complete" from empty/stale peer_heights; ask again
    // from the freshly advanced local height. This keeps the rule simple and
    // data-plane-only, without reintroducing global max_known/admission logic.
    let effective_limit = request_limit.max(1);
    let almost_full_threshold = effective_limit.saturating_sub(1).max(1);
    response_blocks >= almost_full_threshold
}

fn post_snapshot_tail_rearm_operational_hello_v308(
    connected_now: &HashSet<PeerId>,
    peer_network_identity_quarantine_v292: &mut HashMap<PeerId, Instant>,
    peer_vsh_mismatch: &mut HashSet<PeerId>,
    hello_ok: &mut HashSet<PeerId>,
    hello_received: &mut HashSet<PeerId>,
    hello_sent_after_connect: &mut HashSet<PeerId>,
    hello_pending: &mut HashSet<PeerId>,
    last_hello_broadcast: &mut Option<Instant>,
    last_full_pulse_sent_at: &mut Option<Instant>,
    last_full_pulse_state: &mut Option<LocalPulseFullState>,
    cached_full_pulse_entry: &mut Option<CachedFullPulseEntry>,
) {
    peer_network_identity_quarantine_v292.clear();
    peer_vsh_mismatch.clear();
    hello_ok.clear();
    hello_received.clear();
    hello_sent_after_connect.clear();
    hello_pending.clear();
    hello_pending.extend(connected_now.iter().copied());
    *last_hello_broadcast = None;
    *last_full_pulse_sent_at = None;
    *last_full_pulse_state = None;
    *cached_full_pulse_entry = None;
}

fn promote_completed_hello_handshakes(
    connected: &HashSet<PeerId>,
    hello_received: &HashSet<PeerId>,
    hello_sent_after_connect: &HashSet<PeerId>,
    hello_pending: &mut HashSet<PeerId>,
    hello_ok: &mut HashSet<PeerId>,
) -> usize {
    let ready: Vec<PeerId> = hello_received
        .iter()
        .filter(|peer| connected.contains(peer) && hello_sent_after_connect.contains(peer))
        .copied()
        .collect();

    let mut promoted = 0usize;
    for peer in ready {
        if hello_ok.insert(peer) {
            promoted = promoted.saturating_add(1);
        }
        hello_pending.remove(&peer);
    }
    promoted
}

fn note_successful_hello_broadcast(
    connected_targets: &HashSet<PeerId>,
    hello_received: &HashSet<PeerId>,
    hello_sent_after_connect: &mut HashSet<PeerId>,
    hello_pending: &mut HashSet<PeerId>,
    hello_ok: &mut HashSet<PeerId>,
) -> usize {
    hello_sent_after_connect.extend(connected_targets.iter().copied());
    promote_completed_hello_handshakes(
        connected_targets,
        hello_received,
        hello_sent_after_connect,
        hello_pending,
        hello_ok,
    )
}

fn can_trigger_pulse_light_fork_probe(
    boot_phase: P2pBootPhase,
    peer_is_hello_ok: bool,
    sync_in_flight_peer: Option<PeerId>,
    pending_sync_peer: Option<PeerId>,
    last_fork_probe: &HashMap<PeerId, Instant>,
    pid: PeerId,
    now: Instant,
    p2p_policy: &P2PPolicy,
) -> bool {
    let non_fragile_phase = matches!(
        boot_phase,
        P2pBootPhase::FallbackLiveSync | P2pBootPhase::SteadyState
    );
    if !non_fragile_phase || !peer_is_hello_ok {
        return false;
    }
    if sync_in_flight_peer.is_some() || pending_sync_peer.is_some() {
        return false;
    }
    last_fork_probe
        .get(&pid)
        .map(|t| {
            now.duration_since(*t) >= Duration::from_secs(p2p_policy.fork_probe_cooldown_sec.max(1))
        })
        .unwrap_or(true)
}

fn runtime_telemetry_message(
    kind: &str,
    validator_pubkey: &str,
    telemetry_peer_id: &str,
    chain_id: &str,
    genesis_hash: &str,
    validator_set_hash: &str,
    height: u64,
    finalized_height: u64,
    finalized_hash: &str,
    ts: u64,
    runtime_sync_caught_up: bool,
    runtime_bootstrap_complete: bool,
    p2p_ready_for_mining: bool,
) -> Vec<u8> {
    format!(
        "{}|{}|{}|{}|{}|{}|{}|{}|{}|{}|{}|{}|{}",
        kind,
        validator_pubkey,
        telemetry_peer_id,
        chain_id,
        genesis_hash,
        validator_set_hash,
        height,
        finalized_height,
        finalized_hash,
        ts,
        runtime_sync_caught_up as u8,
        runtime_bootstrap_complete as u8,
        p2p_ready_for_mining as u8,
    )
    .into_bytes()
}

fn runtime_telemetry_network_payload_matches(
    telemetry_peer_id: &str,
    telemetry_chain_id: &str,
    telemetry_genesis_hash: &str,
    telemetry_validator_set_hash: &str,
    expected_chain_id: &str,
    expected_genesis_hash: &str,
    _expected_validator_set_hash: &str,
) -> bool {
    !telemetry_peer_id.trim().is_empty()
        && telemetry_chain_id.trim() == expected_chain_id.trim()
        && telemetry_genesis_hash.trim() == expected_genesis_hash.trim()
        && !telemetry_validator_set_hash.trim().is_empty()
}

fn runtime_telemetry_timestamp_is_timely(ts: u64, now_secs: u64) -> bool {
    if ts == 0 {
        return false;
    }
    if ts > now_secs.saturating_add(RUNTIME_TELEMETRY_MAX_FUTURE_SKEW_SECS) {
        return false;
    }
    now_secs.saturating_sub(ts) <= RUNTIME_TELEMETRY_MAX_AGE_SECS
}

fn exported_runtime_sync_caught_up(
    strict_caught_up: bool,
    previous_exported: bool,
    false_candidate_since: &mut Option<Instant>,
    now: Instant,
    false_debounce: Duration,
    force_false: bool,
) -> bool {
    if strict_caught_up {
        *false_candidate_since = None;
        return true;
    }

    if force_false {
        *false_candidate_since = Some(now);
        return false;
    }

    if !previous_exported {
        *false_candidate_since = Some(now);
        return false;
    }

    match false_candidate_since {
        Some(since) if now.duration_since(*since) >= false_debounce => false,
        Some(_) => previous_exported,
        None => {
            *false_candidate_since = Some(now);
            previous_exported
        }
    }
}

fn exported_p2p_ready_for_mining(
    strict_ready: bool,
    previous_exported: bool,
    false_candidate_since: &mut Option<Instant>,
    now: Instant,
    false_debounce: Duration,
    force_false: bool,
) -> bool {
    if strict_ready {
        *false_candidate_since = None;
        return true;
    }

    if force_false {
        *false_candidate_since = Some(now);
        return false;
    }

    if !previous_exported {
        *false_candidate_since = Some(now);
        return false;
    }

    match false_candidate_since {
        Some(since) if now.duration_since(*since) >= false_debounce => false,
        Some(_) => previous_exported,
        None => {
            *false_candidate_since = Some(now);
            previous_exported
        }
    }
}

fn try_decode_signing_key_b64(secret_key_b64: &str) -> Option<SigningKey> {
    let sk_bytes = STANDARD.decode(secret_key_b64).ok()?;
    let sk_arr: [u8; 32] = sk_bytes.as_slice().try_into().ok()?;
    Some(SigningKey::from_bytes(&sk_arr))
}

fn runtime_telemetry_from_snapshot(
    kind: &str,
    telemetry_peer_id: &str,
    chain_id: &str,
    pulse_state: &LocalPulseFullState,
    signing_key: Option<&SigningKey>,
    ts: u64,
) -> (Option<String>, bool, bool, bool, Option<String>) {
    let telemetry_sig_b64 = pulse_state
        .validator_pubkey
        .as_ref()
        .and_then(|validator_pubkey| {
            if telemetry_peer_id.trim().is_empty()
                || chain_id.trim().is_empty()
                || pulse_state.genesis_hash.trim().is_empty()
                || pulse_state.validator_set_hash.trim().is_empty()
                || ts == 0
            {
                return None;
            }
            let sk = signing_key?;
            let msg = runtime_telemetry_message(
                kind,
                validator_pubkey,
                telemetry_peer_id,
                chain_id,
                &pulse_state.genesis_hash,
                &pulse_state.validator_set_hash,
                pulse_state.height,
                pulse_state.finalized_height,
                &pulse_state.finalized_hash,
                ts,
                pulse_state.runtime_sync_caught_up,
                pulse_state.runtime_bootstrap_complete,
                pulse_state.p2p_ready_for_mining,
            );
            Some(crate::crypto::sign_ds_b64(
                sk,
                RUNTIME_TELEMETRY_SIG_CTX,
                &msg,
            ))
        });
    (
        pulse_state.validator_pubkey.clone(),
        pulse_state.runtime_sync_caught_up,
        pulse_state.runtime_bootstrap_complete,
        pulse_state.p2p_ready_for_mining,
        telemetry_sig_b64,
    )
}

#[allow(clippy::too_many_arguments)]
fn verify_runtime_telemetry_signature(
    kind: &str,
    validator_pubkey: &str,
    telemetry_peer_id: &str,
    chain_id: &str,
    genesis_hash: &str,
    validator_set_hash: &str,
    height: u64,
    finalized_height: u64,
    finalized_hash: &str,
    ts: u64,
    runtime_sync_caught_up: bool,
    runtime_bootstrap_complete: bool,
    p2p_ready_for_mining: bool,
    runtime_telemetry_sig_b64: &str,
) -> bool {
    let msg = runtime_telemetry_message(
        kind,
        validator_pubkey,
        telemetry_peer_id,
        chain_id,
        genesis_hash,
        validator_set_hash,
        height,
        finalized_height,
        finalized_hash,
        ts,
        runtime_sync_caught_up,
        runtime_bootstrap_complete,
        p2p_ready_for_mining,
    );
    crate::crypto::verify_ds_b64(
        validator_pubkey,
        runtime_telemetry_sig_b64,
        RUNTIME_TELEMETRY_SIG_CTX,
        &msg,
    )
    .is_ok()
}

fn sync_state_label(sync_in_flight: bool, pending_sync_from: Option<u64>) -> &'static str {
    if sync_in_flight {
        "in_flight"
    } else if pending_sync_from.is_some() {
        "pending"
    } else {
        "idle"
    }
}

/// Canonical local P2P progress height.
///
/// This is the next block height expected by the node (tip + 1), not the
/// current tip height. Keep all Hello / Pulse / sync-trigger code on this
/// helper so snapshot/pruned windows do not drift across callsites.
fn local_p2p_height(chain: &Blockchain) -> u64 {
    if chain.chain.is_empty() {
        return if chain.base_height() == 0 {
            0
        } else {
            chain.tip_height_u64().saturating_add(1)
        };
    }

    let next_from_tip_height = chain.tip_height_u64().saturating_add(1);
    let next_from_tail = chain
        .chain
        .last()
        .map(|b| b.index.saturating_add(1))
        .unwrap_or(0);
    let next_from_window = (chain.height() as u64).saturating_add(1);
    debug_assert_eq!(
        next_from_tail, next_from_tip_height,
        "local_p2p_height drifted from Blockchain::tip_height_u64()"
    );
    debug_assert_eq!(
        next_from_tip_height, next_from_window,
        "local_p2p_height drifted from Blockchain::height()"
    );
    next_from_tip_height
}

fn hello_tip_hash_field(pulse_state: &LocalPulseFullState) -> Option<String> {
    pulse_state.tip_hash.clone()
}

fn log_new_block_intake_event(
    state: InboundBlockIntakeState,
    block: &Block,
    sender_peer: &PeerId,
    local_height: u64,
    disposition: Option<InboundBlockDisposition>,
    reason: Option<&str>,
    boot_phase: P2pBootPhase,
    sync_state: &str,
) {
    let disposition_str = disposition.map(|d| d.as_str()).unwrap_or("none");
    let reason_str = reason.unwrap_or("none");
    match state {
        InboundBlockIntakeState::Received
        | InboundBlockIntakeState::ValidatedBasic
        | InboundBlockIntakeState::AcceptedForProcessing => {
            ng_debug!(
                target: "p2p.chain",
                "event=new_block_intake state={} block_hash={} block_height={} prev_hash={} sender_peer={} local_height={} disposition={} reason={} boot_phase={} sync_state={}",
                state.as_str(),
                block.hash,
                block.index,
                block.previous_hash,
                sender_peer,
                local_height,
                disposition_str,
                reason_str,
                boot_phase.as_str(),
                sync_state,
            );
        }
        InboundBlockIntakeState::Applied | InboundBlockIntakeState::Deferred => {
            ng_info!(
                target: "p2p.chain",
                "event=new_block_intake state={} block_hash={} block_height={} prev_hash={} sender_peer={} local_height={} disposition={} reason={} boot_phase={} sync_state={}",
                state.as_str(),
                block.hash,
                block.index,
                block.previous_hash,
                sender_peer,
                local_height,
                disposition_str,
                reason_str,
                boot_phase.as_str(),
                sync_state,
            );
        }
        InboundBlockIntakeState::RejectedPermanent | InboundBlockIntakeState::RejectedTransient => {
            ng_warn!(
                target: "p2p.chain",
                "event=new_block_intake state={} block_hash={} block_height={} prev_hash={} sender_peer={} local_height={} disposition={} reason={} boot_phase={} sync_state={}",
                state.as_str(),
                block.hash,
                block.index,
                block.previous_hash,
                sender_peer,
                local_height,
                disposition_str,
                reason_str,
                boot_phase.as_str(),
                sync_state,
            );
        }
    }
}

fn make_sync_intent(
    target_height: u64,
    trigger_block_hash: Option<String>,
    source_peer: &PeerId,
) -> SyncIntent {
    SyncIntent {
        target_height,
        trigger_block_hash,
        source_peer: source_peer.to_string(),
        created_at_ms: unix_time_millis_now(),
    }
}

fn is_new_block_invalid_basic(block: &Block) -> bool {
    !block.verify_signature() || block.try_calculate_hash().map_or(true, |h| block.hash != h)
}

fn block_extends_tip_now(block: &Block, tip_hash: &str, local_next_height: u64) -> bool {
    block.previous_hash == tip_hash && block.index == local_next_height
}

fn plan_new_block_deferral(
    block: &Block,
    local_next_height: u64,
    local_tip_hash: Option<&str>,
    parent_known: bool,
    fork_probe_enabled: bool,
) -> Option<DeferredBlockPlan> {
    if local_next_height == 0 {
        return Some(DeferredBlockPlan {
            disposition: InboundBlockDisposition::DeferredForSync,
            reason: DeferredReason::AheadOfLocalTip,
            class: DeferredBlockClass::LinearExtension,
            retry_after_height: Some(1),
            sync_target_height: Some(1),
        });
    }

    if block.index > local_next_height {
        return Some(DeferredBlockPlan {
            disposition: InboundBlockDisposition::DeferredForSync,
            reason: DeferredReason::AheadOfLocalTip,
            class: DeferredBlockClass::LinearExtension,
            retry_after_height: Some(local_next_height.max(1)),
            sync_target_height: Some(local_next_height.max(1)),
        });
    }

    if fork_probe_enabled
        && local_tip_hash.is_some()
        && block.index.saturating_add(1) == local_next_height
        && local_tip_hash != Some(block.hash.as_str())
    {
        return Some(DeferredBlockPlan {
            disposition: InboundBlockDisposition::ForkCandidate,
            reason: DeferredReason::CompetingTip,
            class: DeferredBlockClass::ForkCandidate,
            retry_after_height: Some(local_next_height.max(1)),
            sync_target_height: None,
        });
    }

    if !parent_known {
        return Some(DeferredBlockPlan {
            disposition: InboundBlockDisposition::DeferredForSync,
            reason: DeferredReason::MissingParent,
            class: DeferredBlockClass::MissingParentDependency,
            retry_after_height: None,
            sync_target_height: None,
        });
    }

    None
}

fn register_deferred_block(
    cache: &mut DeferredBlockCache,
    block: &Block,
    sender_peer: PeerId,
    local_height: u64,
    plan: DeferredBlockPlan,
    boot_phase: P2pBootPhase,
    sync_in_flight: bool,
    pending_sync_from: Option<u64>,
) {
    cache.upsert(
        block.clone(),
        sender_peer,
        plan.reason,
        plan.retry_after_height,
    );
    perf_metrics::p2p_new_block_deferred();
    log_new_block_intake_event(
        InboundBlockIntakeState::Deferred,
        block,
        &sender_peer,
        local_height,
        Some(plan.disposition),
        Some(plan.reason.as_str()),
        boot_phase,
        sync_state_label(sync_in_flight, pending_sync_from),
    );
    ng_info!(
        target: "p2p.chain",
        "event=new_block_buffered block_hash={} block_height={} class={} reason={} disposition={} retry_after_height={} sync_target_height={} sender_peer={}",
        block.hash,
        block.index,
        plan.class.as_str(),
        plan.reason.as_str(),
        plan.disposition.as_str(),
        plan.retry_after_height.map(|v| v.to_string()).unwrap_or_else(|| "none".to_string()),
        plan.sync_target_height.map(|v| v.to_string()).unwrap_or_else(|| "none".to_string()),
        sender_peer,
    );
}

fn chain_contains_hash(chain: &Blockchain, hash: &str) -> bool {
    chain.chain.iter().any(|b| b.hash == hash)
}

impl SeenCache {
    fn insert_finality_msg(&mut self, id: [u8; 32]) -> bool {
        if self.finality_msgs.contains(&id) {
            return false;
        }

        self.finality_msgs.insert(id);
        self.finality_q.push_back(id);

        if self.finality_q.len() > SEEN_CAP {
            if let Some(old) = self.finality_q.pop_front() {
                self.finality_msgs.remove(&old);
            }
        }

        if self.last_prune.elapsed() > Duration::from_secs(10) {
            self.prune();
        }
        true
    }
}

