                                                                                                                                                                        ng_info!(target: "p2p.sync", "event=sync_request_sent peer={} from={} req_id={:?} target_height={} trigger_block_hash={} source_peer={} created_at_ms={}", peer, from, req_id, intent.target_height, intent.trigger_block_hash.as_deref().unwrap_or("none"), intent.source_peer, intent.created_at_ms);
