                                                                        // but it no longer delays A/B/C startup or the 30s slot cadence.
                                                                        let readiness_connected_set_v284: &std::collections::HashSet<PeerId> = &simple_runtime_connected_set_v310;
                                                                        let readiness_connected_v284 = readiness_connected_set_v284.len();
