    fn append_live_tip_block_to_runtime(
        storage: &Arc<crate::storage::DbStore>,
        chain: &Arc<Mutex<Blockchain>>,
        height: u64,
    ) {
        let prev = storage
            .get_block(height.saturating_sub(1))
            .unwrap()
            .expect("previous block for live catch-up fixture must exist");

        let miner_cycle = [
            test_validator_pk_hex(0x91),
            test_validator_pk_hex(0x92),
            test_validator_pk_hex(0x93),
        ];

        let mut blk = prev.clone();
        blk.index = height;
        blk.previous_hash = prev.hash.clone();
        blk.timestamp = prev.timestamp.saturating_add(30);
        blk.transactions.clear();
        blk.state_root = prev.state_root.clone();
        blk.miner_pub_key = miner_cycle[(height as usize - 1) % miner_cycle.len()].clone();
        blk.hash = blk.calculate_hash();

        storage
            .append_block(&blk)
            .expect("live catch-up fixture block must persist");

        let mut g = chain.lock().unwrap_or_else(|e| e.into_inner());
        if g.chain.last().map(|b| b.index) < Some(height) {
            g.chain.push(blk);
        }
    }

    fn make_node_paths(name: &str) -> NodePaths {
        let root = temp_test_dir(name);
        fs::create_dir_all(&root).unwrap();
        let paths = NodePaths::from_data_dir(root);
        fs::create_dir_all(&paths.config_dir).unwrap();
        fs::create_dir_all(paths.config_dir.join("secrets")).unwrap();
        fs::create_dir_all(&paths.snapshots_dir).unwrap();
        fs::create_dir_all(&paths.logs_dir).unwrap();
        paths
    }

    async fn send_ctrl(ctrl: &tokio::sync::mpsc::UnboundedSender<P2pControl>, cmd: P2pControl) {
        ctrl.send(cmd).unwrap();
    }

    async fn graceful_shutdown(ctrl: &tokio::sync::mpsc::UnboundedSender<P2pControl>) {
        let (tx, rx) = tokio::sync::oneshot::channel();
        if ctrl.send(P2pControl::Shutdown { ack: tx }).is_ok() {
            let _ = tokio::time::timeout(Duration::from_secs(3), rx).await;
        }
    }

    async fn wait_until(timeout: Duration, mut predicate: impl FnMut() -> bool) {
        let deadline = tokio::time::Instant::now() + timeout;
        loop {
            if predicate() {
                return;
            }
            if tokio::time::Instant::now() >= deadline {
                panic!("condition not met before timeout");
            }
            tokio::time::sleep(Duration::from_millis(50)).await;
        }
    }

    #[test]
    fn cold_start_snapshot_seed_same_ip_v271_bypasses_outbound_ip24_cap_only_when_allowed() {
        let mut policy = P2PPolicy::default();
        policy.diversity_ignore_private_addrs = false;
        policy.max_outbound_conns_per_ip24 = 2;
        policy.max_total_conns_per_ip24 = 8;

        let mut diversity = PeerDiversity::new(&policy, None);
        let a1: Multiaddr = "/ip4/203.0.113.17/tcp/7001".parse().unwrap();
        let a2: Multiaddr = "/ip4/203.0.113.17/tcp/7002".parse().unwrap();
        let a3: Multiaddr = "/ip4/203.0.113.17/tcp/7003".parse().unwrap();

        assert!(diversity
            .on_connect(PeerId::random(), &a1, true, false)
            .is_ok());
        assert!(diversity
            .on_connect(PeerId::random(), &a2, true, false)
            .is_ok());
        assert!(diversity
            .on_connect(PeerId::random(), &a3, true, true)
            .is_ok());
        assert_eq!(diversity.outbound_count(), 3);
    }

    #[test]
    fn steady_state_configured_seed_v271_still_enforces_outbound_ip24_cap() {
        let mut policy = P2PPolicy::default();
        policy.diversity_ignore_private_addrs = false;
        policy.max_outbound_conns_per_ip24 = 2;
        policy.max_total_conns_per_ip24 = 8;

        let mut diversity = PeerDiversity::new(&policy, None);
        let a1: Multiaddr = "/ip4/203.0.113.17/tcp/7001".parse().unwrap();
        let a2: Multiaddr = "/ip4/203.0.113.17/tcp/7002".parse().unwrap();
        let a3: Multiaddr = "/ip4/203.0.113.17/tcp/7003".parse().unwrap();

        assert!(diversity
            .on_connect(PeerId::random(), &a1, true, false)
            .is_ok());
        assert!(diversity
            .on_connect(PeerId::random(), &a2, true, false)
            .is_ok());
        let err = diversity
            .on_connect(PeerId::random(), &a3, true, false)
            .expect_err("steady-state third same-/24 seed must keep V269 diversity enforcement");
        assert!(err.contains("ip24 cap(outbound) exceeded"));
        assert_eq!(diversity.outbound_count(), 2);
    }

    #[test]
    fn cold_start_snapshot_seed_gate_v271_is_phase_and_seed_scoped() {
        let seed: Multiaddr = "/ip4/203.0.113.17/tcp/7001".parse().unwrap();
        let other: Multiaddr = "/ip4/203.0.113.18/tcp/7009".parse().unwrap();
        let mut bootstrap_addr_keys = HashSet::new();
        bootstrap_addr_keys.insert(multiaddr_without_p2p_key(&seed));
        let bootstrap_peer_ids_configured = HashSet::new();

        assert!(allow_cold_start_snapshot_configured_seed_same_ip_v271(
            P2pBootPhase::ColdStartSnapshot,
            true,
            &seed,
            None,
            &bootstrap_peer_ids_configured,
            &bootstrap_addr_keys,
        ));
        assert!(allow_cold_start_snapshot_configured_seed_same_ip_v271(
            P2pBootPhase::RestartCatchup,
            true,
            &seed,
            None,
            &bootstrap_peer_ids_configured,
            &bootstrap_addr_keys,
        ));
        assert!(!allow_cold_start_snapshot_configured_seed_same_ip_v271(
            P2pBootPhase::SteadyState,
            true,
            &seed,
            None,
            &bootstrap_peer_ids_configured,
            &bootstrap_addr_keys,
        ));
        assert!(!allow_cold_start_snapshot_configured_seed_same_ip_v271(
            P2pBootPhase::ColdStartSnapshot,
            false,
            &seed,
            None,
            &bootstrap_peer_ids_configured,
            &bootstrap_addr_keys,
        ));
        assert!(!allow_cold_start_snapshot_configured_seed_same_ip_v271(
            P2pBootPhase::ColdStartSnapshot,
            true,
            &other,
            None,
            &bootstrap_peer_ids_configured,
            &bootstrap_addr_keys,
        ));
    }

