    #[test]
    fn hard_ban_runtime_cache_clear_removes_all_live_views() {
        let peer = PeerId::random();
        let mut hello_pending = HashSet::from([peer]);
        let mut hello_ok = HashSet::from([peer]);
        let mut hello_received = HashSet::from([peer]);
        let mut hello_sent_after_connect = HashSet::from([peer]);
        let mut peer_vsh_mismatch = HashSet::from([peer]);
        let mut peer_heights = HashMap::from([(peer, 42_u64)]);
        let mut peer_tip_hashes = HashMap::from([(peer, "aa".to_string())]);
        let mut peer_snapshot_v2 = HashMap::from([(
            peer,
            PeerSnapshotV2Advert {
                height: 42,
                meta_sha256_hex: "bb".to_string(),
                chunks: 1,
                chunk_size: 1024,
                seen_at: Instant::now(),
            },
        )]);
        let mut connected_bootstrap_peers = HashSet::from([peer]);
        let mut runtime_rr_bootstrap_ready = HashMap::from([(
            peer,
            RuntimeBootstrapSnapshotSignal {
                height: 42,
                seen_at: Instant::now(),
            },
        )]);
        let mut peer_last_seen = HashMap::from([(peer, Instant::now())]);
        let mut peer_last_addr = HashMap::from([(peer, "/ip4/127.0.0.1/tcp/7001".to_string())]);
        let mut rep_protected = HashSet::from([peer]);

        let addr = clear_hard_banned_peer_runtime_caches_v1(
            &peer,
            &mut hello_pending,
            &mut hello_ok,
            &mut hello_received,
            &mut hello_sent_after_connect,
            &mut peer_vsh_mismatch,
            &mut peer_heights,
            &mut peer_tip_hashes,
            &mut peer_snapshot_v2,
            &mut connected_bootstrap_peers,
            &mut runtime_rr_bootstrap_ready,
            &mut peer_last_seen,
            &mut peer_last_addr,
            &mut rep_protected,
        );

        assert_eq!(addr.as_deref(), Some("/ip4/127.0.0.1/tcp/7001"));
        assert!(hello_pending.is_empty());
        assert!(hello_ok.is_empty());
        assert!(hello_received.is_empty());
        assert!(hello_sent_after_connect.is_empty());
        assert!(peer_vsh_mismatch.is_empty());
        assert!(peer_heights.is_empty());
        assert!(peer_tip_hashes.is_empty());
        assert!(peer_snapshot_v2.is_empty());
        assert!(connected_bootstrap_peers.is_empty());
        assert!(runtime_rr_bootstrap_ready.is_empty());
        assert!(peer_last_seen.is_empty());
        assert!(peer_last_addr.is_empty());
        assert!(rep_protected.is_empty());
    }

