    #[test]
    fn local_sync_retry_block_updates_runtime_view_and_clears_when_height_changes() {
        let chain_arc = Arc::new(Mutex::new(Blockchain::new()));
        let mut blocker = None;
        let peer = PeerId::random();
        arm_local_sync_retry_block(
            &mut blocker,
            &chain_arc,
            1,
            Some(1),
            Some(peer),
            "local_snapshot_consensus_context_invalid:seed_mismatch:height=1 epoch=1",
            "unit_test_local_fault",
        );
        assert!(blocker.is_some());
        {
            let bc = chain_arc.lock().unwrap_or_else(|e| e.into_inner());
            let view = bc.local_consensus_runtime_view_for_next_block();
            assert!(view.sync_retry_blocked);
            assert_eq!(view.sync_retry_blocked_next_height, Some(1));
            let fault = view
                .sync_retry_blocked_fault
                .expect("sync retry fault view");
            assert_eq!(fault.scope, "seed_mismatch");
            assert_eq!(
                fault.class,
                crate::blockchain::LocalConsensusBootstrapFaultClass::SnapshotContextInvalid
            );
        }

        {
            let mut bc = chain_arc.lock().unwrap_or_else(|e| e.into_inner());
            let prev = bc.chain.last().unwrap().hash.clone();
            bc.chain.push(signed_block(1, prev, 0x66));
        }

        let active = reconcile_local_sync_retry_block(&mut blocker, &chain_arc);
        assert!(active.is_none());
        assert!(blocker.is_none());
        let bc = chain_arc.lock().unwrap_or_else(|e| e.into_inner());
        let view = bc.local_consensus_runtime_view_for_next_block();
        assert!(!view.sync_retry_blocked);
        assert!(view.sync_retry_blocked_next_height.is_none());
        assert!(view.sync_retry_blocked_fault.is_none());
    }

    #[test]
    fn arm_local_sync_retry_block_from_status_marks_runtime_view_without_peer_penalty() {
        let chain_arc = Arc::new(Mutex::new(Blockchain::new()));
        let mut blocker = None;
        let status = crate::blockchain::LocalConsensusBootstrapStatusView {
            next_height: 1,
            ready: false,
            fault: Some(crate::blockchain::LocalConsensusBootstrapFaultView {
                class:
                    crate::blockchain::LocalConsensusBootstrapFaultClass::HistoricalStateUnavailable,
                scope: "committee".to_string(),
                detail: Some("height=1 state_root=deadbeef epoch=0".to_string()),
            }),
        };

        let inserted = arm_local_sync_retry_block_from_status(
            &mut blocker,
            &chain_arc,
            &status,
            "unit_test_status",
        );
        assert!(inserted);
        let active = blocker.expect("blocker must be armed from runtime status");
        assert_eq!(active.next_height, 1);
        assert_eq!(active.sync_from, Some(1));
        assert_eq!(
            active.fault.class,
            crate::blockchain::LocalConsensusBootstrapFaultClass::HistoricalStateUnavailable
        );
        let bc = chain_arc.lock().unwrap_or_else(|e| e.into_inner());
        let view = bc.local_consensus_runtime_view_for_next_block();
        assert!(view.sync_retry_blocked);
        assert_eq!(view.sync_retry_blocked_next_height, Some(1));
        let fault = view
            .sync_retry_blocked_fault
            .expect("sync retry blocked fault must be published");
        assert_eq!(
            fault.class,
            crate::blockchain::LocalConsensusBootstrapFaultClass::HistoricalStateUnavailable
        );
        assert_eq!(fault.scope, "committee");
    }

