    #[test]
    fn dirty_low_cutoff_and_huge_gap_policy_cover_real_b_recovery_v194() {
        // Regression case observed on the live lab: B was left around height
        // 3_252 after a partial replay while A/C had a snapshot around 39_446.
        // This must remain snapshot-priority even though 3_252 is above the
        // original V191 cold-start cutoff of 1_024.
        assert!(snapshot_priority_blocks_live_block_sync_with_policy_v192(
            P2pBootPhase::RestartCatchup,
            3_252,
            39_446,
            false,
            false
        ));

        // A high local chain with a small gap can still use normal live sync.
        assert!(!snapshot_priority_blocks_live_block_sync_with_policy_v192(
            P2pBootPhase::RestartCatchup,
            35_500,
            36_000,
            false,
            false
        ));

        // A high local chain with a very large gap is snapshot-priority too,
        // unless the operator explicitly enables the unbounded escape hatch.
        assert!(snapshot_priority_blocks_live_block_sync_with_policy_v192(
            P2pBootPhase::RestartCatchup,
            20_000,
            39_446,
            true,
            false
        ));
        assert!(!snapshot_priority_blocks_live_block_sync_with_policy_v192(
            P2pBootPhase::RestartCatchup,
            20_000,
            39_446,
            true,
            true
        ));
    }

