    #[tokio::test(flavor = "current_thread")]
    async fn snapshot_priority_trigger_marks_pending_only_after_supervisor_registered_v196() {
        let _lock = test_process_lock();
        clear_state_sync_supervisor_handle_for_tests();

        let calls = Arc::new(AtomicUsize::new(0));
        let calls_action = calls.clone();
        let action: Arc<dyn crate::state_sync_supervisor::StateSyncAction> =
            Arc::new(move |reason: StateSyncReason| {
                let calls = calls_action.clone();
                async move {
                    calls.fetch_add(1, Ordering::SeqCst);
                    match reason {
                        StateSyncReason::GapStall { detail, .. } => {
                            assert!(detail.contains("snapshot_priority_required"));
                            assert!(detail.contains("local_height=3252"));
                            assert!(detail.contains("peer_height=39446"));
                        }
                        other => panic!("unexpected StateSync reason: {other:?}"),
                    }
                    Ok(())
                }
            });
        let handle = crate::state_sync_supervisor::spawn_state_sync_supervisor(
            crate::state_sync_supervisor::StateSyncSupervisorConfig {
                base_backoff_ms: 1,
                max_backoff_ms: 1,
                breaker_window_ms: 1_000,
                breaker_failures: 10,
                breaker_cooldown_ms: 100,
                trigger_queue: 8,
                auto_retry_on_failure: false,
            },
            action,
        );
        set_state_sync_supervisor_handle(handle);

        let mut tracker = CatchupProgressTracker::default();
        assert!(snapshot_priority_trigger_state_sync_recovery_v195(
            &mut tracker,
            P2pBootPhase::RestartCatchup,
            3_252,
            39_446,
            "test_dirty_low_restartcatchup_supervisor_registered",
            None,
        ));
        assert!(tracker.state_sync_pending());

        tokio::time::sleep(Duration::from_millis(20)).await;
        assert_eq!(calls.load(Ordering::SeqCst), 1);
        clear_state_sync_supervisor_handle_for_tests();
    }

