    #[test]
    fn exported_runtime_sync_caught_up_debounces_brief_false_transitions_in_steady_state() {
        let now = Instant::now();
        let mut false_candidate_since = None;

        assert!(exported_runtime_sync_caught_up(
            true,
            false,
            &mut false_candidate_since,
            now,
            Duration::from_secs(5),
            false,
        ));
        assert!(false_candidate_since.is_none());

        assert!(exported_runtime_sync_caught_up(
            false,
            true,
            &mut false_candidate_since,
            now + Duration::from_secs(1),
            Duration::from_secs(5),
            false,
        ));
        assert!(false_candidate_since.is_some());

        assert!(exported_runtime_sync_caught_up(
            false,
            true,
            &mut false_candidate_since,
            now + Duration::from_secs(4),
            Duration::from_secs(5),
            false,
        ));

        assert!(!exported_runtime_sync_caught_up(
            false,
            true,
            &mut false_candidate_since,
            now + Duration::from_secs(7),
            Duration::from_secs(5),
            false,
        ));
    }

    #[test]
    fn exported_runtime_sync_caught_up_forces_false_outside_steady_state() {
        let now = Instant::now();
        let mut false_candidate_since = None;

        assert!(!exported_runtime_sync_caught_up(
            false,
            true,
            &mut false_candidate_since,
            now,
            Duration::from_secs(5),
            true,
        ));
        assert!(false_candidate_since.is_some());
    }

