    #[test]
    fn runtime_snapshot_serve_session_v221_pins_bundle_after_meta() {
        let root = temp_test_dir("runtime_snapshot_serve_session_v221_pin");
        let _ = fs::remove_dir_all(&root);
        fs::create_dir_all(&root).unwrap();
        let paths = NodePaths::from_data_dir(&root);
        let source_dir = root.join("source_snapshot");
        fs::create_dir_all(source_dir.join("chunks")).unwrap();

        // This test is about V221 serve-session pinning, not validator bootstrap
        // admission. Keep the fixture as a minimal read-only transport manifest so
        // unrelated validator-bootstrap/finality guards cannot mask the pinning
        // invariant being tested here.
        let mut meta = sample_meta();
        meta.height = 50_459;
        meta.window_to_height = meta.height;
        meta.economy_snapshot_height = Some(meta.height);
        meta.chunks = 2;
        // Keep the test bundle transport-servable under the RRv3 metadata/chunk
        // guard. The fixture chunks are intentionally tiny, but the advertised
        // chunk_size must still be a realistic network chunk budget.
        meta.chunk_size = 16 * 1024;
        meta.bytes_len = 8;
        meta.chunk_hashes_hex = vec![
            format!("{:x}", Sha256::digest(b"aaaa")),
            format!("{:x}", Sha256::digest(b"bbbb")),
        ];
        fs::write(
            source_dir.join("meta.json"),
            serde_json::to_vec_pretty(&meta).unwrap(),
        )
        .unwrap();
        fs::write(source_dir.join("chunks").join("000000.bin"), b"aaaa").unwrap();
        fs::write(source_dir.join("chunks").join("000001.bin"), b"bbbb").unwrap();

        let (transport_meta, sha, _encoded) =
            read_snapshot_v2_meta_for_transport_advertise(&source_dir, 262_144)
                .unwrap()
                .unwrap();

        let peer = PeerId::random();
        let sessions: Arc<Mutex<HashMap<(PeerId, u64), RuntimeSnapshotServeSessionV221>>> =
            Arc::new(Mutex::new(HashMap::new()));
        let pinned_dir = runtime_snapshot_open_serve_session_v221(
            &sessions,
            &paths,
            peer,
            &source_dir,
            &transport_meta,
            &sha,
            262_144,
        )
        .unwrap();
        assert_ne!(pinned_dir, source_dir);
        assert!(pinned_dir.join("chunks").join("000001.bin").is_file());

        fs::remove_dir_all(&source_dir).unwrap();
        let session = runtime_snapshot_get_serve_session_v221(
            &sessions,
            peer,
            transport_meta.height,
            Instant::now(),
        )
        .expect("session should still be valid after source alias is removed");
        assert_eq!(session.dir, pinned_dir);
        assert_eq!(session.meta_sha256_hex, sha);
        assert_eq!(session.chunks, 2);

        let (chunk_response, strike) = runtime_snapshot_encode_chunk_response_v221(
            &session.dir,
            transport_meta.height,
            1,
            262_144,
            peer,
            true,
            session.chunk_hashes_hex.get(1).map(|s| s.as_str()),
        );
        assert!(strike.is_none());
        match decode_rr_v3(&chunk_response).unwrap() {
            RrV3Msg::SnapshotV2Chunk {
                height,
                chunk_index,
                data_b64,
            } => {
                assert_eq!(height, transport_meta.height);
                assert_eq!(chunk_index, 1);
                assert_eq!(STANDARD.decode(data_b64).unwrap(), b"bbbb");
            }
            other => panic!("unexpected response: {:?}", other),
        }

        runtime_snapshot_serve_sessions_clear_v221(&sessions, true);
        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn runtime_snapshot_serve_session_v221_wrong_height_or_expired_is_absent() {
        let peer = PeerId::random();
        let now = Instant::now();
        let dir = std::path::PathBuf::from("dummy");
        let sessions: Arc<Mutex<HashMap<(PeerId, u64), RuntimeSnapshotServeSessionV221>>> =
            Arc::new(Mutex::new(HashMap::new()));
        {
            let mut guard = sessions.lock().unwrap();
            guard.insert(
                (peer, 50_459),
                RuntimeSnapshotServeSessionV221 {
                    dir,
                    meta_sha256_hex: "aa".repeat(32),
                    height: 50_459,
                    chunks: 2,
                    chunk_hashes_hex: vec!["aa".repeat(32), "bb".repeat(32)],
                    expires_at: now + Duration::from_secs(60),
                    last_progress_at: now,
                    last_chunk_served: None,
                    bytes_served: 0,
                    consecutive_failures: 0,
                    last_successful_chunk: None,

                    last_attempt_started_chunk: None,
                    last_encoded_chunk: None,
                    last_response_sent_chunk: None,
                    last_acknowledged_chunk: None,
                    last_attempt_started_at: None,
                    last_encoded_at: None,
                    last_sent_at: None,
                    last_acknowledged_at: None,
                    bytes_encoded: 0,
                    bytes_sent: 0,
                    state: RuntimeSnapshotServeSessionStateV233::Open,
                },
            );
        }

        assert!(runtime_snapshot_get_serve_session_v221(&sessions, peer, 50_459, now).is_some());
        assert!(runtime_snapshot_get_serve_session_v221(&sessions, peer, 50_460, now).is_none());
        assert!(runtime_snapshot_get_serve_session_v221(
            &sessions,
            peer,
            50_459,
            now + Duration::from_secs(61)
        )
        .is_none());
    }

    #[test]
    fn runtime_snapshot_active_serve_peers_v223_tracks_only_unexpired_snapshot_clients() {
        let sessions: Arc<Mutex<HashMap<(PeerId, u64), RuntimeSnapshotServeSessionV221>>> =
            Arc::new(Mutex::new(HashMap::new()));
        let active_peer = PeerId::random();
        let expired_peer = PeerId::random();
        let now = Instant::now();
        {
            let mut guard = sessions.lock().unwrap();
            guard.insert(
                (active_peer, 50_459),
                RuntimeSnapshotServeSessionV221 {
                    dir: std::path::PathBuf::from("/tmp/active"),
                    meta_sha256_hex: "active".to_string(),
                    height: 50_459,
                    chunks: 3,
                    chunk_hashes_hex: vec!["a".to_string(), "b".to_string(), "c".to_string()],
                    expires_at: now + Duration::from_secs(60),
                    last_progress_at: now,
                    last_chunk_served: None,
                    bytes_served: 0,
                    consecutive_failures: 0,
                    last_successful_chunk: None,

                    last_attempt_started_chunk: None,
                    last_encoded_chunk: None,
                    last_response_sent_chunk: None,
                    last_acknowledged_chunk: None,
                    last_attempt_started_at: None,
                    last_encoded_at: None,
                    last_sent_at: None,
                    last_acknowledged_at: None,
                    bytes_encoded: 0,
                    bytes_sent: 0,
                    state: RuntimeSnapshotServeSessionStateV233::Open,
                },
            );
            guard.insert(
                (expired_peer, 50_459),
                RuntimeSnapshotServeSessionV221 {
                    dir: std::path::PathBuf::from("/tmp/expired"),
                    meta_sha256_hex: "expired".to_string(),
                    height: 50_459,
                    chunks: 3,
                    chunk_hashes_hex: vec!["a".to_string(), "b".to_string(), "c".to_string()],
                    expires_at: now - Duration::from_secs(1),
                    last_progress_at: now - Duration::from_secs(1),
                    last_chunk_served: None,
                    bytes_served: 0,
                    consecutive_failures: 0,
                    last_successful_chunk: None,

                    last_attempt_started_chunk: None,
                    last_encoded_chunk: None,
                    last_response_sent_chunk: None,
                    last_acknowledged_chunk: None,
                    last_attempt_started_at: None,
                    last_encoded_at: None,
                    last_sent_at: None,
                    last_acknowledged_at: None,
                    bytes_encoded: 0,
                    bytes_sent: 0,
                    state: RuntimeSnapshotServeSessionStateV233::Open,
                },
            );
        }

        let active = runtime_snapshot_active_serve_peers_v223(&sessions, now);
        assert!(active.contains(&active_peer));
        assert!(!active.contains(&expired_peer));
        assert_eq!(active.len(), 1);
    }

