    #[test]
    fn deferred_block_cache_keeps_entries_until_terminal_resolution() {
        let mut cache = DeferredBlockCache::new();
        let peer = PeerId::random();
        let blk = Block::new(1, 1, "prev".to_string(), vec![]);
        let hash = blk.hash.clone();
        cache.upsert(blk, peer, DeferredReason::AheadOfLocalTip, Some(10));
        assert!(cache.contains(&hash));
        assert!(cache.ready_hashes(5, 8).is_empty());
        assert_eq!(cache.ready_hashes(10, 8), vec![hash.clone()]);
        cache.note_retry(&hash, DeferredReason::SyncInProgress, Some(11));
        let entry = cache.get_cloned(&hash).unwrap();
        assert_eq!(entry.class, DeferredBlockClass::LinearExtension);
        assert_eq!(entry.reason, DeferredReason::SyncInProgress);
        assert_eq!(entry.retry_after_height, Some(11));
        assert_eq!(entry.retries, 1);
        cache.remove(&hash);
        assert!(!cache.contains(&hash));
    }

    #[test]
    fn new_block_ahead_of_tip_is_deferred_without_terminal_dedup() {
        let mut seen = SeenCache::new();
        let mut cache = DeferredBlockCache::new();
        let peer = PeerId::random();
        let block = signed_block(105, "tip-104".to_string(), 7);

        assert!(seen.insert_block_wire(&block.hash));
        let plan = plan_new_block_deferral(&block, 100, Some("tip-100"), true, false).unwrap();
        assert_eq!(plan.disposition, InboundBlockDisposition::DeferredForSync);
        assert_eq!(plan.class, DeferredBlockClass::LinearExtension);
        register_deferred_block(
            &mut cache,
            &block,
            peer,
            100,
            plan,
            P2pBootPhase::SteadyState,
            false,
            plan.sync_target_height,
        );

        let entry = cache.get_cloned(&block.hash).unwrap();
        assert_eq!(entry.class, DeferredBlockClass::LinearExtension);
        assert_eq!(entry.reason, DeferredReason::AheadOfLocalTip);
        assert!(!seen.contains_block_terminal(&block.hash));
    }

