    #[test]
    fn requeue_runtime_bootstrap_targets_dedups_addr_only_and_skips_connected_peer_ids() {
        let connected_pid = PeerId::random();
        let queued_pid = PeerId::random();
        let connected_ma: Multiaddr = format!("/ip4/127.0.0.1/tcp/9001/p2p/{}", connected_pid)
            .parse()
            .unwrap();
        let queued_ma: Multiaddr = format!("/ip4/127.0.0.1/tcp/9002/p2p/{}", queued_pid)
            .parse()
            .unwrap();
        let addr_only: Multiaddr = "/ip4/127.0.0.1/tcp/9003".parse().unwrap();

        let bootstrap_peers = vec![
            connected_ma.to_string(),
            queued_ma.to_string(),
            addr_only.to_string(),
            addr_only.to_string(),
        ];
        let mut bootstrap_queue = VecDeque::new();
        let mut queued_keys: HashSet<String> = HashSet::new();
        let mut dial_candidates = DialCandidates::new(60);
        let mut connected_now = HashSet::new();
        connected_now.insert(connected_pid);

        let added = requeue_runtime_bootstrap_targets(
            &bootstrap_peers,
            &mut bootstrap_queue,
            &mut queued_keys,
            &mut dial_candidates,
            &connected_now,
        );

        assert_eq!(added, 2);
        assert_eq!(bootstrap_queue.len(), 1);
        assert_eq!(queued_keys.len(), 1);
        assert!(dial_candidates.m.contains_key(&queued_pid));
        assert!(!dial_candidates.m.contains_key(&connected_pid));
    }

    #[test]
    fn full_pulse_is_due_initially_and_progress_changes_emit_immediately() {
        let base = LocalPulseFullState {
            height: 10,
            tip_hash: Some("tip-a".to_string()),
            finalized_height: 1,
            finalized_hash: "00".repeat(32),
            genesis_hash: "genesis".to_string(),
            validator_set_hash: "vsh-1".to_string(),
            validator_pubkey: Some("pk".to_string()),
            runtime_sync_caught_up: true,
            runtime_bootstrap_complete: true,
            p2p_ready_for_mining: true,
        };
        assert!(should_send_full_pulse(None, None, &base));

        let progressed = LocalPulseFullState {
            height: 11,
            tip_hash: Some("tip-b".to_string()),
            ..base.clone()
        };
        assert!(should_send_full_pulse(
            Some(Instant::now()),
            Some(&base),
            &progressed
        ));
        assert!(should_send_full_pulse(
            Some(Instant::now() - Duration::from_secs(FULL_PULSE_PERIOD_SECS)),
            Some(&base),
            &progressed
        ));
    }

