    #[test]
    fn forced_sync_peer_prefers_bootstrap_then_hello_then_any() {
        let bootstrap_pid = libp2p::identity::Keypair::generate_ed25519()
            .public()
            .to_peer_id();
        let hello_pid = libp2p::identity::Keypair::generate_ed25519()
            .public()
            .to_peer_id();
        let any_pid = libp2p::identity::Keypair::generate_ed25519()
            .public()
            .to_peer_id();

        let connected: HashSet<PeerId> = [bootstrap_pid, hello_pid, any_pid].into_iter().collect();
        let connected_bootstrap: HashSet<PeerId> = [bootstrap_pid].into_iter().collect();
        let hello_ok: HashSet<PeerId> = [hello_pid].into_iter().collect();
        let cooldowns: HashMap<PeerId, Instant> = HashMap::new();
        let now = Instant::now();

        assert_eq!(
            select_forced_sync_peer(&connected, &connected_bootstrap, &hello_ok, &cooldowns, now),
            Some(bootstrap_pid)
        );
        assert_eq!(
            select_forced_sync_peer(&connected, &HashSet::new(), &hello_ok, &cooldowns, now),
            Some(hello_pid)
        );
        assert!(select_forced_sync_peer(
            &connected,
            &HashSet::new(),
            &HashSet::new(),
            &cooldowns,
            now
        )
        .is_some());

        let mut cooldowns = HashMap::new();
        cooldowns.insert(bootstrap_pid, now + Duration::from_secs(5));
        assert_eq!(
            select_forced_sync_peer(&connected, &connected_bootstrap, &hello_ok, &cooldowns, now),
            Some(hello_pid)
        );
    }

    #[test]
    fn runtime_sync_convergence_is_independent_from_tip_gate_and_outbox_transients() {
        let converged = runtime_sync_converged(3, true, true, 2, 3, false, false, true);
        assert!(converged);

        assert!(!runtime_mining_ready(
            3, true, true, 1, converged, true, true
        ));
        assert!(!runtime_mining_ready(
            3, true, true, 1, converged, false, false
        ));
        assert!(runtime_mining_ready(
            3, true, true, 1, converged, false, true
        ));
    }

    #[test]
