    #[test]
    fn quorum_reformation_scope_v283_uses_signed_candidate_before_lifecycle_operational() {
        let _guard = EnvGuard::capture(&["NEWGEN_PEER_LIFECYCLE_OPERATIONAL_STREAK_TICKS"]);
        std::env::remove_var("NEWGEN_PEER_LIFECYCLE_OPERATIONAL_STREAK_TICKS");

        let peer = PeerId::random();
        let mut connected_raw = HashSet::new();
        connected_raw.insert(peer);
        let recovery = HashSet::new();
        let mut hello_ok = HashSet::new();
        hello_ok.insert(peer);
        let mut peer_heights = HashMap::new();
        peer_heights.insert(peer, 100);
        let expected_validator_set_hash = "validator-set-v283";
        let now = Instant::now();
        let mut runtime_candidates = HashMap::new();
        runtime_candidates.insert(
            peer,
            PeerRuntimeOperationalCandidateV236 {
                height: 100,
                validator_set_hash: expected_validator_set_hash.to_string(),
                finalized_height: 99,
                finalized_hash: "f".repeat(64),
                observed_at: now,
            },
        );

        let reformation = runtime_quorum_reformation_peer_scope_v283(
            P2pBootPhase::SteadyState,
            &connected_raw,
            &recovery,
            &hello_ok,
            &peer_heights,
            &runtime_candidates,
            expected_validator_set_hash,
            true,
            now,
        );
        assert_eq!(reformation.len(), 1);
        assert!(reformation.contains(&peer));

        let mut lifecycle_registry = HashMap::new();
        let operational = runtime_operational_peer_scope_v236(
            P2pBootPhase::SteadyState,
            &connected_raw,
            &recovery,
            &hello_ok,
            &peer_heights,
            &runtime_candidates,
            &mut lifecycle_registry,
            expected_validator_set_hash,
            true,
            now,
        );
        assert!(
            operational.is_empty(),
            "first valid tick is only OperationalCandidate"
        );
    }

