    #[test]
    fn quorum_reformation_diagnostics_v284_counts_candidate_rejection_reasons() {
        let peer_ok = PeerId::random();
        let peer_height_mismatch = PeerId::random();
        let peer_wrong_vsh = PeerId::random();
        let peer_stale = PeerId::random();
        let peer_missing_finalized = PeerId::random();
        let peer_missing_candidate = PeerId::random();
        let mut connected_raw = HashSet::new();
        let mut hello_ok = HashSet::new();
        let mut peer_heights = HashMap::new();
        for (peer, height) in [
            (peer_ok, 100),
            (peer_height_mismatch, 100),
            (peer_wrong_vsh, 100),
            (peer_stale, 100),
            (peer_missing_finalized, 100),
            (peer_missing_candidate, 100),
        ] {
            connected_raw.insert(peer);
            hello_ok.insert(peer);
            peer_heights.insert(peer, height);
        }
        let recovery = HashSet::new();
        let now = Instant::now();
        let expected = "validator-set-v284";
        let mut runtime_candidates = HashMap::new();
        runtime_candidates.insert(
            peer_ok,
            PeerRuntimeOperationalCandidateV236 {
                height: 100,
                validator_set_hash: expected.to_string(),
                finalized_height: 99,
                finalized_hash: "f".repeat(64),
                observed_at: now,
            },
        );
        runtime_candidates.insert(
            peer_height_mismatch,
            PeerRuntimeOperationalCandidateV236 {
                height: 99,
                validator_set_hash: expected.to_string(),
                finalized_height: 99,
                finalized_hash: "f".repeat(64),
                observed_at: now,
            },
        );
        runtime_candidates.insert(
            peer_wrong_vsh,
            PeerRuntimeOperationalCandidateV236 {
                height: 100,
                validator_set_hash: "wrong".to_string(),
                finalized_height: 99,
                finalized_hash: "f".repeat(64),
                observed_at: now,
            },
        );
        runtime_candidates.insert(
            peer_stale,
            PeerRuntimeOperationalCandidateV236 {
                height: 100,
                validator_set_hash: expected.to_string(),
                finalized_height: 99,
                finalized_hash: "f".repeat(64),
                observed_at: now
                    - runtime_peer_lifecycle_candidate_ttl_v236()
                    - Duration::from_secs(1),
            },
        );
        runtime_candidates.insert(
            peer_missing_finalized,
            PeerRuntimeOperationalCandidateV236 {
                height: 100,
                validator_set_hash: expected.to_string(),
                finalized_height: 0,
                finalized_hash: String::new(),
                observed_at: now,
            },
        );

        let diag = runtime_quorum_reformation_diagnostics_v284(
            P2pBootPhase::SteadyState,
            &connected_raw,
            &recovery,
            &hello_ok,
            &peer_heights,
            &runtime_candidates,
            expected,
            true,
            now,
        );
        assert_eq!(diag.runtime_candidates_count, 5);
        assert_eq!(diag.candidate_missing_count, 1);
        assert_eq!(diag.candidate_height_mismatch_count, 1);
        assert_eq!(diag.candidate_validator_set_mismatch_count, 1);
        assert_eq!(diag.candidate_stale_count, 1);
        assert_eq!(diag.candidate_missing_finalized_count, 1);
    }

