    #[test]
    fn operational_heartbeat_outbox_v294_is_dropped_during_cold_snapshot_only() {
        let now = Instant::now();
        let mut outbox = VecDeque::new();
        let mut outbox_bytes = 0usize;

        for (kind, topic, bytes) in [
            ("Hello", TopicKind::Heartbeat, vec![1, 2, 3]),
            ("Pulse", TopicKind::Heartbeat, vec![4, 5]),
            ("PulseLight", TopicKind::Heartbeat, vec![6]),
            ("NewBlock", TopicKind::Blocks, vec![7, 8, 9, 10]),
            ("NewTx", TopicKind::Tx, vec![11]),
            ("Announce", TopicKind::Heartbeat, vec![12, 13]),
            ("Ping", TopicKind::Heartbeat, vec![14]),
        ] {
            outbox_bytes = outbox_bytes.saturating_add(bytes.len());
            outbox.push_back(OutboxItem {
                kind,
                topic,
                bytes,
                attempts: 0,
                last_attempt: now,
                critical: matches!(kind, "Hello"),
            });
        }

        let dropped = suppress_operational_heartbeat_outbox_v294(
            &mut outbox,
            &mut outbox_bytes,
            P2pBootPhase::ColdStartSnapshot,
        );

        assert_eq!(dropped, 5);
        assert_eq!(outbox.len(), 2);
        assert!(outbox.iter().all(|item| item.topic != TopicKind::Heartbeat));
        assert!(outbox.iter().any(|item| item.kind == "NewBlock"));
        assert!(outbox.iter().any(|item| item.kind == "NewTx"));
        assert_eq!(
            outbox_bytes,
            outbox.iter().map(|item| item.bytes.len()).sum::<usize>()
        );
    }

