    #[test]
    fn runtime_snapshot_chunk_attempt_deadline_v231_is_per_retry_not_global() {
        let _lock = test_process_lock();
        let _env = EnvGuard::capture(&[
            "NEWGEN_RUNTIME_SNAPSHOT_CHUNK_ATTEMPT_TIMEOUT_MS",
            "NEWGEN_RUNTIME_SNAPSHOT_CHUNK_RETRIES",
            "NEWGEN_RUNTIME_SNAPSHOT_CHUNK_RETRY_FLOOR",
        ]);
        std::env::remove_var("NEWGEN_RUNTIME_SNAPSHOT_CHUNK_ATTEMPT_TIMEOUT_MS");
        std::env::remove_var("NEWGEN_RUNTIME_SNAPSHOT_CHUNK_RETRIES");
        std::env::remove_var("NEWGEN_RUNTIME_SNAPSHOT_CHUNK_RETRY_FLOOR");

        let start = Instant::now();
        let first = runtime_snapshot_chunk_retry_deadline_v231(start, 1_000);
        let retry =
            runtime_snapshot_chunk_retry_deadline_v231(start + Duration::from_secs(10), 1_000);
        assert!(first >= start + Duration::from_secs(5));
        assert!(retry >= start + Duration::from_secs(15));
        assert_eq!(runtime_snapshot_chunk_retries_v231(), 2);

        std::env::set_var("NEWGEN_RUNTIME_SNAPSHOT_CHUNK_RETRY_FLOOR", "1");
        assert_eq!(runtime_snapshot_chunk_retries_v231(), 1);

        std::env::set_var("NEWGEN_RUNTIME_SNAPSHOT_CHUNK_RETRIES", "5");
        assert_eq!(runtime_snapshot_chunk_retries_v231(), 5);

        std::env::set_var("NEWGEN_RUNTIME_SNAPSHOT_CHUNK_RETRIES", "99");
        assert_eq!(runtime_snapshot_chunk_retries_v231(), 16);
    }

