    #[test]
    fn recovery_non_operational_scope_v231_includes_snapshot_pending_and_retry_peers() {
        let active = PeerId::random();
        let pending_peer = PeerId::random();
        let retry_peer = PeerId::random();
        let mut active_set = HashSet::new();
        active_set.insert(active);

        let rid_pending = unsafe {
            std::mem::MaybeUninit::<request_response::OutboundRequestId>::zeroed().assume_init()
        };
        let rid_retry = unsafe {
            std::mem::MaybeUninit::<request_response::OutboundRequestId>::zeroed().assume_init()
        };

        let mut pending = HashMap::new();
        pending.insert(
            rid_pending,
            PendingRuntimeSnapshotChunk {
                peer: pending_peer,
                request_id: rid_pending,
                height: 42,
                chunk_index: 0,
                deadline: Instant::now(),
                attempt_timeout_ms: 30_000,
                retries_left: 3,
                response: oneshot::channel().0,
            },
        );

        let mut retry = VecDeque::new();
        retry.push_back(RuntimeSnapshotRetryV220::Chunk {
            due_at: Instant::now(),
            pending: PendingRuntimeSnapshotChunk {
                peer: retry_peer,
                request_id: rid_retry,
                height: 42,
                chunk_index: 1,
                deadline: Instant::now(),
                attempt_timeout_ms: 30_000,
                retries_left: 2,
                response: oneshot::channel().0,
            },
        });

        let scoped = runtime_recovery_non_operational_peers_v231(&active_set, &pending, &retry);
        assert!(scoped.contains(&active));
        assert!(scoped.contains(&pending_peer));
        assert!(scoped.contains(&retry_peer));
    }

