    #[test]
    fn exported_p2p_ready_drops_false_after_persistent_observable_fault() {
        let debounce = Duration::from_secs(3);
        let start = Instant::now();
        let mut false_since = None;

        assert!(exported_p2p_ready_for_mining(
            true,
            false,
            &mut false_since,
            start,
            debounce,
            false,
        ));

        let persistent_fault_candidate =
            observable_p2p_ready_candidate(true, 3, true, true, 2, true, true, true);
        assert!(!persistent_fault_candidate);

        // The export debounce starts at the first observed false candidate.
        // A newly observed persistent fault must keep the previous exported=true
        // state until the debounce interval has fully elapsed.
        assert!(exported_p2p_ready_for_mining(
            persistent_fault_candidate,
            true,
            &mut false_since,
            start + Duration::from_secs(1),
            debounce,
            false,
        ));
        assert_eq!(false_since, Some(start + Duration::from_secs(1)));
        assert!(!exported_p2p_ready_for_mining(
            persistent_fault_candidate,
            true,
            &mut false_since,
            start + Duration::from_secs(4),
            debounce,
            false,
        ));
    }

