    #[test]
    fn restart_catchup_admission_scope_v226_uses_live_peers_without_opening_mining_gate() {
        let a = PeerId::random();
        let b = PeerId::random();
        let c = PeerId::random();
        let raw_connected = HashSet::from([a, b, c]);
        let recovery_peers: HashSet<PeerId> = HashSet::new();
        let hello_ok = HashSet::from([a, b, c]);
        let peer_heights = HashMap::from([(a, 50_000_u64), (b, 50_000_u64), (c, 50_000_u64)]);

        let admission = runtime_admission_peer_scope_v226(
            &raw_connected,
            &recovery_peers,
            &hello_ok,
            &peer_heights,
            true,
        );
        let operational = runtime_operational_peer_scope_v223(
            P2pBootPhase::RestartCatchup,
            &raw_connected,
            &recovery_peers,
            &hello_ok,
            &peer_heights,
            true,
        );

        assert_eq!(admission.len(), 3);
        assert!(admission.contains(&a));
        assert!(admission.contains(&b));
        assert!(admission.contains(&c));
        assert!(operational.is_empty());

        let first_ready = runtime_boot_phase_step(RuntimeBootPhaseStep {
            phase: P2pBootPhase::RestartCatchup,
            connected: admission.len(),
            multi_validator: true,
            require_hello_ok_for_runtime: true,
            hello_ok_count: admission.iter().filter(|p| hello_ok.contains(*p)).count(),
            peer_heights_count: admission.len(),
            syncing: false,
            mine_behind: false,
            catchup_ok: true,
            fork_ok: true,
            fresh_view_effective_ok: true,
            consensus_context_ready: true,
            ready_streak: 0,
        });
        assert_eq!(first_ready.next_phase, P2pBootPhase::RestartCatchup);
        assert_eq!(first_ready.next_ready_streak, 1);
        assert!(!first_ready.reached_steady_state);

        let second_ready = runtime_boot_phase_step(RuntimeBootPhaseStep {
            phase: P2pBootPhase::RestartCatchup,
            connected: admission.len(),
            multi_validator: true,
            require_hello_ok_for_runtime: true,
            hello_ok_count: admission.iter().filter(|p| hello_ok.contains(*p)).count(),
            peer_heights_count: admission.len(),
            syncing: false,
            mine_behind: false,
            catchup_ok: true,
            fork_ok: true,
            fresh_view_effective_ok: true,
            consensus_context_ready: true,
            ready_streak: first_ready.next_ready_streak,
        });
        assert_eq!(second_ready.next_phase, P2pBootPhase::SteadyState);
        assert!(second_ready.reached_steady_state);
    }

