    #[test]
    fn non_operational_recovery_peer_height_does_not_poison_mining_or_runtime_horizon_v227() {
        let a = PeerId::random();
        let b = PeerId::random();
        let c = PeerId::random();
        let d_recovery = PeerId::random();
        let local_next = 50_001_u64;

        let raw_connected = HashSet::from([a, b, c, d_recovery]);
        let recovery_peers = HashSet::from([d_recovery]);
        let hello_ok = HashSet::from([a, b, c, d_recovery]);
        let peer_heights = HashMap::from([
            (a, local_next),
            (b, local_next),
            (c, local_next),
            (d_recovery, 60_000_u64),
        ]);

        let admission = runtime_admission_peer_scope_v226(
            &raw_connected,
            &recovery_peers,
            &hello_ok,
            &peer_heights,
            true,
        );
        let operational = runtime_operational_peer_scope_v223(
            P2pBootPhase::SteadyState,
            &raw_connected,
            &recovery_peers,
            &hello_ok,
            &peer_heights,
            true,
        );
        let admission_heights: Vec<u64> = peer_heights
            .iter()
            .filter(|(p, _)| admission.contains(*p))
            .map(|(_, h)| *h)
            .collect();
        let operational_heights: Vec<u64> = peer_heights
            .iter()
            .filter(|(p, _)| operational.contains(*p))
            .map(|(_, h)| *h)
            .collect();

        assert_eq!(peer_heights.values().copied().max().unwrap(), 60_000);
        assert_eq!(
            runtime_scope_max_known_height_v227(&admission_heights, local_next),
            local_next
        );
        assert_eq!(
            runtime_scope_max_known_height_v227(&operational_heights, local_next),
            local_next
        );
        assert!(!admission.contains(&d_recovery));
        assert!(!operational.contains(&d_recovery));
    }

    #[test]
    fn restart_catchup_admission_height_uses_admission_peers_not_global_peer_height_v227() {
        let a = PeerId::random();
        let b = PeerId::random();
        let c = PeerId::random();
        let d_recovery = PeerId::random();
        let local_next = 50_001_u64;

        let raw_connected = HashSet::from([a, b, c, d_recovery]);
        let recovery_peers = HashSet::from([d_recovery]);
        let hello_ok = HashSet::from([a, b, c, d_recovery]);
        let peer_heights = HashMap::from([
            (a, local_next),
            (b, local_next),
            (c, local_next),
            (d_recovery, 60_000_u64),
        ]);

        let admission = runtime_admission_peer_scope_v226(
            &raw_connected,
            &recovery_peers,
            &hello_ok,
            &peer_heights,
            true,
        );
        let operational = runtime_operational_peer_scope_v223(
            P2pBootPhase::RestartCatchup,
            &raw_connected,
            &recovery_peers,
            &hello_ok,
            &peer_heights,
            true,
        );
        let admission_heights: Vec<u64> = peer_heights
            .iter()
            .filter(|(p, _)| admission.contains(*p))
            .map(|(_, h)| *h)
            .collect();
        let admission_max_known =
            runtime_scope_max_known_height_v227(&admission_heights, local_next);
        let runtime_mine_behind = admission_max_known > local_next;

        assert_eq!(peer_heights.values().copied().max().unwrap(), 60_000);
        assert_eq!(admission.len(), 3);
        assert!(operational.is_empty());
        assert_eq!(admission_max_known, local_next);
        assert!(!runtime_mine_behind);

        let first_ready = runtime_boot_phase_step(RuntimeBootPhaseStep {
            phase: P2pBootPhase::RestartCatchup,
            connected: admission.len(),
            multi_validator: true,
            require_hello_ok_for_runtime: true,
            hello_ok_count: admission.iter().filter(|p| hello_ok.contains(*p)).count(),
            peer_heights_count: admission.len(),
            syncing: runtime_mine_behind,
            mine_behind: runtime_mine_behind,
            catchup_ok: true,
            fork_ok: true,
            fresh_view_effective_ok: true,
            consensus_context_ready: true,
            ready_streak: 0,
        });
        assert_eq!(first_ready.next_ready_streak, 1);
        assert_eq!(first_ready.next_phase, P2pBootPhase::RestartCatchup);
    }

