    #[test]
    fn abc_operational_scope_v223_excludes_d_recovery_peer_while_preserving_validator_peers() {
        let a = PeerId::random();
        let b = PeerId::random();
        let c = PeerId::random();
        let d_recovery = PeerId::random();
        let raw_connected = HashSet::from([a, b, c, d_recovery]);
        let recovery_peers = HashSet::from([d_recovery]);
        let hello_ok = HashSet::from([a, b, c, d_recovery]);
        let peer_heights = HashMap::from([
            (a, 50_000_u64),
            (b, 50_000_u64),
            (c, 50_000_u64),
            (d_recovery, 50_000_u64),
        ]);

        let operational = runtime_operational_peer_scope_v223(
            P2pBootPhase::SteadyState,
            &raw_connected,
            &recovery_peers,
            &hello_ok,
            &peer_heights,
            true,
        );

        // V238: the legacy V223 helper is fail-closed. A/B/C become
        // operational only through the persistent lifecycle registry.
        assert!(operational.is_empty());
        assert!(!operational.contains(&a));
        assert!(!operational.contains(&b));
        assert!(!operational.contains(&c));
        assert!(!operational.contains(&d_recovery));
    }

