    #[test]
    fn runtime_boot_phase_step_models_restart_catchup_to_steady_state_over_realistic_ticks() {
        let cold_start = runtime_bootstrap_ready_with_lag(
            P2pBootPhase::ColdStartSnapshot,
            &HashSet::from([PeerId::random()]),
            &HashSet::from([PeerId::random()]),
            &HashMap::new(),
            &HashMap::new(),
            &HashMap::new(),
            None,
            0,
        );
        assert!(!cold_start);

        let mut phase = P2pBootPhase::RestartCatchup;
        let mut streak: u8 = 0;

        let hold = runtime_boot_phase_step(RuntimeBootPhaseStep {
            phase,
            connected: 2,
            multi_validator: true,
            require_hello_ok_for_runtime: true,
            hello_ok_count: 1,
            peer_heights_count: 2,
            syncing: false,
            mine_behind: false,
            catchup_ok: true,
            fork_ok: true,
            fresh_view_effective_ok: true,
            consensus_context_ready: false,
            ready_streak: streak,
        });
        assert!(hold.runtime_sync_converged);
        assert!(!hold.transition_ready_candidate);
        assert_eq!(hold.next_phase, P2pBootPhase::RestartCatchup);
        assert_eq!(hold.next_ready_streak, 0);
        phase = hold.next_phase;
        streak = hold.next_ready_streak;

        let first_ready = runtime_boot_phase_step(RuntimeBootPhaseStep {
            phase,
            connected: 2,
            multi_validator: true,
            require_hello_ok_for_runtime: true,
            hello_ok_count: 1,
            peer_heights_count: 2,
            syncing: false,
            mine_behind: false,
            catchup_ok: true,
            fork_ok: true,
            fresh_view_effective_ok: true,
            consensus_context_ready: true,
            ready_streak: streak,
        });
        assert!(first_ready.runtime_sync_converged);
        assert!(first_ready.transition_ready_candidate);
        assert_eq!(first_ready.next_phase, P2pBootPhase::RestartCatchup);
        assert_eq!(first_ready.next_ready_streak, 1);
        phase = first_ready.next_phase;
        streak = first_ready.next_ready_streak;

        let second_ready = runtime_boot_phase_step(RuntimeBootPhaseStep {
            phase,
            connected: 2,
            multi_validator: true,
            require_hello_ok_for_runtime: true,
            hello_ok_count: 1,
            peer_heights_count: 2,
            syncing: false,
            mine_behind: false,
            catchup_ok: true,
            fork_ok: true,
            fresh_view_effective_ok: true,
            consensus_context_ready: true,
            ready_streak: streak,
        });
        assert!(second_ready.runtime_sync_converged);
        assert!(second_ready.transition_ready_candidate);
        assert!(second_ready.reached_steady_state);
        assert_eq!(second_ready.next_phase, P2pBootPhase::SteadyState);
        assert_eq!(second_ready.next_ready_streak, 0);
    }

    #[test]
    fn runtime_boot_phase_step_resets_streak_on_runtime_or_consensus_regression() {
        let unstable_runtime = runtime_boot_phase_step(RuntimeBootPhaseStep {
            phase: P2pBootPhase::RestartCatchup,
            connected: 2,
            multi_validator: true,
            require_hello_ok_for_runtime: true,
            hello_ok_count: 0,
            peer_heights_count: 2,
            syncing: false,
            mine_behind: false,
            catchup_ok: true,
            fork_ok: true,
            fresh_view_effective_ok: true,
            consensus_context_ready: true,
            ready_streak: 1,
        });
        assert!(!unstable_runtime.runtime_sync_converged);
        assert!(!unstable_runtime.transition_ready_candidate);
        assert_eq!(unstable_runtime.next_phase, P2pBootPhase::RestartCatchup);
        assert_eq!(unstable_runtime.next_ready_streak, 0);

        let unstable_consensus = runtime_boot_phase_step(RuntimeBootPhaseStep {
            phase: P2pBootPhase::RestartCatchup,
            connected: 2,
            multi_validator: true,
            require_hello_ok_for_runtime: true,
            hello_ok_count: 1,
            peer_heights_count: 2,
            syncing: false,
            mine_behind: false,
            catchup_ok: true,
            fork_ok: true,
            fresh_view_effective_ok: true,
            consensus_context_ready: false,
            ready_streak: 1,
        });
        assert!(unstable_consensus.runtime_sync_converged);
        assert!(!unstable_consensus.transition_ready_candidate);
        assert_eq!(unstable_consensus.next_phase, P2pBootPhase::RestartCatchup);
        assert_eq!(unstable_consensus.next_ready_streak, 0);
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn runtime_actor_cold_start_bootstrap_rearms_and_reaches_steady_state_over_live_p2p() {
        let _lock = test_process_lock();
        std::env::set_var("NEWGEN_ALLOW_KEYGEN", "1");
        std::env::set_var("NEWGEN_KEYSTORE_PASSPHRASE", "test-passphrase");
        std::env::remove_var("NEWGEN_KEYSTORE_PASSPHRASE_FILE");
        std::env::remove_var("NEWGEN_CONFIG_DIR");

        let port_a = pick_unused_port();
        let port_b = pick_unused_port();

        let paths_a = make_node_paths("p2p_actor_boot_a");
        let paths_b = make_node_paths("p2p_actor_boot_b");
        let (storage_a, chain_a) = build_runtime_bootstrap_test_runtime("p2p_actor_boot_chain_a");
        let (storage_b, chain_b) = build_runtime_bootstrap_test_runtime("p2p_actor_boot_chain_b");
        // Test-only fixture: build a live tip at height 4 and include it in the
        // advertised bootstrap snapshot. This keeps the actor-level test focused
        // on live P2P snapshot discovery/fetch/import/rearm/steady-state without
        // forcing RR catch-up to validate a synthetic block through the full
        // production consensus path.
        append_live_tip_block_to_runtime(&storage_a, &chain_a, 4);
        write_bootstrap_snapshot_bundle(&paths_a, &storage_a, 4);

        std::env::set_var(
            "NEWGEN_KEYSTORE_PATH",
            paths_a.config_dir.join("secrets").join("keystore.json"),
        );
        let handle_a = start_p2p_node(
            port_a,
            None,
            "TEST_A".to_string(),
            Arc::new(Mutex::new(PeerReputationManager::new(
                ReputationConfig::default(),
            ))),
            chain_a.clone(),
            Arc::new(Mutex::new(Mempool::new())),
            paths_a.clone(),
            false,
            PeerBook::new(),
            P2pBootPhase::SteadyState,
        )
        .await
        .unwrap();

        std::env::set_var(
            "NEWGEN_KEYSTORE_PATH",
            paths_b.config_dir.join("secrets").join("keystore.json"),
        );
        let mempool_b = Arc::new(Mutex::new(Mempool::new()));
        let handle_b = start_p2p_node(
            port_b,
            Some(format!("/ip4/127.0.0.1/tcp/{}", port_a)),
            "TEST_B".to_string(),
            Arc::new(Mutex::new(PeerReputationManager::new(
                ReputationConfig::default(),
            ))),
            chain_b.clone(),
            mempool_b.clone(),
            paths_b.clone(),
            false,
            PeerBook::new(),
            P2pBootPhase::ColdStartSnapshot,
        )
        .await
        .unwrap();

        // Actor-level cold-start readiness: requires a live bootstrap connection plus a real
        // semantic snapshot signal (Hello advert / RRv3 path), not just a boolean helper call.
        // On slower CI/Windows hosts peer discovery and advert propagation can lag behind the
        // actor startup by a few ticks, so first wait for the bootstrap peer to become visible
        // to the runtime selector and only then await the semantic readiness gate.
        let peer_list_deadline = tokio::time::Instant::now() + Duration::from_secs(45);
        loop {
            let (tx, rx) = tokio::sync::oneshot::channel();
            send_ctrl(
                &handle_b.ctrl,
                P2pControl::ListBootstrapSnapshotPeers {
                    height_opt: Some(4),
                    response: tx,
                },
            )
            .await;
            let peers = tokio::time::timeout(Duration::from_secs(1), rx)
                .await
                .expect("bootstrap peer list timeout")
                .expect("bootstrap peer list dropped");
            if !peers.is_empty() {
                break;
            }
            assert!(
                tokio::time::Instant::now() < peer_list_deadline,
                "runtime bootstrap peer discovery did not observe any eligible snapshot peer before timeout"
            );
            tokio::time::sleep(Duration::from_millis(200)).await;
        }
        let (ready_tx, ready_rx) = tokio::sync::oneshot::channel();
        send_ctrl(
            &handle_b.ctrl,
            P2pControl::AwaitBootstrapReady {
                height_opt: Some(4),
                timeout_ms: 60_000,
                response: ready_tx,
            },
        )
        .await;
        let ready = tokio::time::timeout(Duration::from_secs(65), ready_rx)
            .await
            .expect("await bootstrap readiness timeout")
            .expect("await bootstrap readiness dropped");
        assert!(
            ready.is_ok(),
            "cold-start bootstrap readiness must become ready over the live actor loop: {ready:?}"
        );

        // End-to-end bootstrap/import/rearm path over the real runtime actor orchestration.
        let snapshot_dir = paths_b.snapshots_dir.join("import_runtime_bundle");
        let expected_genesis_hash = {
            let g = chain_b.lock().unwrap_or_else(|e| e.into_inner());
            g.genesis_hash.clone()
        };
        let cfg = crate::state_sync::StateSyncConfig {
            chain_id: crate::chain_identity::chain_id().to_string(),
            expected_genesis_hash,
            ..crate::state_sync::StateSyncConfig::default()
        };
        let meta = crate::state_sync::fetch_snapshot_v2_bundle_via_runtime_ctrl(
            handle_b.ctrl.clone(),
            &snapshot_dir,
            Some(4),
            cfg,
        )
        .await
        .expect("runtime snapshot bundle fetch must succeed");
        assert_eq!(meta.height, 4);
        assert!(
            snapshot_dir.join("meta.json").exists(),
            "bundle fetch must materialize meta.json"
        );
        assert!(
            snapshot_dir.join("chunks").exists(),
            "bundle fetch must materialize chunks dir"
        );

        {
            let g = chain_b.lock().unwrap_or_else(|e| e.into_inner());
            assert!(!g.runtime_bootstrap_complete);
        }

        let security_policy = Arc::new(crate::security_policy::SecurityPolicy::default());
        crate::state_sync::import_snapshot_v2_bundle_into_live_runtime_and_rearm(
            storage_b.clone(),
            &snapshot_dir,
            &chain_b,
            &mempool_b,
            &security_policy,
            &handle_b.ctrl,
        )
        .await
        .expect("import/apply/rearm path must succeed over runtime orchestration");

        // StateSyncApplied intentionally clears runtime hello/peer-height/bootstrap advert caches.
        // Before asserting steady-state again, wait until the live actor loop rediscovers at least
        // one eligible bootstrap peer after the rearm so the test is coupled to real semantic
        // bootstrap signals instead of a transient local flag.
        let rearm_peer_list_deadline = tokio::time::Instant::now() + Duration::from_secs(45);
        loop {
            let (tx, rx) = tokio::sync::oneshot::channel();
            send_ctrl(
                &handle_b.ctrl,
                P2pControl::ListBootstrapSnapshotPeers {
                    height_opt: Some(4),
                    response: tx,
                },
            )
            .await;
            let peers = tokio::time::timeout(Duration::from_secs(1), rx)
                .await
                .expect("post-rearm bootstrap peer list timeout")
                .expect("post-rearm bootstrap peer list dropped");
            if !peers.is_empty() {
                break;
            }
            assert!(
                tokio::time::Instant::now() < rearm_peer_list_deadline,
                "runtime bootstrap peer discovery did not re-observe any eligible snapshot peer after StateSyncApplied rearm before timeout"
            );
            tokio::time::sleep(Duration::from_millis(200)).await;
        }

        wait_until(Duration::from_secs(150), || {
            let g = chain_b.lock().unwrap_or_else(|e| e.into_inner());
            g.runtime_sync_caught_up
                && g.runtime_bootstrap_complete
                && g.runtime_consensus_bootstrap_ready_for_next_height()
                    .is_ok()
        })
        .await;

        {
            let g = chain_b.lock().unwrap_or_else(|e| e.into_inner());
            let bootstrap_status = g.runtime_consensus_bootstrap_status_for_next_height_view();
            assert!(
                g.runtime_sync_caught_up,
                "runtime actor must converge after RestartCatchup over the live loop"
            );
            assert!(
                g.runtime_bootstrap_complete,
                "runtime actor must reach SteadyState over the live loop"
            );
            assert!(
                bootstrap_status.ready,
                "runtime actor must expose a ready consensus bootstrap context after rearm: {:?}",
                bootstrap_status
            );
        }

        graceful_shutdown(&handle_b.ctrl).await;
        graceful_shutdown(&handle_a.ctrl).await;
    }

    #[test]
    fn incoming_hello_requeues_local_hello_when_peer_not_locally_confirmed() {
        let peer = PeerId::random();
        let connected_now: HashSet<PeerId> = HashSet::from([peer]);
        let mut hello_ok: HashSet<PeerId> = HashSet::new();
        let mut hello_received: HashSet<PeerId> = HashSet::new();
        let hello_sent_after_connect: HashSet<PeerId> = HashSet::from([peer]);
        let mut hello_pending: HashSet<PeerId> = HashSet::new();
        let mut last_hello_broadcast = Some(Instant::now());

        let spid = peer;
        let first_received = hello_received.insert(spid);
        let first_time = if hello_sent_after_connect.contains(&spid) {
            let promoted = promote_completed_hello_handshakes(
                &connected_now,
                &hello_received,
                &hello_sent_after_connect,
                &mut hello_pending,
                &mut hello_ok,
            );
            promoted > 0 && hello_ok.contains(&spid)
        } else {
            false
        };
        if connected_now.contains(&spid) {
            let needs_local_hello_response = first_received || !hello_ok.contains(&spid);
            if needs_local_hello_response {
                hello_pending.insert(spid);
                last_hello_broadcast = None;
            }
        }

        assert!(first_time);
        assert!(hello_ok.contains(&peer));
        assert!(hello_pending.contains(&peer));
        assert!(last_hello_broadcast.is_none());
    }

    #[test]
    fn state_sync_applied_rearm_must_not_drop_connected_hello_and_peer_height_observations() {
        let peer = PeerId::random();
        let connected_now: HashSet<PeerId> = HashSet::from([peer]);
        let mut hello_ok: HashSet<PeerId> = HashSet::from([peer]);
        let mut hello_received: HashSet<PeerId> = HashSet::from([peer]);
        let mut hello_sent_after_connect: HashSet<PeerId> = HashSet::from([peer]);
        let mut hello_pending: HashSet<PeerId> = HashSet::new();
        let mut peer_heights: HashMap<PeerId, u64> = HashMap::from([(peer, 3)]);
        let mut peer_tip_hashes: HashMap<PeerId, String> =
            HashMap::from([(peer, "tip-3".to_string())]);
        let mut peer_last_seen: HashMap<PeerId, Instant> = HashMap::from([(peer, Instant::now())]);
        let mut peer_vsh_mismatch: HashSet<PeerId> = HashSet::from([peer]);
        let mut peer_snapshot_v2: HashMap<PeerId, PeerSnapshotV2Advert> = HashMap::from([(
            peer,
            PeerSnapshotV2Advert {
                height: 3,
                meta_sha256_hex: "ab".repeat(32),
                chunks: 1,
                chunk_size: 1024,
                seen_at: Instant::now(),
            },
        )]);

        hello_ok.retain(|peer| connected_now.contains(peer));
        hello_received.retain(|peer| connected_now.contains(peer));
        hello_sent_after_connect.retain(|peer| connected_now.contains(peer));
        hello_pending.clear();
        hello_pending.extend(connected_now.iter().copied());
        peer_heights.retain(|peer, _| connected_now.contains(peer));
        peer_tip_hashes.retain(|peer, _| connected_now.contains(peer));
        peer_snapshot_v2.clear();
        peer_last_seen.retain(|peer, _| connected_now.contains(peer));
        peer_vsh_mismatch.retain(|peer| connected_now.contains(peer));

        assert!(hello_ok.contains(&peer));
        assert!(hello_received.contains(&peer));
        assert!(hello_sent_after_connect.contains(&peer));
        assert!(hello_pending.contains(&peer));
        assert_eq!(peer_heights.get(&peer), Some(&3));
        assert_eq!(
            peer_tip_hashes.get(&peer).map(String::as_str),
            Some("tip-3")
        );
        assert!(peer_last_seen.contains_key(&peer));
        assert!(peer_vsh_mismatch.contains(&peer));
        assert!(peer_snapshot_v2.is_empty());
    }

    #[test]
    fn pulse_light_fork_probe_requires_live_sync_hello_ok_no_sync_and_cooldown() {
        let pid = PeerId::random();
        let policy = P2PPolicy::default();
        let now = Instant::now();
        let mut last = HashMap::new();
        assert!(!can_trigger_pulse_light_fork_probe(
            P2pBootPhase::ColdStartSnapshot,
            true,
            None,
            None,
            &last,
            pid,
            now,
            &policy,
        ));
        assert!(!can_trigger_pulse_light_fork_probe(
            P2pBootPhase::RestartCatchup,
            true,
            None,
            None,
            &last,
            pid,
            now,
            &policy,
        ));
        assert!(!can_trigger_pulse_light_fork_probe(
            P2pBootPhase::SteadyState,
            false,
            None,
            None,
            &last,
            pid,
            now,
            &policy,
        ));
        assert!(can_trigger_pulse_light_fork_probe(
            P2pBootPhase::SteadyState,
            true,
            None,
            None,
            &last,
            pid,
            now,
            &policy,
        ));
        last.insert(pid, now);
        assert!(!can_trigger_pulse_light_fork_probe(
            P2pBootPhase::SteadyState,
            true,
            None,
            None,
            &last,
            pid,
            now,
            &policy,
        ));
    }

