    #[test]
    fn runtime_telemetry_v234_skips_all_non_operational_telemetry_until_candidate() {
        let peer = PeerId::random();
        let recovery: HashSet<PeerId> = HashSet::from([peer]);
        let empty: HashSet<PeerId> = HashSet::new();

        assert!(runtime_telemetry_should_skip_non_operational_v234(
            Some(peer),
            &recovery,
            0,
            false,
            false,
            false,
        ));
        assert!(runtime_telemetry_should_skip_non_operational_v234(
            Some(peer),
            &empty,
            0,
            false,
            false,
            false,
        ));
        // V235/V261: exact regression case from D local recovery. A validator
        // peer may have height > 0 and no longer be in the transient recovery
        // set, but caught=false or boot=false must still be fail-closed.
        // p2p_ready_for_mining is intentionally not an admission precondition:
        // it is derived from operational peer scope and would otherwise create
        // a self-only readiness deadlock on clean A/B/C restarts.
        assert!(runtime_telemetry_should_skip_non_operational_v234(
            Some(peer),
            &empty,
            10,
            false,
            true,
            false,
        ));
        assert!(runtime_telemetry_should_skip_non_operational_v234(
            Some(peer),
            &empty,
            10,
            true,
            false,
            true,
        ));
        assert!(!runtime_telemetry_should_skip_non_operational_v234(
            Some(peer),
            &empty,
            10,
            true,
            true,
            false,
        ));
        assert!(runtime_telemetry_should_skip_non_operational_v234(
            Some(peer),
            &recovery,
            10,
            false,
            true,
            false,
        ));
        assert!(runtime_telemetry_should_skip_non_operational_v234(
            Some(peer),
            &recovery,
            10,
            true,
            true,
            true,
        ));
        assert!(runtime_telemetry_should_skip_non_operational_v234(
            None, &empty, 10, true, true, true,
        ));
        assert!(runtime_telemetry_should_skip_non_operational_v234(
            Some(peer),
            &recovery,
            10,
            true,
            true,
            true,
        ));
        assert!(!runtime_telemetry_should_skip_non_operational_v234(
            Some(peer),
            &empty,
            10,
            true,
            true,
            true,
        ));
    }

    #[test]
    fn peer_lifecycle_v236_requires_persistent_ready_telemetry_before_operational() {
        let peer = PeerId::random();
        let expected_vsh = "ab".repeat(32);
        let now = Instant::now();
        let connected: HashSet<PeerId> = HashSet::from([peer]);
        let recovery: HashSet<PeerId> = HashSet::new();
        let hello_ok: HashSet<PeerId> = HashSet::from([peer]);
        let mut heights = HashMap::new();
        heights.insert(peer, 50_700);
        let mut registry: HashMap<PeerId, PeerLifecycleObservationV236> = HashMap::new();
        let mut candidates: HashMap<PeerId, PeerRuntimeOperationalCandidateV236> = HashMap::new();

        // V236: hello_ok + height > 0 is still not Operational. Runtime-ready
        // telemetry and lifecycle stability are mandatory.
        let operational = runtime_operational_peer_scope_v236(
            P2pBootPhase::SteadyState,
            &connected,
            &recovery,
            &hello_ok,
            &heights,
            &candidates,
            &mut registry,
            &expected_vsh,
            true,
            now,
        );
        assert!(operational.is_empty());
        assert_ne!(
            registry.get(&peer).map(|obs| obs.state),
            Some(PeerLifecycleStateV223::Operational)
        );

        assert!(runtime_note_operational_candidate_telemetry_v236(
            &mut candidates,
            &recovery,
            peer,
            50_700,
            &expected_vsh,
            &expected_vsh,
            Some(1),
            Some(&"00".repeat(32)),
            true,
            true,
            true,
            true,
            now,
        ));

        let first = runtime_operational_peer_scope_v236(
            P2pBootPhase::SteadyState,
            &connected,
            &recovery,
            &hello_ok,
            &heights,
            &candidates,
            &mut registry,
            &expected_vsh,
            true,
            now + Duration::from_secs(1),
        );
        assert!(first.is_empty());
        assert_eq!(
            registry.get(&peer).map(|obs| obs.state),
            Some(PeerLifecycleStateV223::OperationalCandidate)
        );

        let second = runtime_operational_peer_scope_v236(
            P2pBootPhase::SteadyState,
            &connected,
            &recovery,
            &hello_ok,
            &heights,
            &candidates,
            &mut registry,
            &expected_vsh,
            true,
            now + Duration::from_secs(2),
        );
        assert!(second.contains(&peer));
        assert_eq!(
            registry.get(&peer).map(|obs| obs.state),
            Some(PeerLifecycleStateV223::Operational)
        );
    }

    #[test]
    fn peer_lifecycle_v261_admits_booted_caught_peers_before_p2p_ready_gate() {
        let peers = [PeerId::random(), PeerId::random(), PeerId::random()];
        let expected_vsh = "ab".repeat(32);
        let finalized_hash = "cd".repeat(32);
        let now = Instant::now();
        let connected: HashSet<PeerId> = peers.iter().copied().collect();
        let recovery: HashSet<PeerId> = HashSet::new();
        let hello_ok: HashSet<PeerId> = peers.iter().copied().collect();
        let heights: HashMap<PeerId, u64> =
            peers.iter().copied().map(|p| (p, 51_201_u64)).collect();
        let mut registry: HashMap<PeerId, PeerLifecycleObservationV236> = HashMap::new();
        let mut candidates: HashMap<PeerId, PeerRuntimeOperationalCandidateV236> = HashMap::new();

        for peer in peers {
            assert!(runtime_note_operational_candidate_telemetry_v236(
                &mut candidates,
                &recovery,
                peer,
                51_201,
                &expected_vsh,
                &expected_vsh,
                Some(51_199),
                Some(&finalized_hash),
                true,
                true,
                true,
                false,
                now,
            ));
        }

        let first = runtime_operational_peer_scope_v236(
            P2pBootPhase::SteadyState,
            &connected,
            &recovery,
            &hello_ok,
            &heights,
            &candidates,
            &mut registry,
            &expected_vsh,
            true,
            now + Duration::from_secs(1),
        );
        assert!(
            first.is_empty(),
            "V236 still requires one stable observation interval"
        );

        let second = runtime_operational_peer_scope_v236(
            P2pBootPhase::SteadyState,
            &connected,
            &recovery,
            &hello_ok,
            &heights,
            &candidates,
            &mut registry,
            &expected_vsh,
            true,
            now + Duration::from_secs(2),
        );
        assert_eq!(second.len(), 3, "A/B/C must not deadlock at ready_count=1 when all advertise p2p=false before peer admission");
    }

