    #[test]
    fn peer_lifecycle_v238_promotes_only_persisted_ready_finalized_peers_and_excludes_recovery_d() {
        let a = PeerId::random();
        let b = PeerId::random();
        let c = PeerId::random();
        let d_recovery = PeerId::random();
        let expected_vsh = "ab".repeat(32);
        let finalized_hash = "cd".repeat(32);
        let now = Instant::now();

        let connected: HashSet<PeerId> = HashSet::from([a, b, c, d_recovery]);
        let recovery: HashSet<PeerId> = HashSet::from([d_recovery]);
        let hello_ok: HashSet<PeerId> = HashSet::from([a, b, c, d_recovery]);
        let heights: HashMap<PeerId, u64> = HashMap::from([
            (a, 50_700_u64),
            (b, 50_700_u64),
            (c, 50_700_u64),
            (d_recovery, 50_700_u64),
        ]);
        let mut registry: HashMap<PeerId, PeerLifecycleObservationV236> = HashMap::new();
        let mut candidates: HashMap<PeerId, PeerRuntimeOperationalCandidateV236> = HashMap::new();

        // The old/transient V223 scope must fail closed even though every peer
        // has hello_ok + height>0. It lacks persistent signed-ready proof.
        let legacy = runtime_operational_peer_scope_v223(
            P2pBootPhase::SteadyState,
            &connected,
            &recovery,
            &hello_ok,
            &heights,
            true,
        );
        assert!(legacy.is_empty());

        // D is recovery: even valid-looking telemetry cannot make it a candidate.
        assert!(!runtime_note_operational_candidate_telemetry_v236(
            &mut candidates,
            &recovery,
            d_recovery,
            50_700,
            &expected_vsh,
            &expected_vsh,
            Some(50_699),
            Some(&finalized_hash),
            true,
            true,
            true,
            true,
            now,
        ));

        for peer in [a, b, c] {
            assert!(runtime_note_operational_candidate_telemetry_v236(
                &mut candidates,
                &recovery,
                peer,
                50_700,
                &expected_vsh,
                &expected_vsh,
                Some(50_699),
                Some(&finalized_hash),
                true,
                true,
                true,
                true,
                now,
            ));
        }

        let first_tick = runtime_operational_peer_scope_v236(
            P2pBootPhase::SteadyState,
            &connected,
            &recovery,
            &hello_ok,
            &heights,
            &candidates,
            &mut registry,
            &expected_vsh,
            true,
            now + Duration::from_secs(1),
        );
        assert!(first_tick.is_empty());
        for peer in [a, b, c] {
            assert_eq!(
                registry.get(&peer).map(|obs| obs.state),
                Some(PeerLifecycleStateV223::OperationalCandidate)
            );
        }
        assert_eq!(
            registry.get(&d_recovery).map(|obs| obs.state),
            Some(PeerLifecycleStateV223::SnapshotServingClient)
        );

        let second_tick = runtime_operational_peer_scope_v236(
            P2pBootPhase::SteadyState,
            &connected,
            &recovery,
            &hello_ok,
            &heights,
            &candidates,
            &mut registry,
            &expected_vsh,
            true,
            now + Duration::from_secs(2),
        );
        assert_eq!(second_tick.len(), 3);
        assert!(second_tick.contains(&a));
        assert!(second_tick.contains(&b));
        assert!(second_tick.contains(&c));
        assert!(!second_tick.contains(&d_recovery));
    }

