    #[test]
    fn snapshot_priority_trigger_v242_binds_source_peer_to_its_operational_height() {
        clear_state_sync_supervisor_handle_for_tests();
        let now = Instant::now();
        let a_operational = PeerId::random();
        let d_recovery = PeerId::random();

        let mut registry: HashMap<PeerId, PeerLifecycleObservationV236> = HashMap::new();
        let mut a_obs = PeerLifecycleObservationV236::new(now);
        a_obs.state = PeerLifecycleStateV223::Operational;
        registry.insert(a_operational, a_obs);
        let mut d_obs = PeerLifecycleObservationV236::new(now);
        d_obs.state = PeerLifecycleStateV223::RestartCatchup;
        registry.insert(d_recovery, d_obs);

        let peer_heights: HashMap<PeerId, u64> =
            HashMap::from([(a_operational, 50_720_u64), (d_recovery, 90_000_u64)]);
        let mut tracker = CatchupProgressTracker::default();

        assert!(
            !snapshot_priority_trigger_state_sync_recovery_source_bound_v242(
                &mut tracker,
                P2pBootPhase::SteadyState,
                50_700,
                90_000,
                "test_mismatched_global_height_v242",
                Some(&a_operational),
                &peer_heights,
                &registry,
            )
        );
        assert!(
            !tracker.state_sync_pending(),
            "V242 must reject a global/recovery height even when an Operational source peer is supplied"
        );

        assert!(
            !snapshot_priority_trigger_state_sync_recovery_source_bound_v242(
                &mut tracker,
                P2pBootPhase::SteadyState,
                50_700,
                90_000,
                "test_recovery_source_v242",
                Some(&d_recovery),
                &peer_heights,
                &registry,
            )
        );
        assert!(
            !tracker.state_sync_pending(),
            "V242 must reject non-Operational recovery source peers"
        );

        assert!(
            !snapshot_priority_trigger_state_sync_recovery_source_bound_v242(
                &mut tracker,
                P2pBootPhase::SteadyState,
                50_700,
                50_720,
                "test_bound_operational_source_no_supervisor_v242",
                Some(&a_operational),
                &peer_heights,
                &registry,
            )
        );
        assert!(
            !tracker.state_sync_pending(),
            "with no supervisor registered this still returns false, but the source/height boundary was accepted"
        );
    }

