    #[test]
    fn local_consensus_wedged_v243_requires_source_height_to_cover_blocked_next() {
        let now = Instant::now();
        let a_operational = PeerId::random();
        let d_recovery = PeerId::random();
        let mut registry: HashMap<PeerId, PeerLifecycleObservationV236> = HashMap::new();

        let mut a_obs = PeerLifecycleObservationV236::new(now);
        a_obs.state = PeerLifecycleStateV223::Operational;
        registry.insert(a_operational, a_obs);
        let mut d_obs = PeerLifecycleObservationV236::new(now);
        d_obs.state = PeerLifecycleStateV223::RestartCatchup;
        registry.insert(d_recovery, d_obs);

        let fault = LocalConsensusBootstrapFaultView {
            class: crate::blockchain::LocalConsensusBootstrapFaultClass::SnapshotContextInvalid,
            scope: "snapshot_context".to_string(),
            detail: Some("test".to_string()),
        };
        let peer_heights: HashMap<PeerId, u64> =
            HashMap::from([(a_operational, 50_720_u64), (d_recovery, 90_000_u64)]);

        let too_high = LocalSyncRetryBlock::from_fault(
            50_721,
            Some(50_721),
            Some(a_operational),
            fault.clone(),
        );
        assert!(!local_consensus_wedged_source_operational_bound_v245(
            Some(&too_high),
            &peer_heights,
            &registry,
            "test_source_too_low_v243",
        ));

        let recovery_source =
            LocalSyncRetryBlock::from_fault(50_721, Some(50_721), Some(d_recovery), fault.clone());
        assert!(!local_consensus_wedged_source_operational_bound_v245(
            Some(&recovery_source),
            &peer_heights,
            &registry,
            "test_recovery_source_v243",
        ));

        let valid =
            LocalSyncRetryBlock::from_fault(50_720, Some(50_700), Some(a_operational), fault);
        assert!(local_consensus_wedged_source_operational_bound_v245(
            Some(&valid),
            &peer_heights,
            &registry,
            "test_bound_source_v243",
        ));
    }

