    #[test]
    fn runtime_snapshot_serve_session_v249_tracks_attempt_encoded_sent_and_implicit_ack() {
        let peer = PeerId::random();
        let height = 77;
        let sessions = test_runtime_snapshot_session_v233(peer, height);
        let now = Instant::now();

        let s0 = runtime_snapshot_mark_serve_session_chunk_request_started_v249(
            &sessions, peer, height, 0, now,
        )
        .expect("session should exist");
        assert_eq!(s0.state, RuntimeSnapshotServeSessionStateV233::Progressing);
        assert_eq!(s0.last_attempt_started_chunk, Some(0));
        assert_eq!(s0.last_encoded_chunk, None);
        assert_eq!(s0.last_response_sent_chunk, None);
        assert_eq!(s0.last_successful_chunk, None);
        assert_eq!(s0.last_acknowledged_chunk, None);
        assert_eq!(s0.last_chunk_served, None);
        assert_eq!(s0.bytes_served, 0);

        let s0_encoded = runtime_snapshot_mark_serve_session_chunk_response_encoded_v249(
            &sessions,
            peer,
            height,
            0,
            1024,
            1400,
            now + Duration::from_millis(10),
        )
        .expect("session should still exist");
        assert_eq!(s0_encoded.last_encoded_chunk, Some(0));
        assert_eq!(s0_encoded.bytes_encoded, 1400);
        assert_eq!(s0_encoded.last_response_sent_chunk, None);
        assert_eq!(s0_encoded.last_successful_chunk, None);
        assert_eq!(s0_encoded.bytes_served, 0);

        let s0_sent = runtime_snapshot_mark_serve_session_chunk_response_sent_v249(
            &sessions,
            peer,
            height,
            0,
            1024,
            1400,
            true,
            true,
            now + Duration::from_millis(20),
        )
        .expect("session should still exist");
        assert_eq!(s0_sent.last_response_sent_chunk, Some(0));
        assert_eq!(s0_sent.last_chunk_served, Some(0));
        assert_eq!(s0_sent.bytes_served, 1024);
        assert_eq!(s0_sent.bytes_sent, 1024);
        assert_eq!(s0_sent.last_successful_chunk, None);
        assert_eq!(s0_sent.last_acknowledged_chunk, None);

        let s1 = runtime_snapshot_mark_serve_session_chunk_request_started_v249(
            &sessions,
            peer,
            height,
            1,
            now + Duration::from_secs(1),
        )
        .expect("session should still exist");
        assert_eq!(s1.last_attempt_started_chunk, Some(1));
        assert_eq!(s1.last_successful_chunk, Some(0));
        assert_eq!(s1.last_acknowledged_chunk, Some(0));
        assert_eq!(s1.consecutive_failures, 0);

        let _ = runtime_snapshot_mark_serve_session_chunk_response_encoded_v249(
            &sessions,
            peer,
            height,
            1,
            2048,
            2600,
            now + Duration::from_secs(1) + Duration::from_millis(10),
        );
        let s1_sent = runtime_snapshot_mark_serve_session_chunk_response_sent_v249(
            &sessions,
            peer,
            height,
            1,
            2048,
            2600,
            true,
            true,
            now + Duration::from_secs(1) + Duration::from_millis(20),
        )
        .expect("session should still exist");
        assert_eq!(s1_sent.last_response_sent_chunk, Some(1));
        assert_eq!(s1_sent.bytes_served, 3072);
        assert_eq!(s1_sent.last_successful_chunk, Some(0));

        let s2 = runtime_snapshot_mark_serve_session_chunk_request_started_v249(
            &sessions,
            peer,
            height,
            2,
            now + Duration::from_secs(2),
        )
        .expect("session should still exist");
        assert_eq!(s2.last_successful_chunk, Some(1));
        assert_eq!(s2.last_acknowledged_chunk, Some(1));
    }

