    #[test]
    fn snapshot_served_client_v289_high_height_restartcatchup_stays_quarantined() {
        let peer = PeerId::random();
        let expected_vsh = "vsh-v289".to_string();
        let finalized_hash = "finalized-v289".to_string();
        let now = Instant::now();
        let mut clients = HashMap::new();

        runtime_snapshot_mark_served_bootstrap_client_v289(&mut clients, peer, now);
        assert!(clients.contains_key(&peer));

        let active = HashSet::new();
        let pending = HashMap::new();
        let retry = VecDeque::new();
        let mut recovery = runtime_recovery_non_operational_peers_v264(
            &active,
            &pending,
            &retry,
            &mut clients,
            now,
        );
        assert!(recovery.contains(&peer));

        // Exact D failure mode after snapshot apply: high height but still
        // RestartCatchup/not caught. The served-snapshot marker must keep it
        // out of operational readiness even though finalized evidence is
        // compatible and height is non-genesis.
        assert!(
            runtime_note_snapshot_bootstrap_client_into_recovery_scope_v265(
                &mut clients,
                &mut recovery,
                peer,
                52_255,
                false,
                false,
                now,
            )
        );
        assert!(recovery.contains(&peer));

        let mut candidates = HashMap::new();
        assert!(!runtime_note_operational_candidate_telemetry_v236(
            &mut candidates,
            &recovery,
            peer,
            52_255,
            &expected_vsh,
            &expected_vsh,
            Some(52_254),
            Some(&finalized_hash),
            true,
            false,
            false,
            false,
            now,
        ));
        assert!(!candidates.contains_key(&peer));

        let connected = HashSet::from([peer]);
        let hello_ok = HashSet::from([peer]);
        let heights = HashMap::from([(peer, 52_255_u64)]);
        let mut registry = HashMap::new();
        let operational = runtime_operational_peer_scope_v236(
            P2pBootPhase::SteadyState,
            &connected,
            &recovery,
            &hello_ok,
            &heights,
            &candidates,
            &mut registry,
            &expected_vsh,
            true,
            now,
        );
        assert!(operational.is_empty());

        assert!(
            !runtime_note_snapshot_bootstrap_client_into_recovery_scope_v265(
                &mut clients,
                &mut recovery,
                peer,
                52_256,
                true,
                true,
                now + Duration::from_secs(1),
            )
        );
        assert!(!recovery.contains(&peer));
    }

    #[test]
    fn recovery_quarantine_v289_clears_only_recovery_peer_caches() {
        let recovery_peer = PeerId::random();
        let healthy_peer = PeerId::random();
        let now = Instant::now();
        let mut recovery = HashSet::new();
        recovery.insert(recovery_peer);

        let mut runtime_candidates = HashMap::from([
            (
                recovery_peer,
                PeerRuntimeOperationalCandidateV236 {
                    height: 52_255,
                    validator_set_hash: "vsh".to_string(),
                    finalized_height: 52_254,
                    finalized_hash: "fh".to_string(),
                    observed_at: now,
                },
            ),
            (
                healthy_peer,
                PeerRuntimeOperationalCandidateV236 {
                    height: 52_260,
                    validator_set_hash: "vsh".to_string(),
                    finalized_height: 52_259,
                    finalized_hash: "fh2".to_string(),
                    observed_at: now,
                },
            ),
        ]);
        let mut catchup_candidates = HashMap::from([
            (
                recovery_peer,
                PeerRuntimeCatchupCandidateV287 {
                    height: 52_255,
                    validator_set_hash: "vsh".to_string(),
                    finalized_height: 52_254,
                    finalized_hash: "fh".to_string(),
                    runtime_sync_caught_up: true,
                    runtime_bootstrap_complete: true,
                    observed_at: now,
                },
            ),
            (
                healthy_peer,
                PeerRuntimeCatchupCandidateV287 {
                    height: 52_260,
                    validator_set_hash: "vsh".to_string(),
                    finalized_height: 52_259,
                    finalized_hash: "fh2".to_string(),
                    runtime_sync_caught_up: true,
                    runtime_bootstrap_complete: true,
                    observed_at: now,
                },
            ),
        ]);
        let mut lifecycle = HashMap::from([
            (recovery_peer, PeerLifecycleObservationV236::new(now)),
            (healthy_peer, PeerLifecycleObservationV236::new(now)),
        ]);

        runtime_recovery_quarantine_peer_caches_v289(
            &recovery,
            &mut runtime_candidates,
            &mut catchup_candidates,
            &mut lifecycle,
        );

        assert!(!runtime_candidates.contains_key(&recovery_peer));
        assert!(!catchup_candidates.contains_key(&recovery_peer));
        assert!(!lifecycle.contains_key(&recovery_peer));
        assert!(runtime_candidates.contains_key(&healthy_peer));
        assert!(catchup_candidates.contains_key(&healthy_peer));
        assert!(lifecycle.contains_key(&healthy_peer));
    }

