    #[test]
    fn restart_warm_candidate_v269_breaks_simultaneous_restart_deadlock() {
        let peer = PeerId::random();
        let expected_vsh = "vsh-restart-v269".to_string();
        let finalized_hash = "finalized-restart-v269".to_string();
        let mut candidates: HashMap<PeerId, PeerRuntimeOperationalCandidateV236> = HashMap::new();
        let recovery = HashSet::new();
        let mut registry: HashMap<PeerId, PeerLifecycleObservationV236> = HashMap::new();
        let now = Instant::now();
        let mut connected = HashSet::new();
        connected.insert(peer);
        let mut hello_ok = HashSet::new();
        hello_ok.insert(peer);
        let heights = HashMap::from([(peer, 51_266_u64)]);

        assert!(runtime_note_operational_candidate_telemetry_v236(
            &mut candidates,
            &recovery,
            peer,
            51_266,
            &expected_vsh,
            &expected_vsh,
            Some(51_263),
            Some(&finalized_hash),
            true,
            false,
            false,
            false,
            now,
        ));

        let first_tick = runtime_operational_peer_scope_v236(
            P2pBootPhase::SteadyState,
            &connected,
            &recovery,
            &hello_ok,
            &heights,
            &candidates,
            &mut registry,
            &expected_vsh,
            true,
            now + Duration::from_secs(1),
        );
        assert!(first_tick.is_empty());
        assert_eq!(
            registry.get(&peer).map(|obs| obs.state),
            Some(PeerLifecycleStateV223::OperationalCandidate),
        );

        let operational = runtime_operational_peer_scope_v236(
            P2pBootPhase::SteadyState,
            &connected,
            &recovery,
            &hello_ok,
            &heights,
            &candidates,
            &mut registry,
            &expected_vsh,
            true,
            now + Duration::from_secs(2),
        );
        assert!(operational.contains(&peer));
    }

