    #[test]
    fn peer_identity_quarantine_v292_preserves_data_plane_but_clears_consensus_caches() {
        let peer = PeerId::random();
        let now = Instant::now();
        let mut quarantined: HashMap<PeerId, Instant> = HashMap::new();
        let mut hello_ok: HashSet<PeerId> = HashSet::from([peer]);
        let mut hello_received: HashSet<PeerId> = HashSet::from([peer]);
        let mut hello_sent_after_connect: HashSet<PeerId> = HashSet::from([peer]);
        let mut hello_pending: HashSet<PeerId> = HashSet::from([peer]);
        let mut peer_vsh_mismatch: HashSet<PeerId> = HashSet::from([peer]);
        let mut peer_heights: HashMap<PeerId, u64> = HashMap::from([(peer, 52_696)]);
        let mut peer_tip_hashes: HashMap<PeerId, String> =
            HashMap::from([(peer, "tip".to_string())]);
        let mut runtime_candidates: HashMap<PeerId, PeerRuntimeOperationalCandidateV236> =
            HashMap::from([(
                peer,
                PeerRuntimeOperationalCandidateV236 {
                    height: 52_696,
                    validator_set_hash: "vsh".to_string(),
                    finalized_height: 52_695,
                    finalized_hash: "finalized".to_string(),
                    observed_at: now,
                },
            )]);
        let mut catchup_candidates: HashMap<PeerId, PeerRuntimeCatchupCandidateV287> =
            HashMap::from([(
                peer,
                PeerRuntimeCatchupCandidateV287 {
                    height: 52_696,
                    validator_set_hash: "vsh".to_string(),
                    finalized_height: 52_695,
                    finalized_hash: "finalized".to_string(),
                    runtime_sync_caught_up: false,
                    runtime_bootstrap_complete: false,
                    observed_at: now,
                },
            )]);
        let mut lifecycle_registry: HashMap<PeerId, PeerLifecycleObservationV236> =
            HashMap::from([(peer, PeerLifecycleObservationV236::new(now))]);

        runtime_peer_identity_quarantine_mark_v292(
            &mut quarantined,
            peer,
            now,
            &mut hello_ok,
            &mut hello_received,
            &mut hello_sent_after_connect,
            &mut hello_pending,
            &mut peer_vsh_mismatch,
            &mut peer_heights,
            &mut peer_tip_hashes,
            &mut runtime_candidates,
            &mut catchup_candidates,
            &mut lifecycle_registry,
        );

        assert!(runtime_peer_identity_quarantined_v292(
            &quarantined,
            &peer,
            now
        ));
        assert!(hello_ok.is_empty());
        assert!(hello_received.is_empty());
        assert!(hello_sent_after_connect.is_empty());
        assert!(hello_pending.is_empty());
        assert!(peer_vsh_mismatch.is_empty());
        assert!(peer_heights.is_empty());
        assert!(peer_tip_hashes.is_empty());
        assert!(runtime_candidates.is_empty());
        assert!(catchup_candidates.is_empty());
        assert!(lifecycle_registry.is_empty());
    }

    #[test]
    fn peer_identity_quarantine_v292_expires_or_clears_on_disconnect() {
        let peer = PeerId::random();
        let now = Instant::now();
        let mut quarantined: HashMap<PeerId, Instant> = HashMap::from([(peer, now)]);
        let connected: HashSet<PeerId> = HashSet::from([peer]);
        runtime_peer_identity_quarantine_prune_v292(&mut quarantined, &connected, now);
        assert!(quarantined.contains_key(&peer));

        let disconnected: HashSet<PeerId> = HashSet::new();
        runtime_peer_identity_quarantine_prune_v292(&mut quarantined, &disconnected, now);
        assert!(!quarantined.contains_key(&peer));
    }
